-- Petőfi Sándor összes költeményei, 2/5. rész (forrás: MEK-01006, nem jogvédett)
insert into public.classic_poems (key,poet_id,title,body,excerpt,written,year,section,themes,seasons,is_excerpt,sort,source) values
('petofi-1844-184408-115','petofi','A természet vadvirága','Mit ugattok, mit haraptok
Engemet, hitvány ebek!
Torkotokba, hogy megfúltok,
Oly kemény koncot vetek.
Nyirbáljatok üvegházak
Satnya sarjadékain;
A korláttalan természet
Vadvirága vagyok én.

Nem verték belém tanítók
Bottal a költészetet,
Iskolai szabályoknak
Lelkem sosem engedett.
Támaszkodjék szabályokra,
Ki szabadban félve mén.
A korláttalan természet
Vadvirága vagyok én.

Nem virítok számotokra,
Árva finnyás kóficok!
Kiknek gyönge, kényes, romlott
Gyomra mindjárt háborog;
Van azért, ki ép izléssel
Üdvezelve jön elém.
A korláttalan természet
Vadvirága vagyok én.

Hát azért nekem örökre,
Szépen békét hagyjatok;
Ugysem sok gyümölcsü munka:
Falra borsót hánynotok.
S kedvetek ha jön kötődni,
Ugy kapkodjatok felém:
A természetnek tövíses
Vadvirága vagyok én.','Mit ugattok, mit haraptok
Engemet, hitvány ebek!
Torkotokba, hogy megfúltok,
Oly kemény koncot vetek.','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,213,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-116','petofi','Pál mester','Pál mester ilyformán okoskodott,
És félrecsapta
Szilajhetykén a kalapot:
"Eh, aki adta!
Mire való a feleség nekem?
Nélkűle szabadabb lesz életem;
Elkergetem... az lesz belőle."
És úgy tett, amiként beszéle.

Pál mester később így okoskodott,
Csakhogy nem csapta
Ő félre most a kalapot:
"Hej, aki adta!
Mégis csak kár volt elkergetnem őt;
Kezében gazdaságom egyre nőtt,
S most elpusztúl... az lesz belőle."
És úgy lett, amiként beszéle.

Pál mester ekkor így okoskodott,
És félrecsapta
Ismét hetykén a kalapot:
"Eh, aki adta!
Mi haszna minden búm és bánatom?
Ugy sincs sokam; azt is tovább adom,
Tovább adom... az lesz belőle."
És úgy tett, amiként beszéle.

Pál mester végre így okoskodott,
S szemére csapta
Keservesen a kalapot:
"Hej, aki adta!
Most már minden, de minden odavan;
Mitévő légyek? Felkössem magam?
Fel, felkötöm... az lesz belőle."
És úgy tett, amiként beszéle.','Pál mester ilyformán okoskodott,
És félrecsapta
Szilajhetykén a kalapot:
"Eh, aki adta!','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,214,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-117','petofi','Esik, esik, esik','Esik, esik, esik,
Csókeső esik;
Az én ajakamnak
Nagyon jólesik.

Az eső, az eső
Villámlással jár;
A szemed, galambom,
Villámló sugár.

Mennydörög, mennydörög
A hátunk megett;
Szaladok, galambom,
Jön az öreged.','Esik, esik, esik,
Csókeső esik;
Az én ajakamnak
Nagyon jólesik.','Pest, 1844. december',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,215,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-118','petofi','Gyere, lovam...','Gyere, lovam, hadd tegyem rád nyergem!
Galambomnál kell még ma teremnem.
A kengyelbe most teszem ballábam,
De lelkem már a galambomnál van.

Száll a madár, tán párjához siet;
Sebesen száll, el is hagyott minket.
Érjük utol szaporán, jó lovam,
A párját ő sem szereti jobban.','Gyere, lovam, hadd tegyem rád nyergem!
Galambomnál kell még ma teremnem.
A kengyelbe most teszem ballábam,
De lelkem már a galambomnál van.','Pest, 1844. december',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,216,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-119','petofi','A hegyoldalt venyigesor takarja...','A hegyoldalt venyigesor takarja...
Megvert engem az uristen haragja;
Avval vert meg engemet,
Hogy venyigét teremtett,
Venyigére gerezdet... gerezdet!

Apám után szép vagyonhoz jutottam,
Vagyonomat egy fillérig elittam;
Most napszámra dolgozom,
Ha napszámom kikapom,
Kocsmába mék, eliszom... eliszom!','A hegyoldalt venyigesor takarja...
Megvert engem az uristen haragja;
Avval vert meg engemet,
Hogy venyigét teremtett,','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,217,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-120','petofi','János gazda','János gazda, derék gazda,
Nincsen párja hat faluba'';
Csak egy a bibéje,
Hogy soha sincs pénze.

Széles, hosszú szántóföldje,
Sok gabona terem benne,
Vásárra jár véle,
Még sincs soha pénze.

Nem kóborol a kocsmába,
Kocsmárosra nem kiáltja:
Hej, bort az iccébe!
Még sincs soha pénze.

Felesége szép, takaros,
Legényekre nem haragos,
Kivált béresére...
Hát ezért nincs pénze.','János gazda, derék gazda,
Nincsen párja hat faluba'';
Csak egy a bibéje,
Hogy soha sincs pénze.','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,218,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-121','petofi','Az öregúr','Az öregúrnak élete
Szánandó gyötrelem,
Veséig gyötri a szegényt
Féltékeny szerelem.

Unokaöccse oly gonosz,
S szép, ifju a neje;
Unokaöccse ver szöget
Megőszült fejibe.

Míg nőtlen volt: terhére nem
Esett a hivatal,
Nyugodtan, híven végezé;
De most majd belehal.

Míg nőtlen volt: barátinál
El-elkártyázgatott,
De mostan éjszakázni fél...
Keserves állapot!

Míg nőtlen volt: álom között
Folyának éjei;
De most az öregúr szemét
Behúnyni sem meri.

Pedig, pedig, szegény öreg,
Féltés hiába bánt;
Öcséd nődet nem szereti...
Hanem a szobalyányt.','Az öregúrnak élete
Szánandó gyötrelem,
Veséig gyötri a szegényt
Féltékeny szerelem.','Pest, 1844. december',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,219,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-122','petofi','Szerelem, szerelem...','Szerelem, szerelem,
Keserű szerelem!
Miért bántál olyan
Kegyetlenül velem?
Te voltál szivemben
Első és utósó,
Nemsokára készül
Számomra koporsó.

Elmegyek az ácshoz,
Fejfát csináltatok,
Egyszerű fejfámra
Csak egy sort íratok;
Fekete betűkkel
Ez lesz írva rája:
"Itt hervad a hűség
Eltépett rózsája."','Szerelem, szerelem,
Keserű szerelem!
Miért bántál olyan
Kegyetlenül velem?','Pest, 1844. december',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,220,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-123','petofi','Fényes csillag...','Fényes csillag, mondd meg nekem,
Mért nem maradtál odafenn?
Mondd meg: arra mi ok szolgál,
Hogy az égről lefutottál?

"Csak az az ok szolgál arra,
Mert ránéztem galambodra;
Sugaramnál szebb a szeme,
Boszankodás kergetett le."','Fényes csillag, mondd meg nekem,
Mért nem maradtál odafenn?
Mondd meg: arra mi ok szolgál,
Hogy az égről lefutottál?','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,221,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-124','petofi','Boldog éjjel...','Boldog éjjel! együtt vagyok rózsámmal,
A kis kertben mulatozunk egymással;
Csendesség van, csak az ebek csaholnak,
Fenn az égen
Tündérszépen
Ragyog a hold, a csillag.

Nem jó csillag lett volna énbelőlem;
Tudja isten, nem maradnék az égen,
Nem kellene énnekem a mennyország,
Lejárnék én
Minden estén,
Kedves rózsám, tehozzád.','Boldog éjjel! együtt vagyok rózsámmal,
A kis kertben mulatozunk egymással;
Csendesség van, csak az ebek csaholnak,
Fenn az égen','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,222,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-125','petofi','Szerelem és bor','Azt mondom, amit mindig mondok:
Ne háborgassanak a gondok,
Ne háborgassanak bennünket!
Legyen vidámság, tréfa, nesz;
Ifjak vagyunk és ifjuságunk
Idő jártával odalesz.

Járjunk a szerelem kertében,
Virág ott nyílik minden lépten;
Ha meg talál tüskéje szúrni:
Illatja gyógyulást szerez.
Szeressünk! mert erőnk szeretni,
Idő jártával odalesz.

Midőn a szerelem kertében
A nap tikkasztón süt az égen:
Térjünk hüs árnyékú lugasba
A borgyümölcs tőkéihez.
Igyunk! pénzünk van, hátha pénzünk
Idő jártával odalesz.

E kép a legszebb élet képe;
Adjunk érette bút cserébe.
Mint fellegekre a szivárvány,
Reánk mosolygani fog ez,
Ha majd derengő ifjuságunk
Idő jártával odalesz.','Azt mondom, amit mindig mondok:
Ne háborgassanak a gondok,
Ne háborgassanak bennünket!
Legyen vidámság, tréfa, nesz;','Pest, 1844. december',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,223,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-126','petofi','Mit szól a bölcs?','Hm, bizony csak sok nem úgy halad,
Amint kéne, itt a nap alatt.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Tenger a pénz, melyben elsülyed
Sok hajó: elv, jellem, becsület.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Korpafőt diszít selyem kalap,
S az okos fő teng daróc alatt.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

A lét könyviből e szót "barát"
Az idők régen kivakarák.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Egyenesség, nyilt őszinteség
Rókaságnak zsákmányúl esék.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Feleséghűség járatlan út,
Rajta már csak az együgyü fut.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Igazmondás elhajított kő,
Hajító fejére visszajő.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!

Megterem sok prédikáció,
Nem igen hallgatják, bármi jó.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!','Hm, bizony csak sok nem úgy halad,
Amint kéne, itt a nap alatt.
Szikrát sem törődve szól a bölcs:
Itt van a pohár, hol a bor? tölts!','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,224,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-127','petofi','Katona vagyok én...','Katona vagyok én, kiszolgált katona,
Csak káplár sem voltam, mindig közkatona.
A katonasághoz ifjúságot vittem,
Ott maradt az, haza öregséggel jöttem.

Nagy volt pontosságom, nagy volt a hűségem,
Nem volt reám mérve csak egy büntetés sem.
Mi lett a jutalmam, mikor kiszolgáltam?
A generális megveregette vállam.','Katona vagyok én, kiszolgált katona,
Csak káplár sem voltam, mindig közkatona.
A katonasághoz ifjúságot vittem,
Ott maradt az, haza öregséggel jöttem.','Pest, 1844. december',1844,'1844',array['Haza']::text[],'{}'::text[],false,225,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-128','petofi','Nem tesz föl a lyány magában egyebet...','Nem tesz föl a lyány magában egyebet,
Csak hogy téged, csalfa legény, elfeled;
Addig feled, addig feled, csak feled,
Míg a szíve bánatában megreped.','Nem tesz föl a lyány magában egyebet,
Csak hogy téged, csalfa legény, elfeled;
Addig feled, addig feled, csak feled,
Míg a szíve bánatában megreped.','Pest, 1844. december',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,226,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-129','petofi','Részegség a hazáért','Fiuk, az isten áldjon meg,
Én is iszom, igyatok!
Én nem nézhetek vidámon
Végig elhagyott hazámon,
Csak mikor részeg vagyok!

Ekkor úgy látom hazámat,
Amint kéne lennie;
Mindenik pohár, amelynek
Habjai belém ömölnek,
Egy sebét hegeszti be.

S ha, mig részeg vagyok: boldog
Volna a hon csakugyan,
Bár örökké kéne élnem,
Fiuk, nem láthatna éngem
Soha senki józanan.','Fiuk, az isten áldjon meg,
Én is iszom, igyatok!
Én nem nézhetek vidámon
Végig elhagyott hazámon,','Pest, 1844. december',1844,'1844',array['Haza']::text[],'{}'::text[],false,227,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-130','petofi','Lant és kard','Felhős az ég hazámon,
Aligha nem lesz vész;
Csak hadd legyen, nem bánom,
Lelkem reája kész.

Lantom nagyon szeretne
Hallgatva állani,
Régóta van kezembe'',
Már kopnak húrjai.

S amott a zugban kardom
Folyvást panaszkodik:
Hiába meddig tartom,
Az ítéletnapig?...','Felhős az ég hazámon,
Aligha nem lesz vész;
Csak hadd legyen, nem bánom,
Lelkem reája kész.','Pest, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,228,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-131','petofi','A királyok ellen','Tudjuk, hogy játék kell a gyermekeknek;
Midőn a népek gyermekek valának,
Magoknak cifra ragyogó játékszert,
Bibor karszéket, s koronát csináltak,
S rányomták ezt egy fajankó fejére,
S felülteték e fajankót a székre.

S itt a királyság, ezek a királyok,
S ők, ahol ülnek, ahol fejök szédül,
Azt gondolják a kábító magasban,
Hogy uralkodnak isten kegyelmébül.
Csalatkozásban éltek, jó királyok,
Nem uraink, csak bábjaink valátok.

De nagykorú lett a világ, s a férfi
Nem gondol többé gyermekjátékával.
Le hát a biborszékekről, királyok,
És fejetekről le a koronával!
Ha nem teszitek azt le fejetekrül,
Leütjük, s majd a fej is vele gördül.

Így lesz s nem máskép. A bárd, mely Lajosnak
Párizs piacán lecsapott nyakára,
Első villáma volt a zivatarnak,
Mely rátok készül, s kitör nemsokára;
Igen, maholnap meglesz érkezése,
Nem én vagyok már első mennydörgése!

Egy rengeteg lesz a föld kereksége,
S e rengetegben vadak a királyok,
Kergetjük őket, és fegyvereinket
Szilaj gyönyörrel sütögetjük rájok,
S vérökkel fogjuk ezt az égre írni,
Hogy nem gyermek már a világ, de férfi!','Tudjuk, hogy játék kell a gyermekeknek;
Midőn a népek gyermekek valának,
Magoknak cifra ragyogó játékszert,
Bibor karszéket, s koronát csináltak,','Pest, 1844. december',1844,'1844',array['Gyermekkor']::text[],'{}'::text[],false,229,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-132','petofi','Rabhazának fia','Menjünk, menjünk a földbe,
Beteg szivem!
Hiszen
Megtetted, amit kelle,
Megtetted, amit lehetett:
Viselted honfisebedet.

Hideg van a siréjben;
Másnak lehet...
Meleg,
Forró lesz a sir nékem:
Mit életemben viselék,
A honfiseb még ott is ég.

De az itélet napja
Eljön talán,
S hazám
Bilincseit lerontja,
Akkor sebem begyógyuland,
S hüvösben nyugszom ott alant.','Menjünk, menjünk a földbe,
Beteg szivem!
Hiszen
Megtetted, amit kelle,','Pest, 1844. december',1844,'1844',array['Haza']::text[],'{}'::text[],false,230,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-133','petofi','Etelkéhez','Láttad-e, angyalom, a Dunát
S a szigetet közepén?
Ide szivembe képedet
Akként foglalom én.

A szigetről zöld falomb
Mártja a vízbe magát;
Ha te szivembe így a remény
Zöldjét mártanád!','Láttad-e, angyalom, a Dunát
S a szigetet közepén?
Ide szivembe képedet
Akként foglalom én.','Buda, 1844. december',1844,'1844',array['Természet']::text[],'{}'::text[],false,231,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-134','petofi','Cs. E. kisasszony emlékkönyvébe','Ha e sötét betűk, amiket itt leírok,
Lennének a balsors, amely tán téged ér:
Elvetném tollamat, nem írnék, bárha lenne
Minden vonásomért egy-egy ország a bér.','Ha e sötét betűk, amiket itt leírok,
Lennének a balsors, amely tán téged ér:
Elvetném tollamat, nem írnék, bárha lenne
Minden vonásomért egy-egy ország a bér.','Pest, 1844. december 25.',1844,'1844','{}'::text[],'{}'::text[],false,232,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-135','petofi','V. S.-né emlékkönyvébe','Tudom: mint boldogítod férjedet;
De szinte kívánnám, hogy azt ne tedd,
Ne olyan nagy mértékben legalább.
A fájdalomnak csalogánya ő
S mióta boldog, hangja ritkán jő...
Gyötörd, hogy halljuk édesbús dalát.','Tudom: mint boldogítod férjedet;
De szinte kívánnám, hogy azt ne tedd,
Ne olyan nagy mértékben legalább.
A fájdalomnak csalogánya ő','Pest, 1844. december 25.',1844,'1844','{}'::text[],'{}'::text[],false,233,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184408-136','petofi','Bucsú 1844-től','Egy esztendő a másik sírját ássa,
Gyilkolják egymást, mint az emberek.
Idő, szárnyadnak még egy csattanása,
S a jelen év is sírban szendereg.
Oltsd el, haldokló, hervadt ajakadnak
Lélekzetével életmécsedet,
Nem foglak odaírni tégedet,
Hol boldog évim följegyezve vannak.

Magas tervektől izzadó fejembe
Te oly sok eszme magvait vetéd,
S én a gyümölcsöt bőven megteremve
Láthatván, rajta büszkén nézek szét.
Jutalmaúl nem rest munkálatomnak
A hír csillagja rám sugárt vetett,
S én mégsem írlak oda tégedet,
Hol boldog évim följegyezve vannak.

Szivem sokáig a sors balkezében
A fájdalom meggyúlt világa volt;
Te, megvénűlt év, szóltál, hogy ne égjen,
És szózatodra a vad láng kiholt.
Elhamvadt üszke van csak bánatomnak
A rombadőlt s már fél-ép szív felett;
S én mégsem írlak oda tégedet,
Hol boldog évim följegyezve vannak.

Oh haldokló év! sírod mellett engem
Lágy bölcsejében ringat a remény,
S hahogy szabad, amit jövendöl, hinnem:
A mennyországnak állok küszöbén.
Szomszédságában ilyen boldog kornak
Mondom, tünő év, a bucsút neked.
S én mégsem írlak oda tégedet.
Hol boldog évim följegyezve vannak.

Reád függeszté hévvel esdekelve
Bágyadt szemét sohajtó nemzetem,
S te sóhajára semmit nem figyelve,
Ekkép feleltél mennydörögve: nem!
Te koszorúját eltépted honomnak
Ifjú reménye mit fejére tett;
Ezért nem írlak oda tégedet,
Hol boldog évim följegyezve vannak.','Egy esztendő a másik sírját ássa,
Gyilkolják egymást, mint az emberek.
Idő, szárnyadnak még egy csattanása,
S a jelen év is sírban szendereg.','Pest, 1844. december végén',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,234,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-01','petofi','A magyar nemzet','Oh ne mondjátok nekem, hogy
Hajnallik hazánk felett!
Látom én: az ő számára
Sző a sors szemfödelet.
S kérni istent nem merem, hogy
Nemzetem gyógyítsa fel,
Mert e nemzet, elhigyétek,
Életet nem érdemel.

Figyelemmel átforgattam
A történet lapjait,
S fontolóra vette lelkem,
Amit e hon végbevitt.
S mit találtam ott fölírva
Századok bötűivel?
Azt találtam, hogy e nemzet
Életet nem érdemel.

Jóra termett nép honában
Egy a szív, az akarat,
A közérdek mellett minden
Különérdek elmarad.
Itten oltárt minden ember
Ön bálványaért emel -
És az ilyen önző nemzet
Életet nem érdemel.

Voltak egyesek közöttünk!
Tiszta, hű, nagy szellemek,
Akik mindent, amit tettek,
A hazáért tettenek.
Hány volt köztök, kiket a hon,
Maga a hon veszte el!
És az ily hálátlan nemzet
Életet nem érdemel.

Más hazában híven őrzik
Mindazt, ami nemzeti;
Ősi kincsét a magyar nép
Megveti és elveti,
A magyar magyarnak lenni
Elfeled vagy szégyenel -
És az ily elkorcsult nemzet
Életet nem érdemel...

Oh de mért elősorolnom
E szegény hon vétkeit?
Lesz-e sors, oh lesz-e isten,
Aki minket megsegit?
A nagy isten szent kegyéből
Jő-e megváltási jel?
Lesz-e még e nemzet olyan,
Hogy halált nem érdemel?','Oh ne mondjátok nekem, hogy
Hajnallik hazánk felett!
Látom én: az ő számára
Sző a sors szemfödelet.','Pest, 1845. január',1845,'1845',array['Haza']::text[],'{}'::text[],false,235,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-02','petofi','Két testvér','Van énnekem egy kedves cimborám,
Talpig derék, becsűletes fiú;
Midőn szomoruságnak szele fú,
Vidámság köpenyét akasztja rám.

Ha nemzetem sorsára gondolok,
S szivem szorítja fojtó sejtelem:
Az én kedves pajtásom ott terem,
És szól, hogy ez nem férfias dolog;

Azt mondja, hogy csak várjak egy kicsit,
Hogy majd idővel másformán leszen,
Az ég kegyébe ismét fölveszen,
És, minket árva népet, megsegit.

Ha szerelem bújában epedek,
És a lemondás már-már főbe ver,
Az én kedves pajtásom nem hever,
Hanem jön és szól: ne legyek gyerek.

Azt mondja, hogy ne hagyjam magamat;
Ámbátor az most rám nem is figyel,
Ki szerelmem tőkéjét vette fel,
Majd megkerűl még tőke és kamat.

S ha eszmetársulatnál fogva itt
Eszembe jut borzasztó pénzügyem:
Biztat, hogy a szerencse, elhigyem,
Számomra is megnyitja markait;

Azt mondja, hogy még megjön az idő,
Hol fűtetlen szobában nem lakom,
Ha szűk udvarra nyíló ablakom
Tábláin a tél dérvirága nő. -

Az én kedves pajtásom így beszél
Kimondhatatlan barátságosan,
S lelkemnek oly széles jókedve van
Bút, bajt felejtető meséinél.

E jó fiúnak egy rosz bátyja van,
Igen komor, goromba férfi ő;
Ez a rosz bátya mindig közbejő,
És fölpofozza öccsét csúfosan,

S tőlem kegyetlenűl elkergeti.
Levert kedéllyel ballag tőlem el,
De újra jő, vigasztal és ölel
A jó fiú, ha szerit ejtheti.

Tudjátok tán, s fölösleges a szó:
Ily jóbarátomúl kit bírok én?...
Vigasztaló pajtásom a remény,
S komor, goromba bátyja a való.','Van énnekem egy kedves cimborám,
Talpig derék, becsűletes fiú;
Midőn szomoruságnak szele fú,
Vidámság köpenyét akasztja rám.','Pest, 1845. január első napjaiban',1845,'1845',array['Szerelem','Természet','Család']::text[],'{}'::text[],false,236,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-03','petofi','Apám mestersége s az enyém','Mindig biztattál, jó apám:
Kövessem mesterségedet,
Mondtad, hogy mészáros legyek...
Fiad azonban író lett.

Te a taglóval ökröt ütsz,
Tollammal én embert ütök - -
Egyébiránt ez egyre megy,
Különböző csak a nevök.','Mindig biztattál, jó apám:
Kövessem mesterségedet,
Mondtad, hogy mészáros legyek...
Fiad azonban író lett.','Pest, 1845. január',1845,'1845',array['Család']::text[],'{}'::text[],false,237,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-04','petofi','Hull a levél a virágról...','Hull a levél a virágról,
Elválok én a babámtól.
Isten hozzád, édes,
Isten hozzád, kedves
Galambocskám!

Sárgul a hold az ég alján,
Mind a kettőnk oly halovány.
Isten hozzád, édes,
Isten hozzád, kedves
Galambocskám!

Harmat hull a száraz ágra,
Könnyek hullanak orcánkra.
Isten hozzád, édes,
Isten hozzád, kedves
Galambocskám!

Lesz még virág a rózsafán,
Egymást még mi is látjuk tán.
Isten hozzád, édes,
Isten hozzád, kedves
Galambocskám!','Hull a levél a virágról,
Elválok én a babámtól.
Isten hozzád, édes,
Isten hozzád, kedves','Pest, 1845. január 7.',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,238,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-05','petofi','Elmondom, mit eddig...','Elmondom, mit eddig
Rejtve tartogattam,
Mint gyöngyét a tenger
Legmélyebb habokban.
Halld meg, drága gyöngyöm,
Szép, szelíd galambom!
Amit érezék és
Szenvedék, elmondom.

Éreztem szerelmet,
S szenvedtem miatta,
És nagy volt szerelmem,
Nagy szivem bánatja.
Bánatom s szerelmem,
Ez ikertestvérek,
Engemet gyötörni
Általad levének.

Szigorú körülmény
Ajkamat lezárta,
Hogy ne jőjön titkom
Senkinek tudtára.
Oh minő teher volt
Azt eddig viselnem!
Hányszor volt alatta
Roskadóban lelkem!

Mint a napfény elvesz
Felhők fátyolában,
Képedet szivemben
Eltemetni vágytam.
Könnyü szél pusztítást
Tészen a felhőben,
S felsüt a nap akkor
Annál égetőbben.

Sőt hazudtam többször
Másokért szerelmet;
E hazugság által
Csak nagyobb kinom lett. -
S most tudsz mindent, amit
Éreztem, szenvedtem;
Fogsz-e vígasztalni
Nyájas feleletben?

Szólj, üdvességemnek
Megváltó keresztje!
Nem nyilik meg ajkad?
Semmit sem felelsz-e? - -
Oh, mikép felelnél,
Hiszen néma nyelvvel...
Kiterítve... holtan...
Koporsóban fekszel!','Elmondom, mit eddig
Rejtve tartogattam,
Mint gyöngyét a tenger
Legmélyebb habokban.','Pest, 1845. január',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,239,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-06','petofi','Mit nem tettem volna érted...','Mit nem tettem volna érted,
Szép kis szőke gyermekem!
De szerelmem bemutatni
Megtiltotta végzetem.

Az egész, mit életemben
Érted tennem lehetett,
Annyi, hogy a koporsóba
Én tevém be tetemed.','Mit nem tettem volna érted,
Szép kis szőke gyermekem!
De szerelmem bemutatni
Megtiltotta végzetem.','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,240,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-07','petofi','Hová levél?,,,','Hová levél? te szebb reményeimnek
Korán kiégett hajnalcsillaga!
Keresni foglak; - hasztalan kereslek?
Vagy még meglátjuk egymást valaha?

Ha majd az éjnek hallgatag felében
Halvány sugárt a hold a földre vet:
A temetőnek küszöbét átlépem,
S fejem lehajtom sírhalmod felett.

Fölébredendsz-e ekkor álmaidból,
És elhagyod mély, hűvös nyoszolyád?
Hogy meghallgasd, amit majd ajakam szól:
A szerelemnek epedő szavát.

Fölébredendsz-e ekkor álmaidból,
És elhagyod mély, hűvös nyoszolyád?
Hogy letöröljed lankadt pilláimról
Az érted omló könnyek záporát.

Fölébredendsz-e ekkor álmaidból,
És elhagyod mély, hűvös nyoszolyád?
Hogy szellemed majd égő csókjaimtól
S keblem tüzétől melegűljön át.

Vagy holtjokat a sírok ki nem adják
S csak a mennyben találkozol velem?...
Vagy többé sem az éj, sem a mennyország
Meg nem mutat már tégedet nekem?!','Hová levél? te szebb reményeimnek
Korán kiégett hajnalcsillaga!
Keresni foglak; - hasztalan kereslek?
Vagy még meglátjuk egymást valaha?','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,241,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-08','petofi','Zárjátok be már azt a koporsót','Zárjátok be már azt a koporsót,
És vigyétek ki a temetőbe!
Hisz elég rég nézem már, hogy bennem
Megmaradjon mindörökre képe,
Vagy, hogy szívem, lelkem összetépje!','Zárjátok be már azt a koporsót,
És vigyétek ki a temetőbe!
Hisz elég rég nézem már, hogy bennem
Megmaradjon mindörökre képe,','Pest, 1845. január',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,242,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-09','petofi','Jaj, be bús ez a harangszó!','Jaj, be bús ez a harangszó!
Neked harangoznak,
Kedves, hervadt rózsaszála
Tizenöt tavasznak!

A templomnál van koporsód,
Koporsód van itten!
Hova veled vőlegényként
Egykor jőni hittem.

Védangyala kedvesemnek
Odafönn a mennyben!
Szánj, és vedd el eszemet, vagy
Vígasztalj meg engem.

Vagy talán te is meghaltál?
Tán megölt a bánat?
Hogy hervadni hagytad ezt a
Legszebb rózsaszálat.','Jaj, be bús ez a harangszó!
Neked harangoznak,
Kedves, hervadt rózsaszála
Tizenöt tavasznak!','Pest, 1845. január',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,243,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-10','petofi','Ha ébren meg nem látogatsz...','Ha ébren meg nem látogatsz,
Jőj hozzám álmaimban,
Jőj hozzám, meghalt életem!
Sok mondanivalóm van.

Hisz egymással mi ekkorig
Oly keveset beszéltünk;
Csak egy-két gyorsan illanó
Tekintet volt beszédünk.

Tudod, ha hozzátok menék,
Te mindig úgy futottál;
De más szobából titkosan
Rám gyakran pillantottál.

S öröm volt, látnom téged ott
Félig nyílt ajtó mellett,
Mikéntha láttam volna az
Egészen megnyilt mennyet.

Ha távozám: az ablakból
Tekintettél utánam;
Vélted, hogy észre nem veszem?
Oh, én mindent jól láttam.

De láttam temetésed is...
Csak ezt ne láttam volna!
Az a gödör, mely sírod lett,
Az lett szivemnek pokla.

Egyszerre lelkemet ezer
Mennykő csapása érte...
Ekkor hullott alá a föld
Koporsód födelére.

Ott vagy te most, szent angyalom!
Eljősz-e hozzám vajjon?
Mindenkor tárva lesz karom,
Ha jősz, hogy átkaroljon.

Csak érintsen lehellete
Közelgő szellemednek:
A mennybe föl, vagy sírba le,
Mindenhová követlek!','Ha ébren meg nem látogatsz,
Jőj hozzám álmaimban,
Jőj hozzám, meghalt életem!
Sok mondanivalóm van.','Pest, 1845. január',1845,'1845',array['Elmúlás','Természet']::text[],'{}'::text[],false,244,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-11','petofi','Te voltál egyetlen virágom...','Te voltál egyetlen virágom;
Hervadt vagy: puszta életem.
Te voltál fényes napvilágom;
Lementél: éj van körülem.

Te voltál képzeményim szárnya;
Megtörve vagy: nem szállhatok.
Te voltál vérem forrósága;
Meghűltél: oh, majd megfagyok.','Te voltál egyetlen virágom;
Hervadt vagy: puszta életem.
Te voltál fényes napvilágom;
Lementél: éj van körülem.','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,245,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-12','petofi','Amott fönn egy csillag ragyog...','Amott fönn egy csillag ragyog
A tiszta ég legtetején;
De oly gyönyörűen ragyog!
Egy csillagon sincs annyi fény.

És bennem így szól valami:
"Nézd, nézd, Etelkéd e sugár!
Hagyd itt a földi életet,
Menj föl hozzá, ő téged vár."

Fölmennék édesörömest,
De vágyam hasztalan hevit,
Mert, ami fölsegítene,
Eltörve lajtorjám, a hit.','Amott fönn egy csillag ragyog
A tiszta ég legtetején;
De oly gyönyörűen ragyog!
Egy csillagon sincs annyi fény.','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,246,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-13','petofi','Én vagyok itt...','Én vagyok itt, emésztő gyönyöröm!
Én, sírhalmodnak hű zarándoka;
Kérdezni jöttem, hogy mit álmodál
A föld alatt az első éjszaka?

Oh én nagyon borzasztót álmodám:
A földet a nap űzé, kergeté,
Kétségbeesve vágtatott a föld
A mélybe le s a csillagok fölé;

Utána a nap fáradatlanúl...
A végtelent keresztülnyargalák,
És végre elkezdett rohanni az
Egész rendvesztett, megbomlott világ.

És e zavarban egyre kergeté
A földet a nap, s vad haragja közt,
Hogy kergeté hiába, megragadt
Szilaj kezével egy nagy üstököst,

S rádobta... épen szívemen talált.
Képzelhető, mint fájt e seb nekem;
De úgy mégsem fájt, mint az, amit vert
Bennem halálod, legszebb örömem!','Én vagyok itt, emésztő gyönyöröm!
Én, sírhalmodnak hű zarándoka;
Kérdezni jöttem, hogy mit álmodál
A föld alatt az első éjszaka?','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,247,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-14','petofi','Nem háborítom-e nyugalmad...','Nem háborítom-e nyugalmad,
Elásott kincse életemnek!
Ha szívem árva gyermekével,
A halványarcú szenvedéssel
Hozzád gyakorta kijövendek?

Nem fog zajt ütni érkezésem,
Sírhalmod mellé halkan lépek:
Csak csókomat teszem fejfádra,
- Azt is lemossa könnyem árja, -
És ekkor ismét hazatérek.','Nem háborítom-e nyugalmad,
Elásott kincse életemnek!
Ha szívem árva gyermekével,
A halványarcú szenvedéssel','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,248,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-15','petofi','Természet! Még te is gúnyolódol?','Természet! még te is gúnyolódol?...
Amióta őt eltemetők:
Tél havának kellő közepette
Olyan tavasziak az idők.

Semmi jég a síma Dunavízen,
Semmi hó a Szentgellérthegyen...
Csak hogy testem és lelkem szemében
Mentül sértőbb ellentét legyen.

Mért nem keltek bőszült háborúra?
Mit alusztok? lusta elemek!
Éjszak vésze, te prédát üző sas,
Szárnyaid mért nem süvítenek?

Mért nem hajtod a felhőt az égen?
Mint vadász a sebzett madarat;
Hadd hullatná szét hópillangóit,
Mint ama madár a tollakat.

Ezt szeretném, kedvem ebben telnék,
Ugy láthatni a természetet,
Mint szivem van, mely szép Perzsiából
Vad Szibériává vetkezett. -

Oh de hátha e meleg verőfény
A természetnek nem gúnyja? nem!
Sőt részvéte: csak azért nincsen tél,
Hogy ne fázzék ott kinn kedvesem.','Természet! még te is gúnyolódol?...
Amióta őt eltemetők:
Tél havának kellő közepette
Olyan tavasziak az idők.','Pest, 1845. január',1845,'1845',array['Természet']::text[],array['tel']::text[],false,249,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-16','petofi','Miért tekintesz be szobámba?','Miért tekintesz be szobámba?
Kiváncsi hold!
Nem úgy foly már itt a világ, mint
Hajdanta folyt.

Egykor ha pillantásod hozzám
Betévedett:
Látád a szívben meg nem férő
Lángéletet.

Bú, kedv között élet-halálra
Látál csatát,
De győzedelmeskedni a bút
Nem láthatád.

Ez akkor volt, - ha megtekinted
Most arcomat,
Azt vélheted: tükörben látod
Tenmagadat.

Hideg vagyok és szótalan, mint
- Ahonnan jő
E hidegségem, szótlanságom, -
A temető.','Miért tekintesz be szobámba?
Kiváncsi hold!
Nem úgy foly már itt a világ, mint
Hajdanta folyt.','Pest, 1845. január',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,250,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-17','petofi','Láttam két hosszu nap...','Láttam két hosszu nap
Hideg tetemidet,
A szótlan ajakat,
A becsukott szemet;

Csókoltam homlokod
Letarlott édenét,
- Ez első csókom volt,
S te ezt sem érezéd! -

Csókoltam, rombadőlt
Oltárom, homlokod;
És e csókban hideg
Lelkem reáfagyott;

Csókoltam szemfedőd,
E dönthetlen határt,
Min túl nem léphetek,
Mely mennyemből kizárt.

Láttam koporsódnál
A fáklyák lángjait,
És a gyászszekeret,
Mely temetőbe vitt;

Ott voltam magam is,
Hallám, amint a hant
Az ásók éliről
Tompán reád zuhant...

Mindent, mindent tudok!
És mégsem hihetem;
Mindez nem álom-e?
Kétkedve kérdezem.

És hozzátok megyek,
S tekintek szerteszét:
Nem látom-e szemed
Tündökletes egét?

Nem látom, mindenütt
Hiába keresem,
És hazatérek, és
Sírok keservesen.','Láttam két hosszu nap
Hideg tetemidet,
A szótlan ajakat,
A becsukott szemet;','Pest, 1845. január',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,251,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-18','petofi','Hol vagy te, régi kedvem?','Hol vagy te, régi kedvem?
Te pajkos, vad fiú!
Fölválta lyánytestvéred,
A szótlan, méla bú.

Játékszered volt szívem,
Hová nem hordozád!
Nyilként rohanva, vitted
A nagy világon át,

Míg végre megbotlottál
Egy sírhalom fölött
S estedben a játékszer,
Szivem, kettétörött.','Hol vagy te, régi kedvem?
Te pajkos, vad fiú!
Fölválta lyánytestvéred,
A szótlan, méla bú.','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,252,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-19','petofi','Le az égről hull a csillag...','Le az égről hull a csillag;
Szemeimből könnyek hullnak.

Nem tudom, mért hull a csillag?
Könnyeim halottért hullnak.

Csak hull, csak hull könny és csillag;
Egyre hullnak, mégsem fogynak.','Le az égről hull a csillag;
Szemeimből könnyek hullnak.
Nem tudom, mért hull a csillag?
Könnyeim halottért hullnak.','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,253,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-20','petofi','Mi volna különös azon...','Mi volna különös azon,
Ha néha elmosolyodom
Vidám, tréfás beszéd felett?
Felhős ég is mutat derüt...
Csakhogy, midőn a nap kisüt,
A felhő keble megreped.','Mi volna különös azon,
Ha néha elmosolyodom
Vidám, tréfás beszéd felett?
Felhős ég is mutat derüt...','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,254,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-21','petofi','Ő, a kedves drága kisleány..','Ő, a kedves drága kisleány,
Ő s az élet lakták szívemet;
Mint repkény a fákat, a remény
Átszövé e tündérteremet.

Kisleánykám elment... elvivék...
Most alant a mély házban lakik,
Melynek egyszer elzárt ajtaja
Meg nem nyíl az ítéletnapig.

S a leánnyal elment életem...
Kikisérte... odakinn maradt,
S elfoglalni régi lakhelyét
Nincsen benne semmi akarat.

Igy lett szívem csöndes és üres,
Egy lepusztult ház, bús, laktalan;
Rajt az árva repkény, a remény,
Leng sohajtásim fuvalmiban;

S mert a földön ápolója nincs,
Feltörekszik, fel az ég felé...
Oh, csak a rontó kételkedés
Sarját mindig el nem metszené! -

S ki lesz új lakó szivemben, mely
Nemsokára végkép romban áll?
Legfölebb is egy vén remete,
És ez a remete a halál.','Ő, a kedves drága kisleány,
Ő s az élet lakták szívemet;
Mint repkény a fákat, a remény
Átszövé e tündérteremet.','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,255,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-22','petofi','Álltam sírhalma mellett...','Álltam sírhalma mellett
Keresztbefont kezekkel...
Mozdúlatlan szoborként...
A dombra szögzött szemmel.

Áll a hajós a parton
S a tengeren tekint szét,
Mely koldussá tevé, mely
Elvette minden kincsét.','Álltam sírhalma mellett
Keresztbefont kezekkel...
Mozdúlatlan szoborként...
A dombra szögzött szemmel.','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,256,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-23','petofi','Hazugság amit...','Hazugság, amit annyiszor hallottam,
Hogy ölni képes a nagy fájdalom.
Különben már rég nem volnál magadban,
Veled fekünném, édes angyalom!
A fájdalom nem éles fejsze, melynek
Csapásától az élet fája dől...
A fájdalom féreg, mely lassan, lassan,
De nem fáradva, folyvást rág belől.','Hazugság, amit annyiszor hallottam,
Hogy ölni képes a nagy fájdalom.
Különben már rég nem volnál magadban,
Veled fekünném, édes angyalom!','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,257,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-24','petofi','Barátim, csak vigasztalással...','Barátim, csak vigasztalással
Ne szomorítanátok engem!
A bú egyetlen kincs, amelyet
A szerelemtől örököltem;

S e kincset híven őrzi szívem,
(Mert a sziv üresen nem állhat,
Kell, hogy legyen mindig lakója,
Akár öröm, akár búbánat;)

E kincset el nem tékozolnám
A föld minden gyönyöreért sem,
Minden darabja dallá olvad
Lelkemnek titkos műhelyében.

S minden dal kő egy épülethez,
Mely a felhőket érni fogja;
E büszke, fényes épület lesz
Kedves halottam Pantheonja.','Barátim, csak vigasztalással
Ne szomorítanátok engem!
A bú egyetlen kincs, amelyet
A szerelemtől örököltem;','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,258,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-25','petofi','Jőj, tavasz, jőj!...','"Jőj, tavasz, jőj!" - gondolám az ősszel, -
"Várlak, mert boldogságommal jősz el;
Kinn falun lesz ifju, szép galambom,
És szabad lesz őt meglátogatnom;
S hogyha tőle száz mérföldre lennék,
Száz mérföldről is hozzája mennék.
Ha jön a nap hajnal-ölelésre,
Ha megy a nap éj-fölébresztésre,
És a hold, a zultán, ha belépe,
Csillaglyányos gazdag háremébe:
Én galambom hű árnyéka lészek.
Követője minden lépésének.
Míg szerelme, mint tavasz! virágod
Melegűlő keblén kicsirázott,
És amíg ő e virágot szűzi
Pirulással én szivemre tűzi:
S mért nem tűzné? s lehetetlenség-e?
Hogy menyasszonycsók leend a vége.
Jőj, tavasznak illatos füzére!
Tegyelek föl jegyesem fejére!"

*

Jőj, tavasznak illatos füzére!
Tegyelek föl sírja keresztjére.','"Jőj, tavasz, jőj!" - gondolám az ősszel, -
"Várlak, mert boldogságommal jősz el;
Kinn falun lesz ifju, szép galambom,
És szabad lesz őt meglátogatnom;','Pest, 1845. január',1845,'1845',array['Természet','Szerelem']::text[],array['tavasz']::text[],false,259,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-26','petofi','Be szomorú az élet énnekem..','Be szomorú az élet énnekem,
Mióta eltemették kedvesem!
Csak úgy lézengek, mint az ősz virága,
Mely minden szellő érkezésivel
Egy-egy megszáradt szirmot hullat el,
S mely csüggedt fővel kimulását várja.

A fájdalom gyakorta megrohan,
Mint éhező vad, mérgesszilajan,
S éles körmét szivembe vágja mélyen.
Kiáltok a sors ellen átkokat,
Amely az embernek mennyet mutat,
Hanem megtiltja, hogy belé ne lépjen.

Legtöbbször csendes, néma bánatom;
Élek? nem élek? szinte nem tudom.
Jön és megszólít egy-két jóbarátom;
Beszédeikre ritkán felelek.
Örültem egykor, hogyha jöttenek,
Most, hogyha mennek, szívesebben látom.

Gyakran bolyongok föl s le céltalan,
Bolyongok, míg - azt sem tudom, hogyan? -
A drága kislyány sírhalmához érek,
Édes remény tart ottan engemet;
Remélem, hogy majd szívem megreped...
Mért csalnak mindig, mindig a remények!','Be szomorú az élet énnekem,
Mióta eltemették kedvesem!
Csak úgy lézengek, mint az ősz virága,
Mely minden szellő érkezésivel','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,260,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-27','petofi','Panaszkodám hát?...','Panaszkodám hát? elpanaszolám
Szivem baját, búját az embereknek?
Miként, ha ujját megmetszé, a gyermek
Panaszkodik... szégyen, szégyen reám!

S volt a panasz végtére is miért?
Hisz keservét mutató kebelnek
Vagy szánalommal vagy gúnnyal fizetnek,
S egyik sem kell... egyik, mint másik sért.

Vagy elmondhattam szóval sorsomat?
Elmondhatám? mi az: midőn a lélek,
Sírhalma mellett porló kedvesének,
Egy kínba fúló életet sirat.

És én mégis, mégis panaszkodám
Kislelküen, gyáván az embereknek,
Miként, ha ujját megmetszé, a gyermek
Panaszkodik... szégyen, szégyen reám!

De többé, többé nem panaszkodom,
Büvös szigetté fog változni keblem,
Honnan ki nem fog út vezetni, melyben
Elátkozottan él a fájdalom.','Panaszkodám hát? elpanaszolám
Szivem baját, búját az embereknek?
Miként, ha ujját megmetszé, a gyermek
Panaszkodik... szégyen, szégyen reám!','Pest, 1845. január-február',1845,'1845',array['Gyermekkor']::text[],'{}'::text[],false,261,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-28','petofi','Hatalmas orvos az idő...','Hatalmas orvos az idő; előbb-utóbb
Minden sebet befog.
Bármennyit szenvedek: ez orvos által majd
Én is meggyógyulok.
A bú, mely most sötét felhők villámtüze,
Lesz nyájas hold sugára,
Mely tündökölni száll szelíd emlékezetem
Morajtalan tavára.

És fon talán a sors nem fáradó keze
Egy rózsás kötelet,
Mely összefűzi majd az életvágyat és
Fölépült szívemet.
Ekkor, gondolható, a könnyek és a szók
Mi keserűk lehetnek,
Melyekkel a tört szív örökre búcsut mond
Remény- vagy élvezetnek.

Azért szeretném most, midőn hűlt kebelem
Vágy-, s kívánságtalan,
Azért szeretném most, ha elmennék oda,
Ahol Etelke van.
Öleld fel, oh halál, kifáradt éltemet,
És tedd a temetőbe,
Mint keblén elszunyadt magzatját a szülő
Letészi bölcsejébe.

És hogyha meghalok, ohajtásom csak egy,
Barátim, tőletek:
Hogy engem a mellé a kedves kisleány
Mellé temessetek.
Mik voltak álmaink, majd minden éjfelen
Elmondjuk ott egymásnak,
S egyszerre indulunk, ha ébresztő szava
Zeng a föltámadásnak.','Hatalmas orvos az idő; előbb-utóbb
Minden sebet befog.
Bármennyit szenvedek: ez orvos által majd
Én is meggyógyulok.','Pest, 1845. január-február',1845,'1845',array['Szerelem','Elmúlás']::text[],'{}'::text[],false,262,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-29','petofi','Játszik öreg földünk...','Játszik öreg földünk
Fiatal sugarával a napnak;
Pajkos enyelgés közt
Egymásnak csókokat adnak.

A Duna hullámin,
Bércén, völgyén a vidéknek,
Tornyokon, ablakokon,
Mindenhol csókjaik égnek.

Oly jókedvü a nap
Jöttén; jókedvü lementén,
Mintha nem is látná
Sírhalmodat, édes Etelkém!','Játszik öreg földünk
Fiatal sugarával a napnak;
Pajkos enyelgés közt
Egymásnak csókokat adnak.','Pest, 1845. január-február',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,263,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-30','petofi','Kéket mutatnak még...','Kéket mutatnak még a távol erdő
Virító fáin a zöld levelek?
Tajtékzik még a Duna, mint szilaj mén?
Ha vakmerő harcosként rajt teremvén,
Kergetni kezdi őt a fergeteg.

Pirúl a szép menyasszony még, a hajnal?
Ha vőlegényét várja, a napot;
S harmatkönyűket sír még a bús özvegy,
Az éj? midőn a csillagokhoz fölmegy,
És látja a sok árva magzatot.

Megmérhetetlen látköröm volt egykor,
Hanem most már nem látom ezeket:
Az a kis domb, mely kedvesem takarja,
Rám nézve kél átláthatlan magasra,
S elrejt előlem földet és eget.','Kéket mutatnak még a távol erdő
Virító fáin a zöld levelek?
Tajtékzik még a Duna, mint szilaj mén?
Ha vakmerő harcosként rajt teremvén,','Pest, 1845. január-február',1845,'1845',array['Természet']::text[],'{}'::text[],false,264,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-31','petofi','Ha életében...','Ha életében nem szerettem volna
A szőke fürtök kedves gyermekét:
Övé leendett életem, szerelmem,
Midőn halotti ágyon feküvék.

Mi szép, mi szép volt a halotti ágyon!
Mint hajnalban ha fényes hattyu száll,
Mint tiszta hó a téli rózsaszálon:
Lengett fölötte a fehér halál.','Ha életében nem szerettem volna
A szőke fürtök kedves gyermekét:
Övé leendett életem, szerelmem,
Midőn halotti ágyon feküvék.','Pest, 1845. január-február',1845,'1845',array['Szerelem','Elmúlás']::text[],'{}'::text[],false,265,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-32','petofi','E szobában küszködött...','E szobában küszködött az
Élet és halál fölötte,
Míg az élet
Őt a szépet,
Őt a kedvest, elvesztette.

E szobában siratám őt
Könnyeimnek tengerével:
- Szenvedésem
Avvagy létem
E tengert mért nem nyelé el! -

E szobában lesz lakásom;
Édes kín lesz laknom itten,
Itten laknom,
Őt láthatnom
Mindig éber emlékimben.

Egy kivánatom leszen, ha
E szobából el kell menni;
Az, hogy engem
Akkor innen
Szent Mihály lova vigyen ki.','E szobában küszködött az
Élet és halál fölötte,
Míg az élet
Őt a szépet,','Pest, 1845. január-február',1845,'1845',array['Természet']::text[],'{}'::text[],false,266,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-33','petofi','A hó, a holt föld téli szemfedője','A hó, a holt föld téli szemfedője,
Az éjen át
A temetőre
Leszállt.
A nap
Hideg sugára
Néz komoran
Le a halottak puszta országára.

Nem enged a hó a nagy temetőben,
Csak egyedűl
Etelke sírja
Körűl;
De itt
Sem a napfénytől,
Hanem szemem,
Síró szememnek szakadó könnyétől.','A hó, a holt föld téli szemfedője,
Az éjen át
A temetőre
Leszállt.','Pest, 1845. január-február',1845,'1845',array['Természet','Elmúlás']::text[],array['tel']::text[],false,267,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184501-34','petofi','Midőn nagyon bánt...','Midőn nagyon bánt a vad fájdalom,
A várost, a világot elhagyom,
S oda megyek ki, hol az emberek
Napestig mélyen alva fekszenek,
De ha az óra éj felére jár,
S felhők közt búsong sárga holdsugár:
A szendergőknek álma megszakad,
S elhagyják mély, sötét tanyájokat,
S fehér ruhában járnak tétova,
Mig hajnalt hirdet a kakas szava.
Idemegyek, a temetőbe, én
Fájdalmaimnak vészes éjjelén,
S ha itten, drága sírhalmom felett
Könyűimnek forrása megered,
És a könyűkhöz sóhajom vegyűl:
Fájdalmam lassacskán lecsendesűl.

*

Akkor leszek ám még majd csendesen,
Ha melléd fekszem, édes kedvesem!','Midőn nagyon bánt a vad fájdalom,
A várost, a világot elhagyom,
S oda megyek ki, hol az emberek
Napestig mélyen alva fekszenek,','Pest, 1845. január-február',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,268,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-35','petofi','Tizenkettőt ütött az óra...','Tizenkettőt ütött az óra,
Fölébredék a harangszóra,
És ím sötét szobámban egy
Fehér alak
Föl- és lemegy...
Te vagy, te vagy, kit annyit vártalak,
Te vagy, boldogságom fájának
Idő előtt lehullt gyümölcse!
Jer, karjaim kitárva állnak,
S kész ajkam, hogy csókját ajkadra hintse,
Jer, elröpűlt kedves galambom!...
De szólt a lyányka halk, fájdalmas hangon:
"Megállj, megállj! előbb megkeresem
Elvesztett életem;
Lásd, élet nélkül ott a sírban
Fekünni olyan szomorú dolog:
Ott oly sötét és oly hideg van...
Én újra élni akarok;
Megkeresem
Elvesztett életem.
Nincs nálad?
Add vissza, kérlek, hogyha megtaláltad." -
Oh nincs az nálam,
Meg nem találtam,
Meg nem találtam drága életed!
De hogyha az enyém kell: íme vedd!...
S átadni akarám
Tulajdon éltem,
De már a látomány
Eltűnt az éjben.','Tizenkettőt ütött az óra,
Fölébredék a harangszóra,
És ím sötét szobámban egy
Fehér alak','Pest, 1845. január-február',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,269,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-36','petofi','Anyám, anyám...','Anyám, anyám, oh
Legjobb s legboldogtalanabb anya!
Nincs hát reményed,
Mit a fösvény való beváltana?

Kiküldözéd, mint
Galambját Nóé, a reményeket;
De teljesűlés
Zöld ágával meg egy sem érkezett.

Végső reményed:
Ha majd halálod meg fog hűteni,
Fölmelegítnek
Még egyszer gyermeked hő könnyei.

Szegény anyám te!
Ez a vigasztalás sem jut neked;
Elsírta könnyeit
Szerelmesének sírján gyermeked.','Anyám, anyám, oh
Legjobb s legboldogtalanabb anya!
Nincs hát reményed,
Mit a fösvény való beváltana?','Pest, 1845. január-február',1845,'1845',array['Család']::text[],'{}'::text[],false,270,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-37','petofi','Hiába várlak hát..','Hiába várlak hát ezentúl?
Megsiratott szép gyermekem!
Meg nem jelensz többé nekem?
Mint eddig gyakran megjelentél
Szobámban csöndes éjeken.

Eljő az éj, eljő az éjfél;
Mi haszna jő? nem jő veled.
Nem látom lengő szellemed,
S reményem eltörött szárnyával
Födöm be bágyadt szememet.

Hová levél? miért maradsz el?
Örökre kedves szép leány!
Hervadt orcám ijeszt talán?
Ne félj, ne félj hervadt orcámtól:
Érted levék oly halovány.

Oh jőj fel egyszer még sirodból,
Mindennél drágább árnyalak!
Csak hogy még egyszer lássalak;
Aztán mondd, hogy terhedre van búm,
S többé nem háborítalak.','Hiába várlak hát ezentúl?
Megsiratott szép gyermekem!
Meg nem jelensz többé nekem?
Mint eddig gyakran megjelentél','Pest, 1845. január-február',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,271,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-38','petofi','Függ már a lant...','Függ már a lant megérintetlenűl,
Mellyel keservemet elénekeltem,
Keservem, érted, a sír börtönének
Örök rabjává záratott szerelmem.

Ott függ a lant megérintetlenűl,
S ha megpendűl a méla nyúgalomban:
Az nem az összes hangszernek zenéje,
Egy-egy húr hangja csak, mely kettépattan.','Függ már a lant megérintetlenűl,
Mellyel keservemet elénekeltem,
Keservem, érted, a sír börtönének
Örök rabjává záratott szerelmem.','Pest, 1845. január-február',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,272,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-39','petofi','Vahot sándorhoz','Szent a költő lantja.
A föld működését
Csillagtáborából
Őrszemekkel néző
Isten adománya;
Ő beszél a rezgő
Húrok énekében,
Majd vigasztalólag,
Majd pedig fenyítve.
Mint a nép erénye
Elvetett magvából
Vagy konkolyt arat, vagy
Tántorodva lép a
Nemesebb törekvés
Tiszta ösvényéről
A lealjasúlás
Iszapos gödrébe.
Szent a költő lantja,
És nekem nagyon fájt
Látnom, hogy van olyan,
És hogy nem kevés van,
Aki e szentséghez
Nem fél vakmerően
Nyúlni szennyes ujjal,
S hogy csak fényes álarc
Sok költő beszéde,
Mely sötét szivének
Foltjait takarja.
Szebb örömeimnek
Napja volt azon nap,
Melyben a te kebled
Rejtekében láttam,
S láthatám, hogy benned
Egy a költő s ember,
Hogy dalod s dalodnak
Kútforrása, szíved,
Tiszta egyaránt, mint
A nap és sugára.
Bizalommal adtam
Kezemet baráti
Szorításra, és te
Vissza nem taszítád;
S ha Etelke meghűlt
Szíve ott alant nem
Porlanék a sírnak
Hold- és csillagatlan
Éjjelében: ah, ugy
Tán nemcsak barátod
Lettem volna egykor.
Megtörtént!... a multat
A jelen keserve,
A jelen siralma
Vissza nem teremti.
Enyhítsd legalább te,
Enyhítsd a barátság
Balzsamolajával
Veszteségem sebjét,
És ne bánd, ha olykor
Elmerengve csüggök
Bámuló szemekkel
Hitvesednek arcán,
Oh, ne bánd, barátom!
Hamvadó testvére,
A szegény Etelke
Elvesztett vonásit
Keresem csak ottan;
S ha lelek közűlök
Bárminő kevést is:
A reménynek eldőlt
Tündércsarnokából
Szent ereklyeképen
Tartom emlékimnek
Drága kincstárában,
S őrzöm a felejtés
Eltörlő kezétől,
Mint a megfagyástól
Őrzi a világot
A meleg verőfény.','Szent a költő lantja.
A föld működését
Csillagtáborából
Őrszemekkel néző','Pest, 1845. január',1845,'1845',array['Természet']::text[],'{}'::text[],false,273,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-40','petofi','A világ és én','Megvetésem és utálatomnak
Hitvány tárgya, ember a neved!
A természet söpredéke vagy te,
S nem király a természet felett.
A teremtés legutósó napján
Alkotott az isten tégedet,
Elfáradt már ekkor a munkában,
S így jelessé nem teremthetett.

Szeretélek téged egykor, s szívem
Veled hű szövetséget köte,
Megvetésem és utálatom lett
E szövetség kettős gyermeke;
Jól ismerlek, te nem érdemelsz mást,
Nem, mint megvetést s utálatot...
Szolgazsarnok! vagy nyalod más talpát,
Avvagy talpad mással nyalatod.

S azt hiszed tán, te nyomoru pára!
Mint te, én is olyan rab vagyok?
Azt hiszed, hogy én dicséretedre
Vagy gyalázatodra hallgatok?
Azt hiszed, hogy tettben és irásban
Engem aggódásnak férge rág,
És szorongva kérdezem magamban:
Mit fog erre szólni a világ?

Hidd, ha jónak látod; ámde tudd meg:
Én nem függök tőled semmiben,
Amily útat választott magának
Lelkem, rajta egyenest megyen.
És ha tetszik engem fölemelned,
Ám emelj föl, mint bálványodat;
Ha fölültetsz fejed tetejére,
Majd kirúgom szolgafogadat!','Megvetésem és utálatomnak
Hitvány tárgya, ember a neved!
A természet söpredéke vagy te,
S nem király a természet felett.','Pest, 1845. január',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,274,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-41','petofi','Költő lenni vagy nem lenni','Légy átkozott, te átkos pillanat,
Melyben fogantatám,
S te, melyben kínnal a kín emberének,
Költőnek szűlt anyám!
Oh költészet, te a
Gyanútalan szív csalfa pókhálója,
És azután foglyodnak
Oly irgalomtalan fojtogatója!

Véremből már te oly sokat szivál,
Mérges fulánku pók!
De szálaid bármilyetén kuszáltak,
Még elszaggathatók.
Letépem azokat,
Bármint keresztülszőtték-fonták szívem,
S ha összenőttenek már:
Ugy velök együtt szívem is kitépem!

De véremből e gyilkos férget én
Többé nem hizlalom,
Ugyis, mi lenne a kiszívott, elfolyt
Vérért a jutalom?
Dicsőség legfölebb,
Ez a szem fényét elvakító semmi;
És még az is nagy kérdés:
E semmi is fog-e jutalmam lenni?

Széles folyódon úszom ezután,
Oh mindennapiság!
Ballagsz velem majd, és csendes folyásod
Sziklák közé nem vág.
Nem lesz hirem, nevem,
Tán a boldogság karjai sem várnak,
De lesz mégis nyugalmam,
S a nyúgalom fele a boldogságnak.

És elnémuljak mindörökre hát?
Egy hangszer életem;
E hangszer ép még, s azt, mint elromlottat,
A szögre föltegyem?
Hallgasson örömem?
Ne légyen hangja többé fájdalmamnak?
Hallgathat-e a tenger,
Midőn hullámin szélvészek rohannak?

Nem, költészet, nem hagylak el soha,
Mert nem hagyhatlak el!
Táplálni foglak a gyötört kebelnek
Legforróbb vérivel.
Nem bánom: tépj, eméssz,
Másoktól meghallgattatást sem várok,
Azért éneklek, költök,
Mig végső csep vérem ki nem szivárog.','Légy átkozott, te átkos pillanat,
Melyben fogantatám,
S te, melyben kínnal a kín emberének,
Költőnek szűlt anyám!','Pest, 1845. február',1845,'1845',array['Természet']::text[],'{}'::text[],false,275,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-42','petofi','Elfojtott könnyek','Úgy sírhatnék!... megbántott valami,
Nagyon megbántott, mondhatatlanul.
És a felhővel a lélek rokon:
Megkönnyebbűl, midőn esője hull.

De én nem sírok, nem szivelhetem,
Megfogadám, hogy többé nem sírok.
El, könnyek!... szívem úgyis oly üres,
Megfértek benne, odafolyjatok.','Úgy sírhatnék!... megbántott valami,
Nagyon megbántott, mondhatatlanul.
És a felhővel a lélek rokon:
Megkönnyebbűl, midőn esője hull.','Pest, 1845. február',1845,'1845',array['Természet']::text[],'{}'::text[],false,276,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-43','petofi','Hír','Mi hát az a hír, a költőnek híre?
Hogy annyi a bolondja és irígye?
Van-e, van-e, ki nem sovárg utána?
Van-e, van-e, kinek az nem bálványa?
S méltán! a hír fönséges terebély fa,
Királyi széknél pompásabb árnyéka,
Zöld ágait ki századokra nyujtja,
Rontó enyészet vésze nem fog rajta,
S hozzá magzatjai a késő világnak
Zarándokolni áhítattal járnak.
Oh szép, oh szép a hír borostyánfája!
Nem is csoda, ha hervadás nem bántja,
Hiszen tövét a meggyilkolt boldogság
Kiontott vére és könyűi mossák.','Mi hát az a hír, a költőnek híre?
Hogy annyi a bolondja és irígye?
Van-e, van-e, ki nem sovárg utána?
Van-e, van-e, kinek az nem bálványa?','Pest, 1845. február',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,277,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-44','petofi','Téli világ','Megölte valaki magát,
Az hozta ezt a rút időt.
Fuj a szél, táncol a tányér
A borbélyműhelyek előtt.
Hol a boldogság mostanában?
Barátságos meleg szobában.

A napszámos, napszámosné
Tuskót fürészel és hasít;
Daróc pólyában gyermekök
A szélvésszel versenyt visít.
Hol a boldogság mostanában?
Barátságos meleg szobában.

Jár nagy léptekkel föl s alá
A katona az őrhelyen,
És számlálgatja lépteit;
Kínjában mást mit is tegyen?
Hol a boldogság mostanában?
Barátságos meleg szobában.

A hosszulábu drótostót
Kopott gubáját cepeli;
Az orra érett paprika,
S hidegtől folynak könnyei.
Hol a boldogság mostanában?
Barátságos meleg szobában.

Barangol a vándorszinész
Egy falutól a másikig;
Meleg ruhája nincs ugyan,
De mindazáltal éhezik.
Hol a boldogság mostanában?
Barátságos meleg szobában.

Hát a cigány?... vacog foga
A rongyos sátorok alatt;
Kopogtat a szél és bemegy,
Bár a cigány nem szól: szabad!
Hol a boldogság mostanában?
Barátságos meleg szobában.

Megölte valaki magát,
Az hozta ezt a rút időt.
Fuj a szél, táncol a tányér
a borbélyműhelyek előtt.
Hol a boldogság mostanában?
Barátságos meleg szobában.','Megölte valaki magát,
Az hozta ezt a rút időt.
Fuj a szél, táncol a tányér
A borbélyműhelyek előtt.','Pest, 1845. február',1845,'1845',array['Természet']::text[],array['tel']::text[],false,278,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-45','petofi','A toronyban delet harangoznak...','A toronyban delet harangoznak,
A fejem tetejére süt a nap.
Hej, ha olyan közel volna sírom,
Mint amilyen rövid az árnyékom.

Kihozta az ebédet a gyerek;
Amint látom, egy kis bort is küldtek.
Be savanyú!... de csak kiürítem;
hiszen még savanyúbb az életem.

Élet, élet, áldástalan élet!
Számadásod velem mikor végzed?
Mikor mondod: menj isten hirével,
Porladozzál porló szeretőddel!','A toronyban delet harangoznak,
A fejem tetejére süt a nap.
Hej, ha olyan közel volna sírom,
Mint amilyen rövid az árnyékom.','Pest, 1845. február-március',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,279,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-46','petofi','Így is jó','Megkopott a mentém préme,
A sarkantyúm rozsdás, görbe,
Nincs a kucsmám félrecsapva,
Nincs a bajszom kipödörve.

Így is jó ily bús legénynek,
Akit elhagyott rózsája,
És lement a földbe mélyen,
Hogy ne is nézhessek rája.','Megkopott a mentém préme,
A sarkantyúm rozsdás, görbe,
Nincs a kucsmám félrecsapva,
Nincs a bajszom kipödörve.','Pest, 1845. február-március',1845,'1845','{}'::text[],'{}'::text[],false,280,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-47','petofi','Gyors a madár, gyors a szélvész...','Gyors a madár, gyors a szélvész,
Gyors a villám;
Hanem az alföldi betyár
Még gyorsabb ám!

Ma őkelme csikót szerez
Kecskeméten,
Szentmártonnál aznap át is
Megy a réven.

Holnap a csikót eladja
Fehérváron,
Eladja, még újat is lop
E vásáron.

Holnapután már valahol
Becskereken
Lovagol egy karcsu fakón:
A deresen.','Gyors a madár, gyors a szélvész,
Gyors a villám;
Hanem az alföldi betyár
Még gyorsabb ám!','Pest, 1845. február-március',1845,'1845',array['Természet']::text[],'{}'::text[],false,281,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-48','petofi','Piroslik a kecskerágó...','Piroslik a kecskerágó
Szőlő árka mellett.
Az árokban tehéncsordás
Kutyája megellett.

Tehéncsordás, vízbe ne hányd
A kutyakölyköket!
Tudod-e, hogy sok legénynek
Tetszik feleséged?

Alattomban környékezik
Házad a legények;
Uszítsd rájok a kutyákat.
Majd mikor felnőnek.','Piroslik a kecskerágó
Szőlő árka mellett.
Az árokban tehéncsordás
Kutyája megellett.','Pest, 1845. február-március',1845,'1845','{}'::text[],'{}'::text[],false,282,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-49','petofi','Kicsapott a folyó...','Kicsapott a folyó,
Vízben úszik a táj.
Túl a vizen lakol,
Édes rózsám, ne várj.
Elvitte az árvíz
A töltést, a hidat;
Amott megy a hidból
Az utósó darab.

Magam egy halomról
Nézek át a vizen;
A vízen keresztül
Galamb száll sebesen.
Nem is tudom ugyan:
Galamb-e igazán,
Ami ott száll... vagy az
Én sohajtásom tán?','Kicsapott a folyó,
Vízben úszik a táj.
Túl a vizen lakol,
Édes rózsám, ne várj.','Pest, 1845. február-március',1845,'1845',array['Természet']::text[],'{}'::text[],false,283,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-50','petofi','Pest','Hiába, Pest csak Pest, tagadhatatlan!
S én Pestnek mindig jóbarátja voltam,
És ahol csak kell, hát pártját fogom.
Volt itt nekem sok kellemes napom.
Kivált h'' az utcán kóborolhatok:
Az angyaloknál boldogabb vagyok.
Egy óriáskigyó bámészkodásom,
Végighuzódik a népsokaságon.
S aztán itt minden olyan érdekes,
A sziv örömében csak ugy repes.
A vargainasok pofozkodása,
A bérkocsiknak embergázolása,
A zsebmetszők, a pörölő kofák
Az embert mind igen mulattatják.
S azt kell még látni, hogyha szép időben
Sétára kél a tarkabarka nőnem;
Mi szépek ők, mi szépek, teringette,
Elől kifestve és hátul kitömve.
Hát ahol a dicső arszlánok járnak!
Azt nevezem aztán baromvásárnak.','Hiába, Pest csak Pest, tagadhatatlan!
S én Pestnek mindig jóbarátja voltam,
És ahol csak kell, hát pártját fogom.
Volt itt nekem sok kellemes napom.','Pest, 1845. február-március',1845,'1845','{}'::text[],'{}'::text[],false,284,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-51','petofi','Orbán','Komor, mogorva férfiú
Volt Orbán,
Bár oly vidám hajnal pirult
Az orrán.
De hisz mogorva ép azért
Volt Orbán,
Mert oly vidám hajnal pirult
Az orrán.

Oka egyébiránt maga
Volt Orbán,
Hogy oly vidám hajnal pirult
Az orrán.
Temérdek borfélét ivott
Meg Orbán,
Vidám hajnal azért pirult
Az orrán.','Komor, mogorva férfiú
Volt Orbán,
Bár oly vidám hajnal pirult
Az orrán.','Pest, 1845. február-március',1845,'1845','{}'::text[],'{}'::text[],false,285,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-52','petofi','A sorshoz','Egyet mondok, sors, kettő lesz belőle:
Nekem csak egy leány szerelmit add,
S érette én átengedem cserébe
Minden, de minden... adósságomat.','Egyet mondok, sors, kettő lesz belőle:
Nekem csak egy leány szerelmit add,
S érette én átengedem cserébe
Minden, de minden... adósságomat.','Pest, 1845. február-március',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,286,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-53','petofi','A nap','Mi az a nap? mi az a nap?
Nem is nap az tulajdonkép.
Ugyan mi hát?... hát semmi más,
Mint egy nagy szappanbuborék.

Valami óriásfiú
Kifúja reggel keleten,
S szétpattan este nyúgaton. -
És ez minden nap így megyen.','Mi az a nap? mi az a nap?
Nem is nap az tulajdonkép.
Ugyan mi hát?... hát semmi más,
Mint egy nagy szappanbuborék.','Pest, 1845. február-március',1845,'1845',array['Természet']::text[],'{}'::text[],false,287,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-54','petofi','Mulatság közben','Most már mulassatok, kedves barátim.
Az én mulatságomnak vége van;
A tréfaságok, az elmés beszédek,
Az ének, a bor, mind haszontalan.

Az embernek mért is van gondolatja?
Lássátok, én olyan bolond vagyok:
Mikor legvígabb a jelen, jövőbe
Ragadnak rögtön a gondolatok.

Az a jövő! az a kegyetlen szélvész,
Mely szétzilál bennünket, szerteszét;
S lesz-e azontúl még találkozásunk?
Vagy halljuk-e csak egymásnak hirét?

Igen, halljuk, majd elbeszéli a hír:
Ez és ez nyugszik... odalenn...
Haszontalan história az élet!
Miért is van, vagy mért nem végtelen?','Most már mulassatok, kedves barátim.
Az én mulatságomnak vége van;
A tréfaságok, az elmés beszédek,
Az ének, a bor, mind haszontalan.','Pest, 1845. február-március',1845,'1845',array['Természet']::text[],'{}'::text[],false,288,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-55','petofi','Rosz verseimről','Tán én nem tudnék írni
Mindig jó verseket?
De szívem főerénye
Az emberszeretet.

Valóban!... már pedig ha
Mindig csak jót irok,
Mivé lennének úgy a
Szegény kritikusok?

Időnként valamicske
Ezeknek is csak kell,
S ők minden hulladékot
Gyönyörrel falnak fel.

Rágódjanak szegények,
Csak élősködjenek!
Hiszen, ha nem csalódom,
Tán ők is emberek.','Tán én nem tudnék írni
Mindig jó verseket?
De szívem főerénye
Az emberszeretet.','Pest, 1845. február-március',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,289,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-56','petofi','Azokhoz az én jó Pesti pajtásaimhoz','Hah, börtönöm ajtaja megnyilt,
- Nem börtön-e a hivatal? -
Csókolgat a drága szabadság
Édes, tüzes ajkaival.
De lelkem hová lett?... merre, o lélek,
Szárnyad suhogási merre vivének?

Mi messze, mi messze röpülsz már,
Végetlen előtted az ut;
Hiába suhanna utánad
A fecske, nyomodba se'' jut.
El lelkem után a messze világba!...
De vissza mi tart? szív, monddsza, mi bánta?

Távozni! e gondolat úgy fáj,
Úgy fáj nekem... és mi okért?
Volt itt szeretőm, hanem az már
A sírhalom éjibe tért.
És nem vagyok én már senki barátja.
E puszta üres szót lelkem utálja.

Pajtásaim! értetek a bú;
Elhagyni, fiúk, titeket,
Ez fáj nekem, ez szomorít el,
Ez ver kebelembe sebet...
De nem! mi vigadtunk minden időben,
Igy hát szomorú a búcsu se légyen.

Föl, cimboraság, vigalomra,
S pogány legyen a vigalom:
A bút kiürült poharakkal
Kegyetlenül üssük agyon,
Hogy, majd ha jön a sor kézszoritásra,
Őt könnyre fakadni senki ne lássa!','Hah, börtönöm ajtaja megnyilt,
- Nem börtön-e a hivatal? -
Csókolgat a drága szabadság
Édes, tüzes ajkaival.','Pest, 1845. március végén',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,290,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-57','petofi','Mi kék az ég!','Mi kék
Az ég!
Mi zöld
A föld!
Zöld föld felett, kék ég alatt a
Hangos pacsírta fütyörész:
Dalával a napot kicsalta,
A nap rá gyönyörködve néz.

Mi kék
Az ég!
Mi zöld
A föld!
Zöld a föld, kék az ég, tavasz van...
És én oly sült bolond vagyok,
Hogy idebenn a szűk szobában
Kadenciákat faragok!','Mi kék
Az ég!
Mi zöld
A föld!','Eperjes, 1845. április',1845,'1845',array['Természet']::text[],'{}'::text[],false,291,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-58','petofi','Ki a szabadba!','Ki a szabadba, látni a tavaszt,
Meglátni a természet szinpadát!
Az operákban ki gyönyörködik?
Majd hallhat ott kinn kedves operát.

A természetnek pompás szinpadán
A primadonna a kis fülmile;
Ki volna, énekesnők! köztetek
Merész: versenyre kelni ővele?

Megannyi páholy mindenik bokor,
Amelyben űlnek ifju ibolyák,
Miként figyelmes hölgyek... hallgatván
A primadonna csattogó dalát.

És minden hallgat, és minden figyel,
És minden a legforróbb érzelem...
A kősziklák, e vén kritikusok,
Maradnak csak kopáran, hidegen.','Ki a szabadba, látni a tavaszt,
Meglátni a természet szinpadát!
Az operákban ki gyönyörködik?
Majd hallhat ott kinn kedves operát.','Eperjes, 1845. április',1845,'1845',array['Természet']::text[],'{}'::text[],false,292,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-59','petofi','Magyarország','Te sem termettél ám szakácsnak,
Magyarország, édes hazám!
A sűlt egy részét nyersen hagynád,
S elégetnéd más oldalán.
Mig egyfelől boldog lakóid
Megfúlnak a bőség miatt:
Hát másfelől meg éhhalállal
Megy sírba sok szegény fiad.','Te sem termettél ám szakácsnak,
Magyarország, édes hazám!
A sűlt egy részét nyersen hagynád,
S elégetnéd más oldalán.','Eperjes, 1845. április',1845,'1845',array['Haza']::text[],'{}'::text[],false,293,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-60','petofi','Mi bűvösbájos hang...','Mi bővösbájos hang?
Völgyben csendült meg ünnep-est harangja?
Mely a buzgó falut
Imádkozásra szentegyházba vonja;

Vagy lelkem álmaiban
Cseng édesbús emléke a lyánykának?
Ki szép és ifju volt
S kinek sírjára könnyeim folyának.','Mi bővösbájos hang?
Völgyben csendült meg ünnep-est harangja?
Mely a buzgó falut
Imádkozásra szentegyházba vonja;','Eperjes, 1845. április',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,294,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-61','petofi','Felsülés','Ebédre hítak. Elfogadtam
A meghivást nagy szívesen,
Nem az ebédre nézve,
Hanem mert vettem észre,
Hogy köztünk szép lyány is leszen.

S volt szép lyány, mégpedig milyen szép!
Könnyű lehellet termete,
Fehér egén szemének
Sötétkék napok égtek...
De ez nem tartozik ide.

Csak hogy szép lyányka volt, nagyon szép,
S én őt tüstént megszeretém.
"Kigyúlt indúlatommal
Ebéd után azonnal
Kirontok!" így elmélkedém.

Ebéd alatt erősen szítam
A szíverősítő italt,
Hogy a nagy pillanatban
Majd annál biztosabban
Vívhassam ki a diadalt.

De hah, a szíverősítő ugy
Megerősíté szívemet,
Hogy, az erőből aztán
Lábamban nem maradván,
Kirontanom nem lehetett.','Ebédre hítak. Elfogadtam
A meghivást nagy szívesen,
Nem az ebédre nézve,
Hanem mert vettem észre,','Eperjes, 1845. április',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,295,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-62','petofi','Az erdei lak','Költői verseny Kerényi és Tompával

Mint a szív az első szerelemnek titkát,
Rejti a kis kunyhót bércek koszorúja;
Meg nem árt erőtlen szalmafödelének,
Ha dühét a szélvész e vidékre fúja.

Szalmafödelét beárnyékozza hűsen
Susogó erdőség rezgő lombozatja,
Min magát a vígan fütyölő rigófaj
És a búsan búgó vadgalamb ringatja.

Mint a kergetett őz, fut le gyors futással
Kis patak magasról a völgy mélységébe;
Kétfelől virágok, mint kacér leánykák,
Kandikálnak a víz fényes tűkörébe.

S a viráglyánykákhoz jőnek az imádók,
Égő szenvedéllyel jőnek a vadméhek,
S élveznek szerelmet. Hej, de sok megjárja!
Vízbehullás vége részeg örömének.

A nap és a szellő szánakozva nézi;
Levelet hajít le a szellő, számára,
És ha fennűl már ez életmentő sajkán,
Megszárítja szárnyát a jó nap sugára.

A hegyek tetőin duzzadó emlőkkel
Jár az anyakecske gödölyéi mellett.
Kikerűlt ettől s a vadméhektől mindig,
Mi a kunyhó kicsiny asztalára kellett.

S búgó vadgalamb és fütyölő rigófaj
Nem félnek, hogy őket csalják lépvesszőre...
Önmagáról tudja e lak népe, milyen
Édes a szabadság tiszta levegője.

Nincsen itten rabság, nincsen itten urkény,
Mely parancsolatját mennydörögve adja;
Csak az égiháborúnak zeng koronként
Istentiszteletre buzdító szózatja.

És az isten jó, ő nem soká haragszik:
A dorgáló felhők torkait bezárván,
Újolag mosolyg... a megengesztelődött
Isten mosolygása: tündöklő szivárvány.','Költői verseny Kerényi és Tompával
Mint a szív az első szerelemnek titkát,
Rejti a kis kunyhót bércek koszorúja;
Meg nem árt erőtlen szalmafödelének,','Eperjes, 1845. április',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,296,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184502-63','petofi','Van a nagy Alföldön csárda sok...','Van a nagy alföldön csárda sok.
Azok közt, akiket én tudok,
Legkülönösebb a Betekints -
Ennek széles földön párja nincs.

Menni akar, de csak dűledez,
Mint ivója, kiben sok a szesz!
Födele is félre van csapva,
Mint a részeg ember kalapja.','Van a nagy alföldön csárda sok.
Azok közt, akiket én tudok,
Legkülönösebb a Betekints -
Ennek széles földön párja nincs.','Késmárk, 1845. május 3.',1845,'1845',array['Természet']::text[],'{}'::text[],false,297,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-64','petofi','Paripámnak az ő színe fakó...','Paripámnak az ő színe fakó,
Szőre, mint a vert arany, ragyogó;
Paripámnak az ő neve Csillag,
Gyors a lába, mint a hullócsillag.

Hej szép lovam, hej jó lovam, fakó!
Hol az egyik lábadról a patkó?
Hadd vigyelek, lovam, a kovácshoz,
Azután majd vígy el a rózsámhoz.

Hej, tüzes a kovácsnak a szene,
De tüzesebb rózsámnak a szeme.
Hej, lágy a vas a kovács szenétől,
Lágyabb szivem a rózsám szemétől.','Paripámnak az ő színe fakó,
Szőre, mint a vert arany, ragyogó;
Paripámnak az ő neve Csillag,
Gyors a lába, mint a hullócsillag.','Igló, 1845. május',1845,'1845',array['Természet']::text[],'{}'::text[],false,298,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-65','petofi','Fresco-ritornell','Mihelyt megpillantottalak, menyecske,
Bordám alatt ez a kis húsdarab
Ugrálni kezdett, mint sziklán a kecske.

Azóta mellem folyton égő katlan,
S a láng mindig tovább, tovább harap...
Csak te ne volnál oly meggyujthatatlan!

Kebled fehérlő, mint az alabastrom,
De búm sötét, mint holmi ócska klastrom,
S csak a halál lesz dúlt szivemre flastrom.','Mihelyt megpillantottalak, menyecske,
Bordám alatt ez a kis húsdarab
Ugrálni kezdett, mint sziklán a kecske.
Azóta mellem folyton égő katlan,','Igló, 1845. május',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,299,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-66','petofi','Egy asszonyi állathoz','Megláttuk egymás és a szerelem
Mindkettőnk szívében lobbot vetett,
Fölösleges volt minden vallomás,
Értők a kölcsönös tekintetet.
Alig mult egy nap, már csókoltalak.
S te visszacsókolál és ölelél.
Te is leány vagy, édes angyalom,
Egy szikrával sem jobb a többinél.

Miként folyammá nő a kis patak,
S miként tengerbe vész el a folyam:
Szerelmem akkép napról-napra nőtt,
S lett végre tenger, mély, határtalan.
Láttam pirúló arcod hajnalán,
Hogy boldogságom napja ujra kél.
Te is leány vagy, édes angyalom,
Egy szikrával sem jobb a többinél.

Boldogságomnak napja ujra kelt.
Boldogság napja volt égő szived,
Amely szemedbe szállt, s onnan reám
Elolvasztó sugárokat vetett.
Minő boldogság volt, ha háborgó,
Fölindult kebleden pihentetél!
Te is leány vagy, édes angyalom,
Egy szikrával sem jobb a többinél.

Együttlétünknek végső napja jött.
Tán mindörökre válandók valánk;
De gondolám, nyugtatva magamat:
Vár még egy este boldogsága ránk.
Az este eljött. Épen bál vala,
Te bálba mentél, hozzám nem jövél.
Te is leány vagy, édes angyalom.
Egy szikrával sem jobb a többinél.','Megláttuk egymás és a szerelem
Mindkettőnk szívében lobbot vetett,
Fölösleges volt minden vallomás,
Értők a kölcsönös tekintetet.','Igló, 1845. május',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,300,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-67','petofi','A. B. emlékkönyvébe','Kalmáridőket élünk mostanában,
Egy pénzdarabnak nézik a világot,
S ha a világ pénz, a költő mi rajta?
A költő - mondják - hasztalan penész csak.
Pedig a költő a királyi kép a
Világ tallérján... nem, királyi kép sem!
Ő a tallérnak csengő, tiszta hangja,
Szép szellemrésze a hitvány anyagnak. -
Légy büszke rá, hogy költőnek születtél.','Kalmáridőket élünk mostanában,
Egy pénzdarabnak nézik a világot,
S ha a világ pénz, a költő mi rajta?
A költő - mondják - hasztalan penész csak.','Vár-Gedő, 1845. június 1-13. között',1845,'1845','{}'::text[],'{}'::text[],false,301,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-68','petofi','P.....y Vilma kisasszonyhoz','Ifju szivecskéd legelőször játsza
A szerelemnek szép játékait.
Gyönyör nekem e játék láthatása,
Nem én vagyok bár, akit boldogit.

Ki is ne volna lelkesült néző ott,
Hol a sziv első mozdulásra kél?
Nem olyan-é ez, mintha rózsabokrot,
Virító rózsabokrot ráz a szél?

Az égő szív, ez a rózsának bokra,
Lengő fuvalmak érzeményei,
S hull a bokorról a halvány arcokra
Piros levél, ha a szél lengeti.

Ha szép orcádat ekkép égni látom,
Oh lyányka, szíved érzeményitül:
Derűl kissé az én sötét világom,
Mit szerelemnek napja elkerül.

Költőkebelnek nem szolgál szerencse;
Tudod szerelmem bús történetét:
Volt életemnek egy királyi kincse,
Koldús vagyok, mert azt eltemeték.

Szempilláidnak fekete virágán
A részvét könnyharmatja reszketett,
Midőn előtted szívemet kitárám
És elbeszélém e történetet.

Ekkor, leányka, jó leányka, téged
Édestestvéreműl fogadtalak.
Kössük meg ezt a drága szövetséget
Egy csókkal, Vilmám, és én áldalak.

Különben is te voltál, aki mondád,
Hogy megcsókolni a költőt szabad;
Szép állításod, lyányka, teljesítsd hát:
Tedd ajkaimra testvércsókodat!','Ifju szivecskéd legelőször játsza
A szerelemnek szép játékait.
Gyönyör nekem e játék láthatása,
Nem én vagyok bár, akit boldogit.','Losonc, 1845. június 14-22. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,302,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-69','petofi','A varróleány','Varróleány a szeretőm,
Azaz, hogy én őt szeretem,
Oly fennhangon kiáltja ezt
Vadúl ugrándozó szivem,
Hogy semmi kétség benne. -
Bolondos egy história talán;
De már egyéb nincs hátra;
Szeress te is, te szép varróleány!

Szép vagy, de szép orcáidat
Az ember addig nézi csak,
Amíg nem látja sugarát
Lelked dicső villáminak.
Minden szavad egy villám,
Mely szem fényét ölő szikrákat hány;
Nem ismerem még párod
Az elmésségben, szép varróleány!

S azonkivűl hogy tündökölsz
Az elmésség sugáriban:
Ki oly könnyen megbukhatál.
Erényednek közhíre van.
Elmés vagy, mint az ördög,
S jó, mint az angyal... hogyne hajtanám
Meg térdeim előtted,
Te szép, elmés, te jó varróleány!

Meghajtom íme térdemet,
Emelj föl engem szívedig;
Ennél följebb nem vágyok én,
Hisz ott a menny, a hetedik.
Itt várok térdepelve,
Ruházd a "szerető" cimet reám,
Vagy varrd meg szemfedőmet,
Ha nem szeretsz, te szép varróleány!','Varróleány a szeretőm,
Azaz, hogy én őt szeretem,
Oly fennhangon kiáltja ezt
Vadúl ugrándozó szivem,','Losonc, 1845. június 15-22. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,303,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-70','petofi','Messze vándoroltam...','Messze vándoroltam, elhunyt édes lelkem,
De mindig, mindenütt, ahol jártam-keltem,
Bánatos emléked, mint egy sötét fátyol
Huzódott utánam sírodnak halmátol.

Visszajöttem hozzád. Csókot nem adhattam
Nyájas idvezletül; mélyen vagy alattam.
Lehajtom fejemet árvafűz módjára,
Nem lágy kebeledre, de kemény fejfádra.

Játszanak ujjaim, nem szőke hajaddal,
Tán már hamvaidból sarjadt fűszálakkal;
És hallok suttogást, nem kedves ajkadét,
Hallom suttogni csak a temető szelét.

Ekképen merengek sírod csendes halmán,
A lefolyt időre nyugodtan gondolván.
Nyugodt már kebelem. Fájdalmam szélvésze
Kitombolt, elzúgott, megszűnt, elenyésze.

Alvó tenger a mult. Halálod a kőszirt,
Amelyen reményim sajkája kettétört,
Ez a durva kőszirt most már olyan szépen
Áll a látkör végén a kék messzeségben;

És állani fog az szemem előtt váltig.
Szívemen lesz képed, Etelkém, halálig!
Függni fog szívemen képed, mint domború
Sírodnak fejfáján e hervadt koszorú.','Messze vándoroltam, elhunyt édes lelkem,
De mindig, mindenütt, ahol jártam-keltem,
Bánatos emléked, mint egy sötét fátyol
Huzódott utánam sírodnak halmátol.','Pest, 1845. június 25.',1845,'1845',array['Elmúlás','Természet']::text[],array['osz']::text[],false,304,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-71','petofi','Szerelemvágy','Szeretnék már szeretni újolag...
Mit ér a kert, ha rózsát nem terem?
Ha szerelemmel nem diszeskedik,
Mit ér az élet, ifjuság nekem?

Szerettem én, s csak búját érezém
A szerelemnek mind ez ideig,
S e bú mindennél édesebb vala,
Mire szivem csak emlékezhetik.

Oh istenem, ha gyötrelmében is
Ily boldogító már a szerelem:
Hát akkor még minő lehet, ha a
Szívben szelíd mosolygással pihen!

Lelkem bolyongó, hontalan madár,
Keresve száll: fészkét hol rakja meg?
Hol a leányszív, amely megnyilik
Tanyát ohajtó érzeményinek?

De bár szeretni vágyok újolag,
A holt leánykát nem feledtem el...
A hegytetőn még űl a téli hó,
Midőn tövében már virág fesel.','Szeretnék már szeretni újolag...
Mit ér a kert, ha rózsát nem terem?
Ha szerelemmel nem diszeskedik,
Mit ér az élet, ifjuság nekem?','Pest, 1845. június 25. - július 10. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,305,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-72','petofi','Egy szép hölgy emléke','Ládámat tolvajtól nem féltem én,
Mert oly üres, mint sok tudós feje.
Szivemben hordom kincseim... szivem
Sok szép emlék kincsével van tele.

Ah, mon dieu, ha végiggondolom
Egy gőzhajói útazásomat:
Minő boldogság!... útitársamúl
Egy gyönyörűséges szép hölgy akadt.

Hölgyek körűl én szégyenlős vagyok,
Előbb tehát csak némán bámulám;
Elszántam végre magamat, mivel
Oly nyájasan pillantgatott reám.

Kitudtam a beszélgetés között,
Hogy ő német szinésznő s Pestre mén...
Hohó, szinésznő, már kész a kaland!
Háborgó szívvel ezt gondoltam én.

S ebédre mentünk. Az ebédnél a
Szép hölgy bevágott vagy két itce bort.
Hanem dicséretére mondhatom:
Nem is látszott meg rajta, hogy ivott.','Ládámat tolvajtól nem féltem én,
Mert oly üres, mint sok tudós feje.
Szivemben hordom kincseim... szivem
Sok szép emlék kincsével van tele.','Pest, 1845. június 25. - július 10. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,306,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-73','petofi','Rég veri már a magyart a teremtő...','Rég veri már a magyart a teremtő,
Azt sem tudja: milyen lesz a jövendő?
Lesz-e még ezen a földön jó napja?
Örüljön-e, búsuljon-e? nem tudja.

De ha isten bút adott e nemzetnek,
Azt is adott, mivel a bút ölje meg.
Hol terem több jó bor és több szép leány,
Mint itt, belül Magyarország határán?

Leányt ide, leányt az én ölembe!
Hadd szorítsam két kezemmel szivemre,
Hadd szíjam ki édes lelkét csókommal.
Vessek számot sok keserű bajommal.

Hát az a bor? hej, a borral ide már;
Sírja belém piros könnyét a pohár!
Piros könnye tüzes, mint istennyila,
A kialudt életet is meggyujtja.

Te meg, cigány, húzd rá, majd kifizetem;
De úgy húzd, hogy megrepedjen a szivem.
Repedjen meg örömébe'', bujába''...
Igy vigad a magyar ember, hiába!','Rég veri már a magyart a teremtő,
Azt sem tudja: milyen lesz a jövendő?
Lesz-e még ezen a földön jó napja?
Örüljön-e, búsuljon-e? nem tudja.','Pest, 1845. június 25. - július 10. között',1845,'1845',array['Haza','Szerelem']::text[],'{}'::text[],false,307,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-74','petofi','Líliom Peti','Líliom Peti volt ám csak
A derék legény!
Alig akadt volna párja
A föld kerekén.

Emberül megűlt ő minden
Paripa hátán;
Le nem vetette volna a
Hétfejű sárkány.

Amennyi bor öt más embert
Döntött volna meg:
Annyi még jóformán meg se
Kottyant Petinek.

S ahol vele elvágtatott
Gyors paripája,
Majd megveszett a falusi
Lyányság utána.

De nyakravalója lett a
Hóhér kötele...
Mért? azért, mert Angyal Bandi
Lelke bújt bele.','Líliom Peti volt ám csak
A derék legény!
Alig akadt volna párja
A föld kerekén.','Pest, 1845. június 25. -július 10. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,308,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-75','petofi','Holdvilágos éj','A hold az égen egy ezüst lant,
Megannyi húr a sugarak;
A hold ezüst lantján a szellők
Szellemkezekkel játszanak.

Egy faluhoz közelg a vándor,
Egyúttal költő is talán?
Mert úgy elandalodva csügg a
Holdon s elömlő sugarán.

Megy, megy tovább a méla vándor,
S eléri végre a falut;
A faluban csend, néma csend van,
Népsége régen elaludt.

A kántor háza kapujánál
Szép hajadon leány zokog;
Az este hűs... ő pongyolában...
Reszketnek a gyöngéd tagok.

A vándor arra ballag és szól:
"Mi lelt, mi lelt, szép hajadon?
Felelj, legszebbik holdsugár te,
Segíthetek-e bajodon?

Hűségtelen kedvest siratsz tán?
Ha én lehetnék kedvesed,
Olyan lennék, hogy a világ még
Nem láta oly hűségeset.

Légy holdvilágom, szép leányka!
S nem bánom: a sors bármit ad;
Legyen örök éj létem... csak hogy
Örökké lássam holdamat!"

Igy szólt a vándor lelkesedve,
De a leányka nem felel;
Csak áll és némán nehezíti
Kis kendejét könyűivel.

A hold a kántor szobájába
Sugárait most beveti;
A kántor, a lyány részeg apja,
Benn feleségét döngeti.','A hold az égen egy ezüst lant,
Megannyi húr a sugarak;
A hold ezüst lantján a szellők
Szellemkezekkel játszanak.','Hatvan, 1845. július 10-12. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,309,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-76','petofi','Fekete kenyér','Miért aggódol, lelkem jó anyám,
Hogy kenyeretek barna, e miatt?
Hisz meglehet: ha nincs idehaza,
Tán fehérebb kenyérrel él fiad.
De semmi az! csak add elém, anyám,
Bármilyen barna is az a kenyér.
Itthon sokkal jobb ízü énnekem
A fekete, mint máshol a fehér.','Miért aggódol, lelkem jó anyám,
Hogy kenyeretek barna, e miatt?
Hisz meglehet: ha nincs idehaza,
Tán fehérebb kenyérrel él fiad.','Szalkszentmárton, 1845. július 13-21. között',1845,'1845',array['Család']::text[],'{}'::text[],false,310,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-77','petofi','Búcsu kunszentmiklóstól','Szól a kakas innen-onnan
Viradóra.
Kivígadtunk, takarodjunk
Nyugovóra.
Hej, ennek a mai napnak
Nagy az ára...
T''om: sokáig fáj belé a -
Fáj belé a kezem szára.

Fáj az én jobbkezem szára
Véghetetlen,
Mert nagyon sok telt palackot
Emelgettem.
De ha fáj is a karom, tán
Utójára
Fölbirom még e palackot -
E palackot... bucsuzásra.

Ki veled, bor, ki veled, bor,
Az üvegből!
Telesírom könnyeimmel
Két szememből;
De magam sem tudom én, hogy
Majd az benne
Fájdalomnak vagy örömnek -
Vagy örömnek lesz-e könnye?

Mostanában a keblemnek
Megtelése
Fájdalomnak és örömnek
Vegyülése.
Az örömem onnan ered,
Mert itt voltam;
El kell mennem: innen ered -
Innen ered a fájdalmam.

Kiskunsági Szentmiklósnak
Ifju népe!
Benyitottál a szivemnek
Közepébe;
Hej, pedig e szivközép, ez
Szentek szente,
Nem sok ember fordult meg még -
Fordult meg még eddig benne.

De kinek meg helyet adtam
Egyszer itt benn,
Az ugyan ki soha többé
Nem megy innen.
Ezután úgy nézzetek hát
A szemembe:
Rabok vagytok mindörökre -
Mindörökre a szivembe''!

Hát közöttetek, ha újra
Visszatérek,
Lesz emléke e barátság
Ünnepének?
Ünnep volt ez, a barátság
Szép ünnepje,
Nem is hiszem, hogy valaki -
Hogy valaki elfeledje.

Mostanáig itt vígadtunk
Tennap déltül,
Nem csoda hát, ha kissé a
Fejem szédül...
De azért jól tudom ám, hogy
Mit miveltünk?
Ettünk, ittunk, táncot jártunk -
Táncot jártunk, énekeltünk.

Ilyen a magyar mulatság,
Már hiába!
Ha iszik, hát jár a nyelve,
Jár a lába.
Hej, csak oly gyors lenne honja
Haladása,
Mint lábának, hogyha táncol -
Hogyha táncol, a mozgása!

Hanem hiszen száz szónak is
Egy a vége:
Legyen rajtatok, barátim,
Áldás, béke.
Legyen oly vig mindhalálig
A pályátok,
Amily vígak valamennyin -
Valamennyin ma valátok!

... Hej ha volna ősz; elszállna
Már a gólya;
Mennék én is már, ha még egy
Szóm nem vóna.
Kimondjam-e vagy ne mondjam?
Eh, kimondom;
Mit szóltok rá, mit nem szóltok -
Mit nem szóltok, semmi gondom.

Amott virít Szentmiklósnak
Egy rózsája...
Hej csak soha ne is néztem
Volna rája!
Vagy ha már megbűvölt édes
Arculatja:
Hadd lennék én, aki őtet -
Aki őtet leszakasztja!','Szól a kakas innen-onnan
Viradóra.
Kivígadtunk, takarodjunk
Nyugovóra.','Kunszentmiklós, 1845. június 23.',1845,'1845',array['Ünnep']::text[],'{}'::text[],false,311,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-78','petofi','A honderühöz','Oh Honderü, te Lázárok Lázára,
Te csak nevednek két bötüje vagy,
Nevednek vagy csak két végső bötűje...
Huzd meg magad, nehogy tovább ragadj.
E két bötű elől, hátúl olvasva
Egyformán mondja meg mi-létedet.
De én becsüllek! mert hisz aranyával
Fizetted egykor költeményimet.

Oh Honderü, te olyan szemtelen vagy,
Mint Kecskemétnek piacán a légy;
Egyébiránt alávalóbb a légynél:
Az még röpül, te csuszva, mászva mégy.
De minden ember nem néz láb alá, majd
Elgázolnak... vigyázz, mondom neked!
Javad kivánom! mert hisz aranyával
Fizetted egykor költeményimet.

Oh Honderü, mi aztán a jutalmad
E sok jeles tulajdonságidért?
Hiába, olyan a világ, mint régen:
Az érdem becsüléséhez nem ért.
Lám annyi útál tégedet, ki a hont
Ha nem deríted is, de dőrited.
Szegény! Sajnállak... mert hisz aranyával
Fizetted egykor költeményimet.

De, Honderü, te vélem összetűztél,
Te általad váltig karmoltatom...
Mióta van, hogy meri ingerelni
A hős oroszlánt a hitvány majom?...
... De megbocsátok, hogy muzsámat mostan
Oly irgalmatlanúl becsméreled;
Hisz aranyával fizetéd, s fizetnéd
Most is (ha adnám) költeményimet.','Oh Honderü, te Lázárok Lázára,
Te csak nevednek két bötüje vagy,
Nevednek vagy csak két végső bötűje...
Huzd meg magad, nehogy tovább ragadj.','Pest, 1845. augusztus elején',1845,'1845','{}'::text[],'{}'::text[],false,312,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-79','petofi','Képzetem','Még mit nem mondanak!
Hogy az én képzetem
Alant jár, magasra
Föl nem röpíthetem.
Lent jár a föld szinén,
Ha ugy tartja kedve,
Sőt a föld alá is
Van gyakran sülyedve;
Mint buvár, sülyed a
Mélységek mélyére,
A legmélyebb tenger:
A szív fenekére.
De ha mondom neki:
"Szállj a magasra fel!"
Felszáll s a légben mint
Pacsirta, énekel.
S ha ekkor biztatom:
"Még följebb, képzetem!"
Vele a sasokat
Rendre megkergetem.
A sas mind elfárad,
De nem fárad ő el,
Egy utat kezd a leg-
Magasabb felhővel.
És a felhőknek sem
Társa ő sokáig,
Egyenest fölfelé
Tör az ég boltjáig,
És ha ekkor épen
Napfogyatkozás van:
Az elsötétedett
Nap mellett elsuhan,
Elsuhan mellette,
Egyet pillant rája,
S megkerűl a napnak
Elveszett pompája.
És az én képzetem
Még ekkor sem pihen,
Hanem a legfelső
Csillagzaton terem,
S ott, hol már megszűnik
Az isten világa,
Uj világot alkot
Mindenhatósága - -','Még mit nem mondanak!
Hogy az én képzetem
Alant jár, magasra
Föl nem röpíthetem.','Pest, 1845. augusztus elején',1845,'1845',array['Természet']::text[],'{}'::text[],false,313,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-80','petofi','Gyalázatos világ','Gyalázatos világ! mit nem gondolsz ki még?
Hogy szívemet sebezd...
De mért panaszlanék?
Hisz ami megtörtént: mind, mind várhattam ezt.
Az én pályám nem mindennapi pálya,
S ki új utat tör: gaz és tüske várja.

Uj pályámon paréj, tövis közt gázolok;
De megyek egyaránt,
Bár fájdalmas dolog,
Ha sziszegő kigyók mérges fulánkja bánt.
(Az én utamban sok a kígyófészek
S hogy eltiporjam, én beléje lépek!)

Jó, hogy sebemre az ég orvosságot ad.
Keblem varázsfüve
A büszke öntudat,
Mely tőlem már oly sok fájdalmat elveve.
Ha ez nem volna, a kígyók marása
Eddig szivemnek közepében ásna.

Mardossatok csak hát, ti kígyófajzatok!
Eltiprom köztetek,
Kit eltiporhatok,
S akit nem: azt majd az idő gyilkolja meg;
Mert az idő a jobb lelkek segéde,
Kiáll ezeknek védelmezésére.

Idő, hű gyámolóm! benned megbízhatom,
Ha úton-útfelen
Sárral dobáltatom...
Ha senki nem lesz is, leszesz te majd velem;
Amelyet a szennyes világ dobott rám,
Megtisztitod te majd a sártul orcám!','Gyalázatos világ! mit nem gondolsz ki még?
Hogy szívemet sebezd...
De mért panaszlanék?
Hisz ami megtörtént: mind, mind várhattam ezt.','Pest, 1845. augusztus',1845,'1845',array['Természet']::text[],'{}'::text[],false,314,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-81','petofi','Egy hajfürthöz','Barna lyányka szép fejéről
Kaptam e hajfürtöt én.
Én s e fürt együtt pihentünk
A leányka kebelén.

A bucsúnak órájában
Adta emlékül nekem;
A bucsú órája óta
Mindig itt volt szívemen.

Oh ha nézem e hajfürtöt:
Minden perc eszembe jut,
Melyben a boldogság szárnyán
Mennybe nyilt előttem ut;

A letűnt szerelmi órák
Körülöttem lengenek,
Mint vidám csillagsugáros
Túlvilági szellemek.

Nézlek, nézlek, drága hajfürt.
Hosszan nézlek tégedet,
Aki üdvem holt időjét
A sírból kivezeted.

Hosszan függenek terajtad,
Oh szép hajfürt, e szemek,
Hosszan... hosszan... és... utószor...
Minthogy már... mást szeretek.','Barna lyányka szép fejéről
Kaptam e hajfürtöt én.
Én s e fürt együtt pihentünk
A leányka kebelén.','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,315,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-82','petofi','Szép vidéknek szépséges leánya...','Szép vidéknek szépséges leánya!
Eszem azt a gyönyörű szemed -
Gyönyörű? nem! csak azért sem az, mert
Hazugságban hagytál engemet.

Hányszor mondtam, hányszor irtam én meg,
Hogy már láttam tiszta kék eget!
S ez hazugság, mert nem láttam addig,
Míg nem láttam a te szemedet.

Vetted észre? mily hosszan merengtem
S milyen áhitattal szemeden?
Áhitattal függtem rajta, mint a
Haldokló szent a feszűleten.

S te valóban megváltóm lehetnél,
Mindazáltal nem halnál te meg:
Holt, hideg fán nem függnél... ölelned
Kéne élő, égő keblemet...

Mit beszélek? mit mondtam?... szerelmet
Tőled én nem, oh, nem várhatok!
Szerelemmel a szegény költőre
Áldást hozni melyik lyányka fog?

Mert szegénynek alkotá az isten
A költőt, s tán rendén is van ez:
Tarka, pompás toll nem ékesíti
A madárt sem, amely zengedez.

Igy a költő egyszerűségében
Képes-e lyányt meghódítani?
Tündökölni vágynak a leányok,
S méltán... ők a föld csillagjai.

Te, leányka, az én csillagom vagy,
S tőlem senki nem tilthatja meg:
Ha keblemre nem tűzhetlek is, hogy
Szemeimmel ne kisérjelek.

Fog kisérni szemeim világa,
Fog kisérni vándorútamon.
A távolból ha nem melegítesz:
Legalább nézz rám, szép csillagom!','Szép vidéknek szépséges leánya!
Eszem azt a gyönyörű szemed -
Gyönyörű? nem! csak azért sem az, mert
Hazugságban hagytál engemet.','Pest, 1845. augusztus',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,316,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-83','petofi','Megteremtéd lelkem új világát...','Megteremtéd lelkem új világát,
Szerelem dicső világa ez!
Hálából e szív, örök tüzével,
Istenséged szent oltára lesz.

Oh leányka, ha te nem szeretsz is,
Engedd meg, hogy szerethesselek,
Mert különben köztem s a világ közt
Megszakadnak minden kötelek.

Vad, sötét föld keblem birodalma,
Fejedelme gyűlölő harag,
Harcban állok a nagy mindenséggel -
Szeretetre csak képed marad.

Képed a fény, az egyetlenegy fény,
Mely keblemnek éjjelébe jár,
Mint a rabhoz, földalatti börtön
Kisded ablakán, a napsugár.

Én szeretlek! bár tudom: mily rém a
Nem viszonzott szerelem baja;
De kit annyi rém gyötör, szivemnek
Könnyű lesz ezt is megszoknia.

Nem viszonzott szerelem keserve!
Türelemmel hordom terhedet,
Mint az istenember a keresztfát,
Melyen aztán megfeszittetett.','Megteremtéd lelkem új világát,
Szerelem dicső világa ez!
Hálából e szív, örök tüzével,
Istenséged szent oltára lesz.','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,317,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-84','petofi','Éj van...','Éj van, csend és nyúgalomnak éje,
A magas menny holdas, csillagos;
Szőke gyermek, kékszemű kökényfa,
Drágagyöngyöm! mit csinálsz te most?

Engem édes álmak környekeznek,
De nem alszom, ébren álmodom.
Minden álmam egy fényes királyság,
S koronája te vagy, angyalom!

Be szeretném most, ha lopni tudnék,
A lopás bármily rút lelki folt!
Meglopnám az álmak kincstárát, hogy
Gazdagítsam a szegény valót.','Éj van, csend és nyúgalomnak éje,
A magas menny holdas, csillagos;
Szőke gyermek, kékszemű kökényfa,
Drágagyöngyöm! mit csinálsz te most?','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,318,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-85','petofi','Félre mostan...','Félre mostan, hagyjatok magamra,
Hagyjatok, ti régi cimborák!
Nem látjátok, hogy mi lett belőlem?
Címerem most rózsa s nem borág.

Szerelemnek katonája lettem...
A lant, a dal töltött fegyverem,
Töltés benne forró érzeményem,
Boldog én! ha a csatát nyerem.

Oh, ha nyernék, istenem, ha nyernék...
Tündérország, mely előttem áll;
Sikerüljön ezt bevennem: akkor
Én leendek a tündérkirály!','Félre mostan, hagyjatok magamra,
Hagyjatok, ti régi cimborák!
Nem látjátok, hogy mi lett belőlem?
Címerem most rózsa s nem borág.','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,319,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-86','petofi','Ablakodból hogyha...','Ablakodból hogyha kitekintesz:
Kertet látsz csak, kertet és eget.
(Adja isten, hogy legyen hasonló
E látmányhoz teljes életed!)

Képzelem: mily boldog vagy, leányka,
Hogy körűled ilyen kert virít.
Jaj, de e kert sokkal boldogabb még,
Mert beléje néznek szemeid.','Ablakodból hogyha kitekintesz:
Kertet látsz csak, kertet és eget.
(Adja isten, hogy legyen hasonló
E látmányhoz teljes életed!)','Gödöllő, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,320,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-87','petofi','Nála voltam...','Nála voltam, a kedves leánynál.
Nála voltam, ismét eljövék.
Honn vagyok... honn? nem tudom. Szédűlök.
Kereng velem a föld és az ég.

Oh, mi szép, mi jó vagy te, leányka,
Szép és jó s oly lelkes honleány!
Te hazám leglelkesebb leánya,
Te hazám nemtője vagy talán.

Lyányka, neked költőt kell szeretned,
Más nem méltó birni tégedet,
Nem méltó más erre, mert hazát ugy,
Mint a költő, senki nem szeret.

Mit tegyek? szólj, üdvem gyöngyvirága,
Mit tegyek? hogy megnyerhesselek.
Kész vagyok, kész mindent elkövetni,
Mindent, hogy megérdemeljelek.

De ha semmit nem tennék is, lyányka,
Érdemetlen nem vagyok reád:
Szerelemért csupán szerelem kell,
S én szeretlek, mint te a hazát!','Nála voltam, a kedves leánynál.
Nála voltam, ismét eljövék.
Honn vagyok... honn? nem tudom. Szédűlök.
Kereng velem a föld és az ég.','Pest, 1845. augusztus',1845,'1845',array['Szerelem','Haza']::text[],'{}'::text[],false,321,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-88','petofi','Vasárnap volt...','Vasárnap volt. Nem felejtem én el
E napot. Lenn a kertben valánk.
Néztelek.. te bokrétát kötöttél,
A nap jókedvvel mosolyga ránk.

És midőn elkészült a bokréta,
Általadtad - oh, meglepetés! -
Általadtad azt nekem, leányka...
E gyönyörre minden szó kevés!

Általadtad nekem a bokrétát,
Most is itt van az szivem felett;
S ha fölhajtod egykor szemfedőmet,
Akkor is még szívemen leled.

Higgy nekem, hogy szívem és bokrétád
Egy időben, együtt hamvad el...
Milyen édesen fog majd pihenni
Ő alatta e fáradt kebel!

S amig élek, addig paizsom lesz.
Oly szükséges nekem a paizs!
Most merészen állok ki, ha mindjárt
Az egész föld ostromolna is.

Rágalom, gúny, ármány, balszerencse
Szórhatnak rám millió nyilat:
Szánakozva nézem ellenségim
E tündér virágpaizs alatt.','Vasárnap volt. Nem felejtem én el
E napot. Lenn a kertben valánk.
Néztelek.. te bokrétát kötöttél,
A nap jókedvvel mosolyga ránk.','Buda, 1845. augusztus',1845,'1845',array['Természet']::text[],'{}'::text[],false,322,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-89','petofi','Drága orvos úr...','"Drága orvos úr!" szólék eszemhez,
"Látogassa meg csak szívemet;
Látogassa meg, kérem... roszul van...
És gyógyítsa ki, ha még lehet.

Nagy bizalma van szivemnek önben,
Mert ön már többször segíte rajt.
De siessen, kérem, csak siessen,
Még talán elűzheti a bajt."

És az ész, ez a jó háziorvos,
Nem késett, hanem lesietett,
És megrémült és fejét csóválta,
Meglátván a vérző beteget;

S így kiálta föl: "Fiatalember,
Mit cselekszik ön, az istenért?
Sebe mélyebb s szélesb a Dunánál -
Mért is nem vigyáz magára, mért?

De legyünk csak egy kis türelemmel,
Még talán... talán segíthetek."
Szóla, és a sebet megvizsgálván,
Abba balzsamot csepegtetett.

"Ah!" felelt a szív, "ön a reménynek
Balzsamát használja?... hagyjon föl...
Kínom szörnyü... gyógyuljak, vagy haljak!...
A reménység sem gyógyit, sem öl."','"Drága orvos úr!" szólék eszemhez,
"Látogassa meg csak szívemet;
Látogassa meg, kérem... roszul van...
És gyógyítsa ki, ha még lehet.','Pest, 1845. augusztus',1845,'1845',array['Természet']::text[],'{}'::text[],false,323,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-90','petofi','Hol van oly nagy pusztaság...','Hol van oly nagy pusztaság, mint keblem?
Oh, e puszta oly határtalan!
Jobbra, balra terméketlen föld, csak
Közepében egy élőfa van.

S hol van olyan nagy élőfa, mint ez?
Árnyat az egész világra vet!
Tudjátok: mi e roppant fa keblem
Pusztájában?... ez a gyűlölet.

El fog dőlni e világborító
Fa, ha majd egy órjás megjelen.
E világborító fát eldöntő
Óriás a boldog szerelem.','Hol van oly nagy pusztaság, mint keblem?
Oh, e puszta oly határtalan!
Jobbra, balra terméketlen föld, csak
Közepében egy élőfa van.','Pest, 1845. augusztus',1845,'1845',array['Természet']::text[],'{}'::text[],false,324,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-91','petofi','Sírba tették...','Sírba tették első szeretőmet.
Búm e síréj holdvilága volt.
Uj szerelmem, mint nap, jött ez éjre
Fölkelt a nap... halványúl a hold.','Sírba tették első szeretőmet.
Búm e síréj holdvilága volt.
Uj szerelmem, mint nap, jött ez éjre
Fölkelt a nap... halványúl a hold.','Pest, 1845. augusztus',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,325,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-92','petofi','Nő szerelmem...','Nő szerelmem, egyre nő, pedig már
Végtelen tengerré árada.
És amint nő: szaporodik benne
A szörnyeknek rémes tábora.

És ha benne a rémek mozognak,
És ha rajta szélvész vágtatott:
Föl az égre csap szilaj hulláma,
S lemos onnan minden csillagot.

És mi kelti e vihart?... az eszme:
Ha te, lyányka, nem lennél enyém!
Iszonyú ez éj és e sötétség
S villám benne égő agyvelőm.

Oh, az ily perc helyett egy öröklét
A pokolban áldás volna rám!...
Múl a vész, a tenger csendesül, ha
Ezt az eszmét elzavarhatám.

Csendesűl a tenger és lesímul,
És a tengerpartra lépek én,
S ott remények erdejében járok;
Oh, mi szép zöld erdő a remény!

A remények szép zöld erdejében
Két galamb ül s búg egy ág felett,
S én, lyánykám, azt gondolom: jövőben
E galambpár én leszek veled!','Nő szerelmem, egyre nő, pedig már
Végtelen tengerré árada.
És amint nő: szaporodik benne
A szörnyeknek rémes tábora.','Pest, 1845. augusztus',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,326,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184503-93','petofi','Meg ne ítélj...','Meg ne ítélj a találkozásról,
Mely közöttünk a legelső volt!
Mint magát ekkor viselte nyelvem:
Az nem mindig olyan néma, holt.

Ajkaimról hallhatják gyakorta
A beszéd megáradt folyamát,
S közbe-közbe tréfa úszik árján,
Mint enyelgő csónakos-család.

De midőn tevéled összejöttem,
Ajkamon szó, hang meg nem jelent.
Fergeteg ha van keletkezőben:
Megelőzi temetői csend.

Fergeteg volt itt keletkezőben,
Fergetegre készült kebelem,
S az kitört már... ontja villámlását,
Mennydörgését a vad szerelem.

Zúg, süvölt és szaggat és ront és bont
Bennem a föllázadt fergeteg...
De tűröm; tán egykor, mint szivárványt,
Látom majd viszonszerelmedet.','Meg ne ítélj a találkozásról,
Mely közöttünk a legelső volt!
Mint magát ekkor viselte nyelvem:
Az nem mindig olyan néma, holt.','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,327,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-94','petofi','Voltak sokkal jelesebbek...','Voltak sokkal jelesebbek, mint én,
Hírök mégis elfelejtve már.
Hát tirátok, dalaim, tirátok
A jövendőben vajjon mi vár?

Éltek-e ti még akkor, midőn már
Én fölöttem fűvek lengenek?
Úgy, miként a lantnak húrja, mely, ha
Elszakad, még aztán is zeneg.

Nem bánom, ha, amit eddig irtam,
Nem bánom, ha mindaz elenyész;
Csak amit tehozzád írok, lyányka,
Ezt ne bántsa elmulási vész.

S én hiszem, hogy ezt idő nem bántja:
Szent lesz minden hozzád írt dalom,
Mert hisz azok a mennyből erednek,
Kék szemedből, szőke angyalom!','Voltak sokkal jelesebbek, mint én,
Hírök mégis elfelejtve már.
Hát tirátok, dalaim, tirátok
A jövendőben vajjon mi vár?','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,328,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-95','petofi','Vadonerdő a világ...','Vadonerdő a világ körűlem,
Oly sötét, oly éktelen vadon!
Benne járok én, elfáradt vándor;
Éj van és az útat nem tudom.

Egy kicsiny fény rezg amott előttem
Ágak-bogak gyér nyilásin át;
Te vagy az, te szeretett leányka,
Követem fényednek sugarát.

Vajjon e fény mécsvilág-e - ahol
Nyughatom majd - egy csöndes tanyán?
Vagy csalóka bolygótűz csak, amely
Temetőbe... sírba visz talán?','Vadonerdő a világ körűlem,
Oly sötét, oly éktelen vadon!
Benne járok én, elfáradt vándor;
Éj van és az útat nem tudom.','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,329,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-96','petofi','Nincs jogom, hogy...','Nincs jogom, hogy féltselek, leányka,
Mert hiszen nem is vagy még enyém;
Néha mégis szerelemféltés, e
Legborzasztóbb mennykő üt belém.

Elsötétül a világ ilyenkor...
Elsötétül? nem, sőt meggyulad...
Végitélet van... az alkotó az
Angyalokkal trombitát fuvat.

Harsog az arkangyal trombitája...
Agyvelőm reng... szerteszét szakad...
Mert reám igy dörg le az itélet:
A te sorsod örök kárhozat!','Nincs jogom, hogy féltselek, leányka,
Mert hiszen nem is vagy még enyém;
Néha mégis szerelemféltés, e
Legborzasztóbb mennykő üt belém.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,330,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-97','petofi','Száz alakba...','Száz alakba öltözik szerelmem,
Száz alakban képzel tégedet.
Majd sziget vagy s vívó szenvedélyem
Mint szilaj folyam fut körüled.

Máskor ismét, édes kedvesem, hogy
Szentegyház vagy, én azt gondolom,
És szerelmem mint repkény huzódik
Fölfelé a szentegyház-falon.

Néha gazdag útas vagy s szerelmem
Mint az útonálló megrohan,
Néha meg mint jámbor alamizsnás
Lép elédbe alázatosan.

Majd a Kárpát vagy, s én ott a felhő,
S mennydörgéssel ostromlom szived.
Majd meg rózsalomb vagy, s én körűled
Csalogányként zengek éneket.

Im, szerelmem ekkép változik, de
Soha meg nem szűnik, mindig él,
S nem gyöngül, ha néha szelidebb is...
Gyakran csendes a folyó, de mély!','Száz alakba öltözik szerelmem,
Száz alakban képzel tégedet.
Majd sziget vagy s vívó szenvedélyem
Mint szilaj folyam fut körüled.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,331,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-98','petofi','Megvallom, hogy...','Megvallom, hogy én az iskolában
Rest tanúló voltam, szörnyü rest.
Légy tanítóm, jó leányka, tőled
Majd tanúlok édesörömest.

S okvetetlen tőled kell tanulnom,
Amit mostan tudni akarok,
Nem tanulják azt az iskolában,
Nem tudják azt a professzorok.

Nos, leányka, lész-e hát tanítóm?
Kell-e tőlem a professzorság?
Azt szeretném én csak megtanulni:
Mit tesz az a szó, hogy "boldogság"?

Nem kerűl ám sok fáradságodba,
Ne gondold; csak egy kis percig vársz...
Szólnod sem kell... minek?... egy tekintet
Mindent oly szépen megmagyaráz.','Megvallom, hogy én az iskolában
Rest tanúló voltam, szörnyü rest.
Légy tanítóm, jó leányka, tőled
Majd tanúlok édesörömest.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,332,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-99','petofi','Álmaimban gyakran...','Álmaimban gyakran látogatsz meg,
Életemnek legszebb álma te!
Onnan van, mert rajzolásit elmém
Minden este véled végzi be.

Te vagy elmém végső gondolatja,
Mielőtt bezárkozik szemem,
Igy az égen, mielőtt az éj jön,
A szép alkony mindig ott terem.

Hej, leányka, akarod-e tudni:
Álmaimnak foglalatja mi?
Rövid az, de oly szép!... látlak téged
Szerelemmel rám mosolygani.

Ha ez igy van, mint álmodni szoktam,
Ha szeretsz tán engem, oh leány!
Add tudtomra, kérlek, hogy ne légyen
Boldogságom álomkép csupán.

De ha nincs igy, oh, ha nem szeretsz, s tán
Kebled értem soha nem hevül:
Akkor... akkor legjobb lesz alunnom
És álmodnom véghetetlenül.

Kérem istent, hogy ne ébresszen föl
Az ítéletkor se engemet;
Jobb itt lenn csak álmodnom, hogy bírlak,
Mint a mennyben lennem nélküled!','Álmaimban gyakran látogatsz meg,
Életemnek legszebb álma te!
Onnan van, mert rajzolásit elmém
Minden este véled végzi be.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,333,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-100','petofi','Szerelemnek lobogója...','Szerelemnek lobogója szívem,
Érte két szellem viaskodik;
Rémes a harc és mindennap eltart
Kora regtől késő alkonyig.

Egyik szellem, hófehér ruhába
Öltözködve, a vidám remény;
Másik szellem a mogorva kétség,
Öltözködve hollófeketén.

Egyre vínak, és nem tudhatom még:
Győzedelmes melyikök lehet?
Attól tartok, hogy kettészakítják
E szerelmi zászlót, szívemet!','Szerelemnek lobogója szívem,
Érte két szellem viaskodik;
Rémes a harc és mindennap eltart
Kora regtől késő alkonyig.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,334,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-101','petofi','Alacsony kis ház...','Alacsony kis ház az én lakásom;
A tiéd magas, nagy palota.
Jaj nekem, jaj énnekem, leányka,
Nem emelkedhetem én oda...

De miért ne egyesülhetnénk mi?
Énhozzám le mért ne hajlanál?
Le a völgybe tér a hegy patakja,
S az égről a nap a földre száll.

Igy, mint a nap földre száll az égről,
És a völgybe hegyről a patak:
Palotádból, lelkem szép galambja,
Szállj le hozzám, hogy birhassalak!

Én hiszem, hogy boldogabb lennél te
Itt lenn nálam, mintsem odafenn.
A magasban hűvös levegő van,
A tavasz legszebb a völgyeken.

Szép tavasz vár, ha lejősz, leányka,
Szerelemnek ékes tavasza;
Nem mulandó e tavasz viránya,
Mint az, melyet a május hoza.

A mezőkre jő az ősz és hervaszt,
Ahol látja a virágokat.
Titkos, rejtett kert szivem szerelme,
A hervasztó ősz rá nem akad.

Kell-é e kert, lyányka, és lejősz-e
Hajlékomba?... szűk s kicsinke bár:
Oh azért megférünk benne ketten,
Mint fészkében a páros madár.

Jőj le, lyányka, nem törődöm azzal,
Ha otthagyod minden ékszered...
Mért is volna rajtad ékszer? úgyis
Elhomályosítja azt szived.','Alacsony kis ház az én lakásom;
A tiéd magas, nagy palota.
Jaj nekem, jaj énnekem, leányka,
Nem emelkedhetem én oda...','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Szerelem']::text[],array['tavasz']::text[],false,335,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-102','petofi','Mihelyest megláttalak...','Mihelyest megláttalak, leányka,
Én azonnal megszerettelek.
Látásodkor úgy jártam, mint a fa,
Amelyet a villám gyujta meg.

Fa valék én, egy kiszáradott fa,
Melynek lombja szertehulla rég.
Most örűlök rajta, hogy az voltam,
Mert a száraz fa legjobban ég.','Mihelyest megláttalak, leányka,
Én azonnal megszerettelek.
Látásodkor úgy jártam, mint a fa,
Amelyet a villám gyujta meg.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,336,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-103','petofi','Lyányka, mikor...','Lyányka, mikor úgy együtt sétáltunk,
Én nem szóltam és te hallgatál.
Hej! ha tudnám, be sokért nem adnám,
Hogy te ekkor min gondolkozál?

Én csak ilyenféléket gondoltam,
Hogy... izé... bizony már nem tudom:
Mit gondoltam? - csak hogy volt temérdek
Gyönyörűséges gondolatom.

Minden eszmém tündércsengetyű volt,
Mely bűbájosan csilingele,
Bájosan,... de némely''k olyan búsan,
Hogy szivem majd megrepedt bele!','Lyányka, mikor úgy együtt sétáltunk,
Én nem szóltam és te hallgatál.
Hej! ha tudnám, be sokért nem adnám,
Hogy te ekkor min gondolkozál?','Pest, 1845. augusztus',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,337,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-104','petofi','A világtól elvonulva...','A világtól elvonulva élni
Egy csöndes kis házfödél alatt,
Elvonulva, lyányka, véled élni...
Oh mily szép, mily édes gondolat!

Itt szeretném hagyni a világot,
Mely ugysem más, mint egy csatatér,
Harcolunk s mi harcaink jutalma?
Legfölebb is tán egy kis babér.

És ezért küszködjem én örökké?
S megvagdalni hagyjam lelkemet?
A babér csak elfödi sebünket,
Elfödi, de nem gyógyítja meg.

Tedd kezembe kezedet, leányka,
S ahová vezetsz: megyek veled;
Oh de messze menjünk, hogy ne lássam
Távolról se a csatahelyet.

Messze menjünk és sebes léptekkel,
Hogy minket ne érjen majd utol
Mult időm emléke, e madár, mely
Harcaimról oly búsan dalol.','A világtól elvonulva élni
Egy csöndes kis házfödél alatt,
Elvonulva, lyányka, véled élni...
Oh mily szép, mily édes gondolat!','Pest, 1845. augusztus',1845,'1845',array['Szerelem','Haza']::text[],'{}'::text[],false,338,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-105','petofi','Amióta szerelembe...','Amióta szerelembe estem,
Igazán, hogy féleszű vagyok.
Szemkötősdit játszanak fejemben
S falnak mennek a gondolatok.

Nem csoda, ha olyasmit teszek, mit
Józanan tőlem nem láttatok.
Amit szinte szégyenlek kivallni:
A tükörbe is pillantgatok.

Reggel sokszor jó estét kivánok,
És jó reggelt, hogyha este van.
Isten hozott! mondom a menőnek,
S annak, aki jő: élj boldogan!

Tollam gyakran a porzóba mártom,
A tintát meg porzónak veszem.
S mindez hagyján! de mikor szájamba
A szivar tüzes végét teszem...

Erre aztán elmondhatni ám, hogy
Valóságos szerelem sebe.
Te miattad kaptam, lyányka... illő
Volna, hogy csókod gyógyítsa be!','Amióta szerelembe estem,
Igazán, hogy féleszű vagyok.
Szemkötősdit játszanak fejemben
S falnak mennek a gondolatok.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,339,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-106','petofi','Sohasem volt az szerelmes...','Sohasem volt az szerelmes, aki
Mondja, hogy rabság a szerelem.
Szárnyat ád ő, és nem rabbilincset,
Szárnyat ád ő... azt adott nekem.

S a madárnak nincsen olyan szárnya,
Mint minőt a szerelem növeszt.
El sem kezdem oly parányisággal,
Mint a föld, hogy átröpüljem ezt.

Szállok én az angyalok kertébe,
Föl az égre, pillantás alatt,
S koszorúba fűzöm ott e kertnek
Lángrózsáit, a csillagokat.

Majd ez égi fény borít el, majd az
Alvilágnak éjszakája föd...
Szállok és egy pillanatban látok
Istent s mennyet, poklot s ördögöt.

Nincsen itt tér, nincsen itt időköz,
Hogyha szárnyam fölkerekedik;
A világnak megteremtésétől
Szállok a végső itéletig.

S így ha mennyet és poklot bejárok:
A pokolban ami gyötrelem
És a mennyben ami üdvesség van,
Egy percben mindazt átérezem.','Sohasem volt az szerelmes, aki
Mondja, hogy rabság a szerelem.
Szárnyat ád ő, és nem rabbilincset,
Szárnyat ád ő... azt adott nekem.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,340,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-107','petofi','A bokrétát, melyet...','A bokrétát, melyet nekem adtál,
Háromszin szalaggal kötted át.
Szereted te a hazának színeit,
Lyányka, mert szereted a hazát.

Adok én is három szint cserébe:
A zöld színnek vedd reményimet,
A fehérnek halovány orcámat,
A pirosnak vérző szívemet.','A bokrétát, melyet nekem adtál,
Háromszin szalaggal kötted át.
Szereted te a hazának színeit,
Lyányka, mert szereted a hazát.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,341,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('c10','petofi','Fa leszek, ha...','Fa leszek, ha fának vagy virága.
Ha harmat vagy: én virág leszek.
Harmat leszek, ha te napsugár vagy...
Csak, hogy lényink egyesüljenek.

Ha, leányka, te vagy a mennyország:
Akkor én csillagá változom.
Ha, leányka, te vagy a pokol: (hogy
Egyesüljünk) én elkárhozom.','Fa leszek, ha fának vagy virága.
Ha harmat vagy: én virág leszek.
Harmat leszek, ha te napsugár vagy...
Csak, hogy lényink egyesüljenek.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet']::text[],array['tavasz']::text[],false,342,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-109','petofi','Őszi reggel járok...','Őszi reggel járok a szabadban,
De hiába nézek szerteszét;
Sűrü ködnek fátyolában a táj,
A toronynak látni csak hegyét.

A természet elhagyott szentegyház;
Nincsen benne buzgó népe már:
A virágok... s hallgat orgonája,
Hallgat a sok énekesmadár.

A természet néma szentegyháza
Fölzajlik még egyszer az idén
- A tavasznak mintegy viszhangjául -
A szüretnek megjövetelén.

A szüret víg, kellemes mulatság.
Gyakran ekkép sóhajtott szivem:
Be szeretnék én is szüretelni,
Mért nincs nekem is szőlőhegyem?...

Most beérném egyetlen gerezddel,
Egy egész szőlőhegy nem epeszt;
Hej, beérném én veled, leányka,
Te legszebb, legédesebb gerezd!','Őszi reggel járok a szabadban,
De hiába nézek szerteszét;
Sűrü ködnek fátyolában a táj,
A toronynak látni csak hegyét.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Ünnep']::text[],array['osz']::text[],false,343,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-110','petofi','Háborúval álmodám...','Háborúval álmodám az éjjel,
Háborúba hítták a magyart;
Fölhivó jelül, mint hajdanában,
Országszerte járt a véres kard.

S fölriadt a véres kard láttára,
Akinek csak egy csepp vére volt.
A szabadság drága koszorúja,
Nem hitvány pénz volt a harci zsold.

Épen e nap volt menyegzőnk napja,
Az enyém, leányka, s a tiéd;
S én, hogy haljak a honért, elhagytam
Házasságunk első éjjelét.

Úgye, lyányka, a menyegző napján
Menni és meghalni, szörnyű vég?
És mégis, ha rákerülne a sor,
Ugy tennék, mint álmomban tevék.','Háborúval álmodám az éjjel,
Háborúba hítták a magyart;
Fölhivó jelül, mint hajdanában,
Országszerte járt a véres kard.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Haza']::text[],'{}'::text[],false,344,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-111','petofi','Életem most...','Életem most egyetlen kivánság:
Megnyerhetni, lyányka, szívedet!
Néha mégis csaknem azt ohajtom:
Vajha ne szeretnél engemet.

Azt hiszem, hogy sorsom a tiéddel
Összekötni vétek volna tán;
Az enyém oly boldogtalan, oly bús,
A tiéd oly boldog, oly vidám!

Berekesszem a szelíd galambot
Vérszomjas vadállatok közé?
Tengerekre, vészes tengerekre
A kicsiny sajkát vezessem-é?

Nem járnál-e ugy mellettem, lyányka,
Mint ott a galamb s a sajka jár?
Megbirnád-e a balsorsot? melyet
Én megbírok, mert megszoktam már...

Csak szeress te engemet, leányka,
Szenvedésim tudni sem fogod.
Nem borúl el soha én miattam,
Nem borúl el fényes homlokod.

Megkiméllek bánatomtól téged,
Mint a föld a napot, kedvesét.
Víg, derült ő, s ha lenyugszik a nap:
Akkor lesz csak szomorú, sötét.','Életem most egyetlen kivánság:
Megnyerhetni, lyányka, szívedet!
Néha mégis csaknem azt ohajtom:
Vajha ne szeretnél engemet.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,345,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-112','petofi','A letarlott...','A letarlott, megsárgult vidéken
Szomorúan űl az őszi köd...
Mult időmnek szomorú emléke
Őszi ködként ült szivem fölött.

Feljön a nap fényes arculatja
És eloszlik a szomoru köd...
Fényes arcod megláttam, leányka,
S világosság lett szívem fölött.

Oh, de, lyányka, ugy ne tégy, mint a nap,
Mely azért veré el a ködöt,
Csak azért, hogy tisztán lássék: milyen
Hervadás van a világ fölött.','A letarlott, megsárgult vidéken
Szomorúan űl az őszi köd...
Mult időmnek szomorú emléke
Őszi ködként ült szivem fölött.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet']::text[],array['osz']::text[],false,346,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-113','petofi','Ha az Isten...','Ha az isten ekkép szólna hozzám:
"Fiam, én neked megengedem,
Hogy ugy halj meg, mint magadnak tetszik."
Erre kérném akkor istenem:

Legyen ősz, de szép, szelíd, derült ősz,
Sárga lombon fényes napsugár;
Sárga lomb közt zengje végdalát egy
A tavasztól elmaradt madár.

S valamint az őszi természetre
A halál jön észrevétlenül:
Énreám is így jőjön... csak akkor
Vegyem észre, ha mellettem ül.

Ekkor, mint a lombon a madárka,
Zengjem én is el végdalomat
Bűvös hangon, mely le a sziveknek
Fenekére s föl az égbe hat.

És ha vége a varázséneknek:
Ajkaimat egy csók zárja be,
A te csókod, szőke szép leány, te
Földi lények legdicsőbbike! -

De ha ezt nem engedné az isten,
Kérném akkor, hogy tavasz legyen,
Harc tavasza, hol rózsák teremnek,
Véres rózsák, férfikebleken.

S lelkesítve zengjenek a harcok
Csalogányai, a trombiták,
Ott legyek, s az én szivemből szinte
Nőjön egy halálos vérvirág.

S ha ledőlök ekkor paripámról:
Ajkaimat egy csók zárja be,
A te csókod, te szép szabadság, te
Égi lények legdicsőbbike!','Ha az isten ekkép szólna hozzám:
"Fiam, én neked megengedem,
Hogy ugy halj meg, mint magadnak tetszik."
Erre kérném akkor istenem:','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Szerelem','Haza']::text[],array['tavasz','osz']::text[],false,347,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-114','petofi','Elnémult a fergeteg...','Elnémult a fergeteg süvöltő
Hárfájának zordon éneke.
Nyúgodt a táj, mint az arc, mely küzdött
A halállal s már kiszenvede.

Oly szelíd, szép őszi délután van!
Itt-ott látni csak kis felleget;
A viharból ugy maradt meg ez, mint
Bús időkből az emlékezet.

A faluknak bádogtornyait a
Nap sugári megaranyozák;
Délibábak távol tengerében
Mint hajók lebegnek a tanyák.

Áttekintek a nagy láthatáron,
Rónaság ez, völgy- és hegytelen.
Szívem is most ily végetlen róna...
Nincsen benne más, csak szerelem.

Szívem olyan tele szerelemmel,
Hogy terhétől csaknem elesik.
Ugy vagyok, mint a fa, melynek ága
Alig birja dús gyümölcseit.

Szívem így, megtelve szerelemmel,
Egy pohár, amely csordultig áll...
Drága bor!... s ha a lyány porba önti?
Kár lesz... inkább idd ki te, halál!','Elnémult a fergeteg süvöltő
Hárfájának zordon éneke.
Nyúgodt a táj, mint az arc, mely küzdött
A halállal s már kiszenvede.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,348,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-115','petofi','Arcképemmel...','Arcképemmel, lelkem arcképével
Ajándékozlak meg tégedet.
Nem bánom, ha senkinek sem tetszik,
Csak neked tessék, lyánykám, neked!

Lelkem egy könyv, amely mindig nyitva,
Olvashatja, ki mellette jár.
Olvassák is - a sok forgatásban
Össze is van az szaggatva már.

Lelkem gyűrü, egy acélgyürű; de
Láthatsz benne drágaköveket.
Legnagyobb, legszebb ezen kövek közt
Egy gyémánt, a tiszta becsület.

Lelkem oszlop, egy kősziklaoszlop,
Mely soha meg nem rendíttetett,
Nem reszket... csak egy, csak egy esetben:
Hogyha rászáll szép tekinteted.

Lelkem felhő, egy haragvó felhő,
Gyakran ontja a villámokat;
De, leányka, te ne félj! - a villám
Tölgyeket sujt, nem virágokat.

Lelkem Illés próféta, a mennybe
Száll a dicsőség lángszekerén...
Híj öledbe, lyányka, s lángszekérről
És mennyországról lemondok én!','Arcképemmel, lelkem arcképével
Ajándékozlak meg tégedet.
Nem bánom, ha senkinek sem tetszik,
Csak neked tessék, lyánykám, neked!','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,349,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-116','petofi','Avvagy én már soha...','Avvagy én már soha meg nem nyugszom?
Mindörökké tart e lelki harc?
Oh leányka, e véget nem érő
Kínozással, mondd, hogy mit akarsz?

Mert te kínzasz, mert te gyötresz engem,
Pedig én meg nem bántottalak;
Vagy talán az megbántás előtted,
Hogy szeretlek, hogy imádalak?

És ezért kell oly sokat szenvednem,
Oly sokat, amennyit csak lehet!
Szívemet megvesztegetted, lyányka,
Hogy örökké verjen engemet.

S ezelőtt még, ha reggeltül estig
Gyötörtettem is a kínpadon:
Az enyém volt a pihentető éj;
Most sem éjem többé, sem napom!

Mint galamb száll én felém az álom,
De reám nem édesgethetem:
A galamb félénk madár... tovább száll...
Elriasztja dobogó szivem.

Kérlek, lyányka, parancsolj szivemnek,
Csendesítsd le e vad pártütőt,
Nehogy egyszer a kétségb''esésnek
Óráján keresztüllőjem őt!','Avvagy én már soha meg nem nyugszom?
Mindörökké tart e lelki harc?
Oh leányka, e véget nem érő
Kínozással, mondd, hogy mit akarsz?','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,350,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184504-117','petofi','Azt hivém, hogy...','Azt hivém, hogy csak az emberek közt
Van irigység és kajánkodás.
Csalatkoztam! mert amilyen a föld,
Ott fenn az ég egy cseppel se'' más.

Földön, égen nincs valódi béke;
Örökös harc, örökös zavar.
Mint a földön, épenúgy az égen
Minden csak uralkodni akar.

A nap és éj háborút viselnek,
Hol az egyik, hol a másik nyér.
Mi a hajnal és az alkony?... a nap
S éj közötti harcban elfolyt vér.

És mi a hold? egy zsarnok király ő,
És jobbágyai a csillagok.
És a jobbágy, ki nagyon tündöklik?
Jaj neki, mert számüzetni fog.

Hány jobbágyát számüzé e zsarnok!
Minden éjjel hull alá nehány...
Tán te is így fényedért az égből
Száműzött csillag vagy, szép leány?','Azt hivém, hogy csak az emberek közt
Van irigység és kajánkodás.
Csalatkoztam! mert amilyen a föld,
Ott fenn az ég egy cseppel se'' más.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Haza']::text[],'{}'::text[],false,351,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-118','petofi','Messze estem...','Messze estem, oh lyánykám, beszédes
Szemeidnek szép sugáritól...
(Szemeidből jóság és vidámság,
E kedves két égi gyermek szól.)

Messze estem tőled, oh, te szép lyány.
Te aranyba foglalt drágakő!
De a nap, hol majd elédbe állok,
Ez a nagy nap nemsokára jő.

Nagy lesz e nap, sorsomat határzó,
Mint Waterloo Napoleonét.
Még király vagyok... kevélyen hordom
Koronámat, a fényes reményt.

Oh, de mi lesz éltem, ha fejemről
Porba hull e drága korona?
Mi lesz akkor éltem?... fájdalomnak
Oceánján a Szentilona.','Messze estem, oh lyánykám, beszédes
Szemeidnek szép sugáritól...
(Szemeidből jóság és vidámság,
E kedves két égi gyermek szól.)','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet']::text[],'{}'::text[],false,352,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-119','petofi','Milyen fucsa álmam...','Milyen furcsa álmam volt az éjjel!
Lyányka, te megszúrtad szívemet,
És belőle minden vér kifolyt; de
Minden csepp vérből egy rózsa lett.

Mit jelenthet ez az álom?... semmit,
Csak azt, hogy ilyen a szerelem;
A szegény szivet halálra gyötri,
S olyan édes ez a gyötrelem!','Milyen furcsa álmam volt az éjjel!
Lyányka, te megszúrtad szívemet,
És belőle minden vér kifolyt; de
Minden csepp vérből egy rózsa lett.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,353,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-120','petofi','Félre mostan...','Félre mostan, félre a fejemről,
Bú, te fekete, nehéz sisak!...
Jer, jókedv, te könnyü tarka csákó,
Melyen pajkos tollak inganak.

Félre, bú, te lándzsa, mely szögezve
Vagy tulajdon gazdád keblinek...
Jer, jókedv, te szép virágbokréta,
Mit keblemre bátran tűzhetek.

Félre, bú, te alvilági kínpad,
Amelyen a szív mártírkodik...
Jer, jókedv, te hattyutollas párna,
Melyen a szív mennyről álmodik.

Jöszte, jókedv! jöszte, víg barátom,
Csapjunk egy hatalmas ünnepet,
Oly hatalmast, aminő közöttünk
Még soha nem ünnepeltetett.

Jöszte, jókedv! fényes szivárványod
Vond keresztül a nagy ég-iven;
Jöszte, kezdd el szép szellemzenédet,
Hadd táncoljon lelkem és szivem!

Kérdezed, jókedv barátom, hogy mért,
Mért tartunk ilyen nagy ünnepet?
Csak azért, mert megtudom: a lyányka
Szeret-e hát avvagy nem szeret?

Hogyha visszatérünk a leánytól
És szerelmet tőle nem hozunk:
Messze utra küldelek, barátom,
S többé tán nem is találkozunk.

Megvallom, hogy eddig én reszkettem
Az időtől, mely most jőni fog,
De kihamvadt bátorságom lángja
Most, hogy épen kell, megint lobog.

Gyalázat a gyáva katonára,
Ki a síkra búsfélénken áll -
Vigalomra hát - vigan rohanjunk
A csatába - élet vagy halál - - !','Félre mostan, félre a fejemről,
Bú, te fekete, nehéz sisak!...
Jer, jókedv, te könnyü tarka csákó,
Melyen pajkos tollak inganak.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Természet','Ünnep']::text[],'{}'::text[],false,354,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-121','petofi','Oh mi szép...','Oh mi szép a vándorélet... oh az
Irigylendő vándormadarak!
Nem tudják ők, nem tudják: mi a tél,
Egy tavaszból másba szállanak.

Vándorolni... vándorolni, mint a
Fecske, mint a gólya, szabadon:
Add e sorsot énnekem, teremtőm!
Hajdan ez volt a kivánatom.

Oh mi szép a házi élet... oh az
Irigylendő házi madarak!
Mit törődnek ők téllel, tavasszal?
Fészkeikben olyan boldogak.

Házasodni, házasodni... élni,
Halni a szerelmi láncokon:
Add e sorsot énnekem, teremtőm!
Mostan ez az én kivánatom!','Oh mi szép a vándorélet... oh az
Irigylendő vándormadarak!
Nem tudják ők, nem tudják: mi a tél,
Egy tavaszból másba szállanak.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,355,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-122','petofi','Falun','Király vagyok most minden alkonyon:
A nap pirosló fényt lövel reám,
A nap pirosló búcsusúgara
Biborra festi egyszerű ruhám.

Gyönyörrel járom estenként a tájt,
Kilépvén a kis házfödél alól;
Porfellegekben a nagy ég alatt
A hazatérő nyáj kolompja szól.

Elandalodva hallom e zenét,
Elandalodva szemlélek körűl;
És messze látok, mert mindenfelé
Megmérhetetlen rónaság terűl.

A rónaságnak messze tengerén
Imitt-amott áll egy fa, mint sziget,
S hová imát küld a mohamedán:
Kelet felé ez hosszu árnyat vet.

Miként csatában a sebzett vitéz,
Elvérzik a nap végre, s elesik;
S mint a dicsőség a vitéz-halált,
A napot csillagok s hold követik.

Körűlem éj van, fényes éjszaka;
A csillagfényes éjben méla csend,
Oly csend, hogy szinte vélem hallani,
Mit a holdban szent Dávid lantja zeng.

A szomszéd tóból a vadlúdakat
Látom csapatban messzeszállani;
Szivemből is föl- és elszállanak
A nagyravágyás, hír vad álmai.

Feledni kezdem Pestet és zaját,
S jövendőm minden büszke terveit;
Jobb lenne élnem, így gondolkodom,
Jobb lenne élnem elfeledve itt.

A fölmagasztalt nagy nevek között
Ne hangoztassa senki nevemet,
Csak szőlőm és szántóföldem legyen,
Termők piros bort s fehér kenyeret.

S midőn szőlőmbül s szántóföldemről
Házamba térek este: hozza be
Majd a piros bort s fehér kenyeret
Piros menyecskének fehér keze.

S ha a késő halálnak ujjai
A férj és nő szemét majd befogák:
Tegyék egy sírba a két aggastyánt
Nem tettetésből síró unokák.','Király vagyok most minden alkonyon:
A nap pirosló fényt lövel reám,
A nap pirosló búcsusúgara
Biborra festi egyszerű ruhám.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet','Elmúlás']::text[],'{}'::text[],false,356,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-123','petofi','A jó öreg kocsmáros','Itt, ahonnan messze kell utazni, míg az
Ember hegyet láthat, itt a szép alföldön,
Itten élek én most megelégedéssel,
Mert időm vidáman, boldogságban töltöm.
Falu kocsmájában van az én lakásom;
Csendes kocsma ez, csak néha zajlik éjjel.
Egy jó öregember benne a kocsmáros...
Áldja meg az isten mind a két kezével!

Van szállásom itten s ennem-innom ingyen,
Sohasem volt ennél jobb gondviselésem.
Az ebédre nem kell senkit is megvárnom,
És mindnyájan várnak énrám, hogyha késem.
Csak egyet sajnálok: az öreg kocsmáros
Összekoccan néha jó feleségével;
No de amint összekoccan, meg is békül...
Áldja meg az isten mind a két kezével!

Elbeszélünk néha a letűnt időkről.
Hej, régibb idői boldogak valának!
Háza, kertje, földje, pénze, mindene volt,
Alig tudta számát ökrének, lovának.
Pénzét a hitetlen emberek csalása,
Házát a Dunának habjai vitték el;
Igy szegényült el a jó öreg kocsmáros...
Áldja meg az isten mind a két kezével!

Alkonyúló félben van már élte napja,
S ilyenkor az ember nyúgodalmat óhajt,
S őreá, szegényre, a szerencsétlenség,
Őreá mostan mért legtöbb gondot és bajt.
Fáradoz napestig, vasárnapja sincsen,
Mindig későn fekszik, mindig idején kel;
Mint sajnálom én e jó öreg kocsmárost...
Áldja meg az isten mind a két kezével!

Biztatom, hogy majd még jóra fordul sorsa;
Ő fejét csóválja, nem hisz a szavamnak.
"Úgy van, úgy" szól később, "jóra fordul sorsom,
Mert hisz lábaim már a sír szélén vannak."
Én elszomorodva borulok nyakába,
S megfürösztöm arcát szemeim könnyével,
Mert az én atyám e jó öreg kocsmáros...
Áldja meg az isten mind a két kezével!','Itt, ahonnan messze kell utazni, míg az
Ember hegyet láthat, itt a szép alföldön,
Itten élek én most megelégedéssel,
Mert időm vidáman, boldogságban töltöm.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,357,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-124','petofi','Imádságom','Elkárhozástól félt szegény anyám,
S talán féltése nem alaptalan.
Tart tőle - s ebben igazsága van -
Hogy már régóta nem imádkozám.
Imádkozom hát; íme két kezem
Szent áhitattal összekulcsolom.
Hallgass meg engem, égi hatalom,
Hallgass meg engem, édes istenem!

Adj énnekem... hó, első a haza.
Hatalmas isten, népem istene!...
De kérni vajjon mit is kellene
Hazámért, melynek annyi a baja?
Ezért csak egy, csak egy a kérelem:
Mely így, mint van, már nem sok évet lát,
Teremtsd egészen ujjá e hazát.
Hallgass meg engem, édes istenem!

És magamért? mit kérjek magamért?
Adj hát nekem szépséges szeretőt,
S amelyen majd meglátogassam őt,
Gyors paripát; aztán sok, sok babért...
Nem hogy fejemet ékesítse, nem,
De hogy, ha nem lesz szénám, abrakom,
Csikóm legyen mivel jól tartanom...
Hallgass meg engem, édes istenem!','Elkárhozástól félt szegény anyám,
S talán féltése nem alaptalan.
Tart tőle - s ebben igazsága van -
Hogy már régóta nem imádkozám.','Szalkszentmárton, 1845. aug. 20. - szept. 8. között',1845,'1845',array['Szerelem','Haza']::text[],'{}'::text[],false,358,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-125','petofi','Piroslik már a fákon a levél...','Piroslik már a fákon a levél,
Süvölt köztök, süvölt az őszi szél,
Homályos a nap, a mező deres;
Pásztor, betyár meleg tanyát keres.

Meleg tanyát a pásztor csak talál,
Vár ott reá kulacs bor, tele tál.
Ha kifogy a kulacs bor s tele tál,
Lágy párnán felesége vele hál.

Betyár embernek jó tanyája nincs,
Minden felől csörög rá rabbilincs.
Száraz bokorban huzza meg magát,
Átkozza a hűs őszi éjszakát.','Piroslik már a fákon a levél,
Süvölt köztök, süvölt az őszi szél,
Homályos a nap, a mező deres;
Pásztor, betyár meleg tanyát keres.','Dömsöd, 1845. szeptember',1845,'1845',array['Természet']::text[],'{}'::text[],false,359,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-126','petofi','Felhő és csillag','Mikor isten a férfit teremté,
Homlokára szállt sötét ború,
Nem tudom mért?... csakhogy e borúból
Lett a felhő s égiháború.

Mikor isten a hölgyet teremté,
Örömében sírva fakadott.
Most is látni ez örömkönnyeknek
Cseppjeit, a sok szép csillagot.','Mikor isten a férfit teremté,
Homlokára szállt sötét ború,
Nem tudom mért?... csakhogy e borúból
Lett a felhő s égiháború.','Cinkota, 1845. szeptember',1845,'1845',array['Természet']::text[],'{}'::text[],false,360,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-127','petofi','Császár Ferenc őnagyságához','Nagyságos úr! ismer engem,
Tudja azt a rosz szokásom,
Hogy az igazságot isten-
S embernek szemébe vágom.

Nagyságos úr! ön nem isten,
Csak ember, de az sem nagy ám!
S így az igazságot önre
Ugyan mért ki ne mondanám?

Nagyságos úr! kimondom azt,
Mert ön énnekem nem árthat;
Cenzurázni nem akarok,
És így nem rejiciálhat.

Nagyságos úr! meglehet, hogy
Önnek számtalan bűne van;
Mind leimádkozhatja... de
Van egy megbocsáthatatlan.

Nagyságos úr! tudja mi ez?
Nem, hogy engemet kritizál,
A világért sem az!... hanem
Az, hogy ön verseket csinál.

Nagyságos úr! az isten szent
Szerelmére, mit gondol ön?
Azt hiszi: a költészet a
Nagyságos címmel együtt jön?

Nagyságos úr! a költőnek
Szükséges, hogy lelke légyen;
Hanem önnek lélek helyett
Spongyia van a szivében.

Nagyságos úr! a spongyia
Lángot nem vet, szikrát sem ád,
Akármikép ütik, verik...
Minek üti-veri tehát?

Nagyságos úr! valahányszor
Az ön verseit olvasám,
Tudja: mi jutott eszembe?
Az, hogy: asinus ad lyram.

Drága, tisztelt nagyságos úr!
Az ön atyja csizmadia;
Önnek is jobb lenne, ezt a
Mesterséget folytatnia.','Nagyságos úr! ismer engem,
Tudja azt a rosz szokásom,
Hogy az igazságot isten-
S embernek szemébe vágom.','Pest, 1845. szeptember 10. után',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,361,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-128','petofi','Az utósó ember','Mi az fölöttem? ég vagy sírbolt?
Igen, sírbolt, amelyben a föld,
Ez óriás koporsó fekszik.
És ott fejem fölött az a fény
A nap? vagy a sírbolti lámpa?
Igen, sírbolti lámpa, melynek
Bágyadtan pislogó sugára
Sötétségét a síri éjnek
Halvány piros-sárgára festi.
S mily hallgatás!... de, hah, mi zendül
A némaságnak közepette?
Madárszó vagy leánydal? Oh nem!
A férgek rágják a koporsó
Behunyt szemű, hideg lakóit.
Igen, behunyvák a szemek mind,
Melyekben egykor szerelemnek
S gyűlölségnek szikrája lángolt,
S amelyekből oly undorítón
Nézett ki, mint a kéjleányok
A bordélyházak ablakából,
A gőg, irígység, elbizottság,
A megvetés, alázatosság.
Behunyvák a szemek, s hideg már
A szív, e kis pokol, amely száz
Meg száz ördögnek volt tanyája,
Hol a bünök máglyája égett
Kihamvadatlan lángolással.
Hanem már mindeneknek vége.
Alszik már a becsűletorzás,
Barát- s honárulás, s egyéb szörny,
S amely őket nyomban követte,
A lelkiösmeret marása...
De ez nagyon régen halt már meg,
Az újabb kornak nemzedéke
Ismerte ezt csupán hiréből.-
Mindennek vége. Minden alszik.
Becsukva a szem. Hűlve a szív.
Csak én magam vagyok még élő
A sírbolt roppant üregében,
S tünődöm, egy vendégre várván,
A késedelmező halálra.
Halál, mért nem jösz? félsz talán, hogy
Megbirkozom veled s legyőzlek?
Ne félj, nem az vagyok, ki voltam,
Ki egykor vakmerő kebellel
Dacoltam sorssal és világgal.
Bátran jöhetsz. Meg nem támadlak.
Hagyom magam. Erőtelen hang
Leszek. Te szélvész légy. Sodorj el.','Mi az fölöttem? ég vagy sírbolt?
Igen, sírbolt, amelyben a föld,
Ez óriás koporsó fekszik.
És ott fejem fölött az a fény','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet','Elmúlás','Szerelem']::text[],'{}'::text[],false,362,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-129','petofi','Három szív története','1

Volt egy lovag, kinek nem volt hazája,
Mert rajtütének ellenséges népek,
És pusztulás lett, mit hozának rája
Komor fényében a csaták tüzének.
Komor fényében a csaták tüzének
Piroslott a lovag hős arca szinte
S piroslott vére, melyet bőven önte
Megmentésére a hon életének.
De hasztalan folyt a lovagnak vére;
Ő megmaradt és honja véget ére.
S a hontalan lett fának eltört ága,
Mit a fáról a fergeteg törött le,
S mit ez most kerget a széles világba.
Midőn a felhő ott szállott fölötte,
Ahol volt a ledöntött hon határa,
Megállott és letérdepelt hantjára,
Hogy könnyeit végső cseppig kisírja
A földre, mely holt nemzetének sírja;
Mert könnye volt egyetlen kincse, melyet
Elvesztett mindenéből még megtarta:
S ezt tékozolni másra nem akarta. -
Megindult és ment tompa búja mellett,
Mely árny képében őt folyvást kisérte.
Midőn kifáradt már a bujdosásban:
Csöndes vidékbe megpihenni tére
Egy idegen nép távol országában.
És gondolá azt is, hogy őt halála,
Ha egy helyen lesz, hamarabb találja;
S ha ráhull a halál fehér virága,
Beteljesűlve minden kívánsága.
Ezt várta ő a csendes zárt vidéken,
Hová fáradtan megpihenni tére,
S hol élt egy lyányka olyan ifjuszépen,
Hogy a vidéknek vált bámult diszére.
De ő a lyányka szépségét nem látta,
Semmit sem látott, csak romját honának;
Nem látta, hogy rá gyakran szállt a lyányka
Tekintetének csillagos világa,
S tekintetei mi lángolók valának!
Igy a leányka napjai folyának,
S arcára halvány liljomot föstének
Gyötrelmei a szólni nem merésnek;
Mert mit mondhatna a fényes lovagnak,
Mit mondhat ő, ki, bár eléggé gazdag,
De pórszülőknek egyszerű magzatja? -
És a vidéket még egy ifju lakja;
Szegény fiú, a legszegényebb szolga,
Tengődve éli nyomorú világát,
Kit tán megölne sok fárasztó dolga,
Ha nem láthatná néha a leánykát;
A titkon bámult lyányka láthatása
Fogyó erője meghozó varázsa.
Fél rágondolni, hogy kérjen szerelmet
A pór, de gazdag szülők gyermekétől,
Ő, akinek ha jut száraz kenyérből
Egy-két nagyobb falat, sorsán örülhet.
S ő mégis boldog, és azzal beéri,
Hogy a leánykát messziről kiséri.

2

És a lovagnak kondult a nagy óra,
Mely e világból őt egy másba vitte,
Ahol bitor kény mennykövit nem szórja
Az ártatlanság népének fölötte.
Letették őt az anyaföld ölébe;
Követ nem tettek a halom fölébe,
Mely pajzsa lett az élet búja ellen...
Miért is volna kő? a lyányka szíve,
Halála által kő lett, érzéketlen;
S ha nincsen érzés a szív birtokában,
Az ember mit keressen a világban?
Nem volt a lyányka sem sokáig földi.
Lefekvék, honnan senki fel nem költi.
És a szegény, az árva, árva szolga,
Tüntén egyetlen gyönyörűségének,
Az élet terhét hogy viselte volna?
Végét vetette terhes életének.

3

Az éjszakának sírnyitó felében
Fölkél a szolga, és a helyre mégyen,
Hová temették a kedves leánykát;
Akarja látni élte szép bálványát.
De a leánnyal nincs találkozása,
Mert a leány a sírból szinte eljár,
Hogy a lovagnak szellemét meglássa,
S ott vár, ott vár, de szinte hasztalan vár;
Mert a lovag száll messze, messze tájra,
Elszáll megnézni: rab-e még hazája?','1
Volt egy lovag, kinek nem volt hazája,
Mert rajtütének ellenséges népek,
És pusztulás lett, mit hozának rája','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Szerelem','Haza','Természet']::text[],'{}'::text[],false,363,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-130','petofi','Ismerjetek meg!','Ismerjetek meg végre: ki vagyok?
Álarc alatt volt mostanáig képem.
De már meguntam én álarcomat,
És azt most ünnepélyesen letépem!

Olvastátok vidám dalaimat?
Azt gondoljátok, hogy lelkembül írom?
Oh, dalaimban a kedv, nevetés,
Csak olyan ez, mint a virág a síron.

Kivűl a síron nyílik a virág,
S belűl a sírban féreg és halott van;
Igy írtam én enyelgő dalokat,
Mig lelkem haldokolt a fájdalomban.

De többé nem leszek komédiás,
Ki víg pofákat vág a közönségnek,
És odabenn a színfalak között
Arcán kínszenvedés könyűi égnek! -

Oh nem, ez mégsem szép határozat!...
Muljék oly gyorsan, amily gyorsan támadt.
Szenvedjen bár szivem: a víg dalok
Ne szűnjenek meg... hátha általok
Kissé vidítom szomorú hazámat.','Ismerjetek meg végre: ki vagyok?
Álarc alatt volt mostanáig képem.
De már meguntam én álarcomat,
És azt most ünnepélyesen letépem!','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,364,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-131','petofi','A hűtelen barátokhoz','Derék fiúk, mint hagyogatnak el!...
Eredjetek csak isten hírivel;
Hagyjátok itt a fát, ti levelek,
A fát, e szívet, melyen függtetek.
Az őszi szél, mely titeket lefú,
Majd elmulik, nem lesz örökkorú;
S ha eljövend ismét a kikelet,
Fog kapni a fa új leveleket.
De tudjátok: többé ki nem virul
Az a levél, mely fájáról lehull.','Derék fiúk, mint hagyogatnak el!...
Eredjetek csak isten hírivel;
Hagyjátok itt a fát, ti levelek,
A fát, e szívet, melyen függtetek.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,365,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-132','petofi','Virágoskert a költő szíve...','Virágoskert a költő szíve,
De másnak termi a virágokat;
Míg ezeket szétosztogatja,
Önnön magának csak tövis marad.

És pillangó a költő lelke;
Szegény pillangó! neki megesett:
Addig bolyong a puszta kertben,
Míg összetépik őt a tövisek.

S a puszta kert s tépett pillangó
Eszébe sem jut senkinek talán,
Midőn élvezettel mereng a
Szegény költő mártirkoszoruján.','Virágoskert a költő szíve,
De másnak termi a virágokat;
Míg ezeket szétosztogatja,
Önnön magának csak tövis marad.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,366,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-133','petofi','Ifjuság','Mondják hidegnyugalmasan
Az öregek:
Szilaj, bolond fiú vagyok,
Csendesb legyek.
Vénség az életnek viszhangja csak,
E tompa hangok meg nem bántanak.

Szilaj vagyok, igaz; s bolond?
Az is lehet.
Az észt tanácsra nem hivom,
Csak a szivet.
No de fejemnek is hasznát veszem:
Reá bokrétás kalpagom teszem.

S a szív nem rosz tanácsadó,
Higyétek el.
Az észnél gyakran messzebb lát
Sejtelmivel.
Az ifju szíve lánglobogva ég;
Világít ez, midőn sötét az ég.

S szolgál a szív nemcsak vezér-
Szövétnekül.
Balsors telében életünk
Gyakorta hűl,
S az ész miatt akár megfagyhatnánk,
De szivünkben fölmelegít a láng.

És ne higyétek, csendes öregek,
Hogy tán megárt,
Ha túllobogja is a fiatal
Tüz a határt;
Föl szoktak gyujtani egész mezőt,
S lesz égés által ez gyümölcsözőbb.','Mondják hidegnyugalmasan
Az öregek:
Szilaj, bolond fiú vagyok,
Csendesb legyek.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,367,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-134','petofi','Búm és örömem','Nincsen oly bú,
Mint az én búm.
Oh ha én busúlok!
Keblem egy oroszlánbarlang,
S szívem benne bárány;
Szaggatják az éhes oroszlánok
Fogaikkal, körmeikkel.
Vérét isszák,
Csontját rágják
És velőjét szíják
E szegény báránynak az
Éhes oroszlánok. - -
Olyan öröm sincs,
Milyen az én örömem.
Oh, mikor én örülök!
Keblem egy édeni kert
S rózsa e kertbe'' szivem.
Napsugarakkal,
Tarka lepékkel
Játszik e rózsa,
S zeng körülötte
A csalogány.
És jön egy angyal,
És leszakítja e rózsát,
S illeti csókkal,
S keblire tűzi,
S véle az égbe röpűl!','Nincsen oly bú,
Mint az én búm.
Oh ha én busúlok!
Keblem egy oroszlánbarlang,','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,368,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-135','petofi','Visegrád táján','Ki mondja meg?... Visegrád táján
A bágyadt alkony
Nem Zách Klárának megtört szelleme?

Ki mondja meg?... Visegrád táján
A vad, sötét éj
Nem Zách Bódognak bosszus szelleme?','Ki mondja meg?... Visegrád táján
A bágyadt alkony
Nem Zách Klárának megtört szelleme?
Ki mondja meg?... Visegrád táján','Pest, 1845. szeptember 10-24. között',1845,'1845','{}'::text[],'{}'::text[],false,369,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-136','petofi','Sorshúzás előtt','Kétszázezer forint! reá
Gondolni is alig merek.
Nagyúr leszek, mennykő nagy úr,
Föltéve persze: ha nyerek.

Vajon hová teszem e pénzt?
Mindenh''á, csak ládámba nem!
Meg nem penészedik az én
Ládámban, hiszem istenem.

Amint nyerek: elnyargalok
Tóth Gáspárhoz nagy hirtelen,
És e jó úrnál eddigi
Kontóm szépen lekvittelem;

Aztán (most már készpénzemért!)
Jó téli öltönyt varratok;
Mert közel a tél, s mostani
Ruhámban meg is fagyhatok.

Mily jól esik majd: ha fogat
Vicsorgat énrám a hideg,
Hahá! mily jólesik: fügét
Mutatni őkegyelminek.

Ugy ám, de hátha nem nyerünk?...
Ha nem nyerünk: isten veled,
Jó téli öltöny! - de sebaj,
Megszoktam már a hideget.','Kétszázezer forint! reá
Gondolni is alig merek.
Nagyúr leszek, mennykő nagy úr,
Föltéve persze: ha nyerek.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet']::text[],array['tel']::text[],false,370,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184505-137','petofi','M. e kisasszony emlékkönyvébe','Legboldogabb perc életünkben az,
(Még nem próbáltam, ámde ugy hiszem)
Ha kedvesünkkel oltárhoz megyünk.
S neked maholnap e sorsod leszen.
Megállítnám, ha volnék Józsue,
Megállítnám itt a napot, időt,
Hogy mindörökké oly boldog lehess,
Minő ekkor lész az oltár előtt.','Legboldogabb perc életünkben az,
(Még nem próbáltam, ámde ugy hiszem)
Ha kedvesünkkel oltárhoz megyünk.
S neked maholnap e sorsod leszen.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,371,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-138','petofi','Én és a nap','Bámulja sok oly epedőleg a holdat,
Ezt a megtestesült sohajt.
Miattam akár kimaradjon örökre,
Nem csüggök én merengve rajt.

Megtestesülése te érzeteimnek,
Magas, fényes, hő napsugár!
Te vagy szivem öröme, gyönyörüsége,
Érted szemem, lelkem sovár.

Egymás szeretői vagyunk mi a nappal:
Mi hűséges két szerető!
Ki mondja meg: én melegűlök-e tőle?
Vagy szívemtől melegszik ő?

És hogyha siromba leűzni fog a sors,
Csak azt az egyet fájlalom,
Hogy majd szeretőmet a földnek alatta,
A szép napot, nem láthatom.

De szabad a holtnak egy óra naponként,
S én arra kérem istenem:
Éjfél idején legyen zárva koporsóm,
S nyíljon meg az délben nekem!','Bámulja sok oly epedőleg a holdat,
Ezt a megtestesült sohajt.
Miattam akár kimaradjon örökre,
Nem csüggök én merengve rajt.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,372,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-139','petofi','A zsiványság vége','Hej zsiványság, derék szép zsiványság!
A te véged hatalmas mulatság;
Lesz belőled, ugy hord a szerencse,
Száraz fának száradó gyümölcse.

Hogy kimulj, szikrát sem fáradsz magad:
Kitekeri a hóhér a nyakad.
Hogy pedig ne láthasd szégyenedet,
Kivájják a varjak szemeidet.

És mig tested a táncot ugy járja,
Amint szól a szelek muzsikája:
Mélységében a sátán házának
Lelkeddel az ördögök labdáznak.','Hej zsiványság, derék szép zsiványság!
A te véged hatalmas mulatság;
Lesz belőled, ugy hord a szerencse,
Száraz fának száradó gyümölcse.','Pest, 1845. szeptember 10-24. között',1845,'1845','{}'::text[],'{}'::text[],false,373,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-140','petofi','Egy fiatal íróhoz','Üdvezellek, ifjú pályatárs,
Pályatársam s szeretett barátom!
Egykor én terólad jósolék,
S jóslatom most teljesedni látom.

Láttam egykor egy kis felleget,
S megmondtam, hogy ebből fergeteg lesz.
E kicsiny felhőcske te valál,
És most villámterhesen közelgesz.

Jőj és ontsd lelked villámait,
S lángjaikkal gyujtsd föl a világot;
Rendűljön meg a föld, amidőn
Mennydörgő jelszódat elkiáltod.

Hogyha majd villámlasz s mennydörögsz,
Jőnek ellened zudúló hangok;
Mert ha nagy az égiháború,
Félre szokták verni a harangot.

De azért dúl a vihar tovább
Minden félrevert harang dacára.
Igy barátom, te se hajts ama
Jajveszéklő emberek szavára.

Ekkép kellett volna nekem is
Tenni sokszor ostromolt pályámon.
Én e tehetetlen hangokat
Figyelemre méltatám. Sajnálom.

Eh, megtörtént, mit sajnálkozom?
Hadd szorítsam jobbod, ifju bajnok,
Én, ki ilyen rokonszellemű
Pályatárs után már rég sohajtok.

Fölléptél. Ez engem megujit,
Hogy a sorompók közt ketten állunk.
Most, barátom, küzdjünk, hadd legyen
Győzedelmünk vagy vitéz halálunk!','Üdvezellek, ifjú pályatárs,
Pályatársam s szeretett barátom!
Egykor én terólad jósolék,
S jóslatom most teljesedni látom.','Pest, 1845. szeptember 10-24. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,374,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-141','petofi','Alku','Juhászlegény, szegény juhászlegény!
Tele pénzzel ez a kövér erszény;
Megveszem a szegénységet tőled,
De rá''dásul add a szeretődet.

"Ha ez a pénz volna csak foglaló,
S még százennyi lenne borravaló,
S id''adnák a világot rá''dásnak,
Szeretőmet mégsem adnám másnak!"','Juhászlegény, szegény juhászlegény!
Tele pénzzel ez a kövér erszény;
Megveszem a szegénységet tőled,
De rá''dásul add a szeretődet.','Szalkszentmárton, 1845. szeptember 25-26.',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,375,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-142','petofi','A szeretőm nyalka gyerek...','A szeretőm nyalka gyerek,
Alája termett a nyereg.
Ha viszi a paripája,
Gyönyörűség nézni rája.

Gyakran látogat meg engem,
Most is amott jön a lelkem;
Ugy megvágtat paripája,
A négy körmét majd elhányja.

Öregbiró lyánya, szivem,
Mit kukucskálsz olyan igen?
Mit lesed a szeretőmet?
Ugysem szeret ám ő téged. -

Szállj le, kincsem, a nyeregből,
Vedd ki lábad a kengyelből,
Ereszd meg a terhelődet,
Öleld meg a szeretődet.

Istenem, be ver a szived,
Mert itt van az enyim mellett.
Szived az én kincsesládám,
Három faluért sem adnám.

Mulattató, nevettető,
Ha összejön két szerető;
Elbeszélnek végtelenül,
Magok sem tudják, hogy mirül.

Jaj de mi zaj van odakint?
Hát biz ott a lovad nyerit.
Hogy elfeledkeztünk róla!
Isten bűnünkűl ne rója.

Jól tartottad a lovadat,
De már föl is kantároztad.
Még egy csókot, itt az orcám,
Isten hozzád, kedves rózsám!

Kedves rózsám, isten hozzád.
Adjon isten arany zablát,
Arany zablát a lovadnak,
Aranyos kedvet magadnak!','A szeretőm nyalka gyerek,
Alája termett a nyereg.
Ha viszi a paripája,
Gyönyörűség nézni rája.','Dunaföldvár, 1845. szeptember 25-26.',1845,'1845',array['Szerelem','Gyermekkor']::text[],'{}'::text[],false,376,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-143','petofi','S. K. emlékkönyvébe','Vén épület már a világ,
Le, alacsonyra sűlyedett.
Ha egyenest jársz: beütöd
A gerendában fejedet.
Hajolj meg, ha a fejtörő
Gerenda ellenedre van...
Én inkább betöröm fejem,
Semhogy meghajtsam derekam!','Vén épület már a világ,
Le, alacsonyra sűlyedett.
Ha egyenest jársz: beütöd
A gerendában fejedet.','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845','{}'::text[],'{}'::text[],false,377,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-144','petofi','S. Zs. kisasszony emlékkönyvébe','Méhek s virágok kertednek lakói.
Méhes, virágos kert legyen szived;
Ha nyílik benne szerelem virága,
A barátságnak méhét is bevedd;
Mert jól tudod: szép a virág; azonban
Tavasszal él csak, és ez oly rövid,
Míg a szerény méh munkálódásából
Megédesíted téli napjaid.
Ha e tanácsom nem lesz sikeretlen:
Engedd, hogy én is méh legyek szivedben.','Méhek s virágok kertednek lakói.
Méhes, virágos kert legyen szived;
Ha nyílik benne szerelem virága,
A barátságnak méhét is bevedd;','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,378,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-145','petofi','A négyökrös szekér','Nem Pesten történt, amit hallotok.
Ott ily regényes dolgok nem történnek.
A társaságnak úri tagjai
Szekérre ültek és azon menének.
Szekéren mentek, de ökörszekéren.
Két pár ökör tevé a fogatot.
Az országúton végig a szekérrel
A négy ökör lassacskán ballagott.

Világos éj volt. A hold fenn vala;
Halványan járt a megszakadt felhőkben,
Miként a bús hölgy, aki férjinek
Sírhalmát keresi a temetőben.
Kalmár szellő járt a szomszéd mezőkön.
S vett a füvektől édes illatot.
Az országúton végig a szekérrel
A négy ökör lassacskán ballagott.

A társaságban én is ott valék,
S valék szomszédja épen Erzsikének,
A társaságnak többi tagjai
Beszélgetének s énekelgetének.
Én ábrándoztam s szóltam Erzsikéhez:
"Ne válasszunk magunknak csillagot?"
Az országúton végig a szekérrel
A négy ökör lassacskán ballagott.

"Ne válasszunk magunknak csillagot?"
Szólék én ábrándozva Erzsikéhez.
"A csillag vissza fog vezetni majd
A mult időknek boldog emlékéhez,
Ha elszakaszt a sors egymástul minket."
S választottunk magunknak csillagot.
Az országúton végig a szekérrel
A négy ökör lassacskán ballagott.','Nem Pesten történt, amit hallotok.
Ott ily regényes dolgok nem történnek.
A társaságnak úri tagjai
Szekérre ültek és azon menének.','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,379,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-146','petofi','Szerelem átka','Te vitéz Barangó, hova oly vágtatva?
Mért öltöztél fényes hadi páncélodba?
Mért fényesebb szemed fényes páncélodnál
S kezedben villogó kardod acélánál?

Vitéz Barangónak leszen útja hosszu,
Azért megy sebesen, mint halálos bosszu,
De nem bosszu űzi, hanem a szerelem,
Azért a tündöklő szikra szemeiben.

Szép szeretője van vitéz Barangónak,
Híják szeretőjét a szép Ildikónak.
Ildikónak arca szép, mint az ég boltja;
Szeme, mint a nap, a csillagot kioltja.

Barangó szerette őt véghetetlenűl,
Föl is szólította: menjen hozzá nejűl.
Ildikó felele: "Kezem neked adom,
Hogyha teljesíted három kivánatom.

Hozz nekem az égből szivárványdarabot,
Menyasszonyi ruhát majd abból varratok;
Hozz nekem rózsákat a hajnal kertébül
Koszorúnak főmre nászi ékességül;

Végső kivánságom a göncölszekere,
Ezen űljek, hogyha megyünk esketőre.
Ha teljesíted e három kívánságot,
Férjem leszesz, veled élek házasságot."

Im, ezek valának Ildikó szavai.
Barangó alighogy hallá kimondani,
Paripáján termett s gyorsan elrobogott,
S hozott először is szivárványdarabot.

Azután berontott a hajnal kertébe,
És a legvirítóbb rózsákat letépte.
Sok bajába kerűlt mindezt végbevinni,
De vitézségének nem állt gátul semmi.

Most megyen harmadszor a göncölszekerért.
Magára öltötte minden jó fegyverét;
Ha szép szóval meg nem kapja, amit akar.
Erőszakkal vívja ki a fegyveres kar.

Szép Tündérországban éktelen sok a kincs,
Hanem hát a göncölszekérnek párja nincs;
Őriztetik is ám a fenevadakkal,
Meredő körmökkel, tátongó szájakkal.

Barangó odaér, kéri a szekeret;
De mihelyest kérő beszéde megeredt,
Végét nem is várva, nekirohantanak
Dühös méreggel az őrző fenevadak.

Esztendeig harcolt Barangó hős keze,
Mig elhullt a szekér egész őrizete,
Mig kivívta a nagy és véres diadalt,
Amelybe maga is majd hogy bele nem halt.

Ekkoron Barangó nem is tett egyebet,
Az istálóból négy tátost kivezetett.
A legszebb négy tátost vezette ki onnan,
S befogta őket a szekérbe legottan.

A gyémántos gyeplőt ragadta kezéba,
Csillagsugárostort a másik kezébe,
Saját paripáját saraglyához köté,
Ugy hajtott serényen szeretője felé.

Szeretője addig, szép Ildikó, mit tett?
Gondolta Barangó: búsan várja őtet,
Gondolta Barangó: "szivem Ildikója,
Ne marjon a bánat fulánkos kigyója!

Ne marjon a bánat fulánkos kigyója,
Közeledem immár, szivem Ildikója!
Közeledem hozzád szép göncöl szekerén,
És boldog vagyok, mert kezed megnyerem én.

Ne félj, jó Barangó, Ildikó nem búsul!
Vigad ő más karján kicsiny magzatostul,
Van már kis magzata, van már férje neki,
Jősz-e te vagy nem jősz? nem igen keresi.

Feledte Ildikó régen igéretét,
A jött-ment Kevének adta szivét, kezét.
Keve bírja mostan azt a boldogságot,
Melyért kezed fáradt és szived sovárgott.

Ildikó most is ott űl Keve ölében,
Egymást csókolgatják, ölelgetik épen.
Amint ezt meglátja jó Barangó vitéz,
Nincs ereje szólni, csak merőn áll és néz.

De föllázad a vér félholt nyugalmábul,
Barangónak összeszorult szive tágul,
Eszeveszett harag fut égő agyába,
Kirántja szablyáját és megindul lába.

A két szeretőnek borsózott a háta,
Mikor a vitézt így közeledni látta,
Egymás kebeléről gyorsan fölriadnak,
Megszökni előle a szilaj haragnak.

Hős Barangó erre kardját elvetette,
És ily szókat ejtett nagy gúnnyal nevetve:
"Nem érdemlitek meg, hogy ezen kar által
Ismerkedjetek meg a méltó halállal!

Nem fogja szívetek kardom hegye érni,
Te szószegő asszony, te csábító férfi!
De ami átka van a széles világnak,
Ha isten meghallgat, mind reátok szállnak.

Mindkettőtök élte legyen halhatatlan,
Hogy szenvedhessetek örökös kinokban.
Éljetek, mig eljön az üstököscsillag,
Melytől a rengő föld sarkai bomolnak.

Kivánom: váljatok kővé mind a ketten,
Szivetek a kíntól hogy meg ne repedjen.
Te csábító férfi, amint most kebled ég:
Azt olyan mértékben örök lángok egyék.

S te szószegő asszony, bűnbánó könnyeid
Szünetlen folyjanak a világ végeig,
És a patakba, mely szemeidből ered,
Könnyed patakjába fuladjon gyermeked.

S az én életem is legyen halhatatlan,
Hogy kínaitokat váltig kacaghassam!"
Barangó vitéz az átkot így végezte,
Meghallgatta isten s beteljesítette.

Kősziklákká váltak Ildikó és Keve.
Csábító Kevéből tűzokádó leve,
Hányja magából a tüzet szakadatlan,
Mai nap is hányja s jajgat a kinokban.

És amely Ildikó volt egykor, a hegyből
Kiapadhatatlan két forrás buzog föl,
E forrásokba fult be kicsiny magzata,
Kit isten a völgyben fává változtata.

Barangóból pedig sötét fergeteg lett,
Mely ottan borong a két átkos hegy felett.
Mig Ildikó sír és míg Keve lángol s nyög,
Reájuk Barangó rettentőn mennydörög.','Te vitéz Barangó, hova oly vágtatva?
Mért öltöztél fényes hadi páncélodba?
Mért fényesebb szemed fényes páncélodnál
S kezedben villogó kardod acélánál?','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Természet','Szerelem','Elmúlás']::text[],'{}'::text[],false,380,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-147','petofi','A magyar nemes','Őseimnek véres kardja
Fogason függ, rozsda marja,
Rozsda marja, nem ragyog.
Én magyar nemes vagyok!

Munkátlanság csak az élet.
Van életem, mert henyélek.
A paraszté a dolog.
Én magyar nemes vagyok!

Jól készítsd, paraszt, az útat,
Mert hisz a te lovad vontat.
Csak nem járhatok gyalog.
Én magyar nemes vagyok!

Tán a tudománynak éljek?
A tudósok mind szegények.
Nem irok, nem olvasok.
Én magyar nemes vagyok!

Van, igaz, egy tudományom,
Ebben párom ritkán látom:
Enni, inni jól tudok.
Én magyar nemes vagyok!

Milyen jó, hogy nem adózok.
Gazdaságom van, de nem sok,
S van adósságom, de sok.
Én magyar nemes vagyok!

Mit törődöm a hazával?
A hazának száz bajával?
Majd elmulnak a bajok.
Én magyar nemes vagyok!

Ősi joggal, ősi házban
Éltemet ha elpipáztam:
Mennybe visznek angyalok.
Én magyar nemes vagyok!','Őseimnek véres kardja
Fogason függ, rozsda marja,
Rozsda marja, nem ragyog.
Én magyar nemes vagyok!','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Haza']::text[],'{}'::text[],false,381,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-148','petofi','Gyermekkori barátnémhoz','Te vagy? valóban te vagy az?
Vagy e látmány csak képzelet?
Csak képzetemnek tündér délibábja,
Amelyben lelkem ujra látja
Szép arcod s boldog gyermekségemet?

Te vagy valóban! ennyire
Csalódás nem megy, nem mehet;
Ismérem én jól e szemek sugárát,
Amellyel glóriába zárád
Hajdanta boldog gyermekségemet.

A kisleányból hajadon,
A kisfiúból ifju lett;
Jött az idő, mely soha meg nem állott,
S miként a szélvész a virágot,
Elvitte boldog gyermekségemet.

Azóta tiszta látköröm
Oly gyakran elsötétedett,
S az éjszakában, mely sírként fedett el,
Csak egy csillag volt, a könny, mellyel
Sirattam boldog gyermekségemet.

Viszontlátásunk ünnepén
Ölelj meg, lyánykám, engemet;
Hagyd elfeledni kínos ifjuságom,
Hagyd karjaidban ujra látnom
Ragyogni boldog gyermekségemet!','Te vagy? valóban te vagy az?
Vagy e látmány csak képzelet?
Csak képzetemnek tündér délibábja,
Amelyben lelkem ujra látja','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Gyermekkor','Természet']::text[],'{}'::text[],false,382,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-149','petofi','A költő s a szőlővessző','Semmi vágyam, semmi kedvem
A borostyánkoszorúhoz!
Magyarország szép leányi,
Szőlővessző-koszorúval
Koszorúzzatok meg engem,
Mert a szőlővessző és a
Költő sorsa oly hasonló.
Költő és a szőlővessző
A világnak adja lelkét.
Szőlővessző lelke a bor,
A költőnek lelke a dal.
Lelkünket ha általadtuk
Borban, dalban a világnak:
Elhervadunk, elenyészünk.
És midőn már elenyésztünk:
Lelkeink, a bor s dal mellett
Vígad a világ! - - -','Semmi vágyam, semmi kedvem
A borostyánkoszorúhoz!
Magyarország szép leányi,
Szőlővessző-koszorúval','Borjád, 1845. szeptember 26. - október 7. között',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,383,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-150','petofi','A csárda romjai','Te vagy, oh szép alföld végtelen rónája,
Lelkem legkedvesebb mulatótanyája.
Az a görbe felföld hegy- és völgyeivel
Könyv, melynek számtalan lapját forgatni kell,
De te, alföldem, hol hegy után hegy nem kél,
Olyan vagy, mint a nyilt, a fölbontott levél,
Amelyet egyszerre általolvashatok;
S vannak beléd írva szép, nagy gondolatok.
Mint sajnálom én, hogy egész életemet
Itt kinn a pusztákon töltenem nem lehet!
Itt szeretnék élni a puszták közepin,
Mint Arábiában a szabad beduin.
Puszta, puszta, te vagy a szabadság képe,
És, szabadság, te vagy lelkem istensége!
Szabadság, istenem, még csak azért élek,
Csak azért, hogy egykor érted haljak én meg,
S síromnál, ha érted onthatom véremet,
Meg fogom áldani átkos életemet.
De mi ez? sír... halál... hova nem vetődtem!
Nem csoda különben, mert rom van előttem.
Nem váromladék ez. Csárdának romjai.
Hanem hiszen azt az idő nem keresi:
Mely''k milyen épület? vár-e avvagy csárda?
Ennek is, annak is reálép falára;
S hova az idő lép, omlik, ha kő, ha vas,
És neki semmi nem alacsony, nem magas. -
Hogy van, hogy e csárda kövekből épüle?
Holott kőtermésnek nyoma sincs körüle.
Itt régente falu avvagy város állott,
Míg nem nyögte hazánk a török rabságot;
(Szegény Magyarország, szegény édes honom,
Be sokféle bilincs volt már lábaidon!)
E hajdani várost földúlta az ozmán,
Kő kövön nem maradt, csak az isten házán.
A templom maradt meg - de ez is betegen -
Hogy a pusztulásnak gyászolója legyen.
És gyászolt a templom több hosszu századot,
Míg végre bujában össze nem roskadott.
Hogy haszna ne vesszen széthullott kövének,
Belőle e helyen csárdát épitének.
Az isten házából csárda!... és miért ne?
Ott léleknek: testnek szolgált itt enyhére.
És nem ugy részünk-e a test, mint a lélek?
Egyenlőn kedveznünk kell mind a kettőnek.
Az isten házából csárda!... és miért ne?
Itt és ott élhetünk az isten kedvére;
S láttam én csárdákban tisztább szíveket már,
Mint kit naponként lát térdelni az oltár. -
Csárda, eldőlt csárda, még mikor tebenned
Utasok vigadtak, utasok pihentek!
Fölépít tégedet újra képzeletem,
S vendégidet színről-színre szemlélhetem:
Itt görcsös botjával egy vándorlólegény,
Ott zsíros subában egy pár szegénylegény,
Itt hosszu szakállal egy üveges zsidó,
Amott egy drótostót s több ilyen borozó.
Hát a szép csaplárné fiatalságával?
Mostan ölelkezik egy hamis deákkal,
Kinek a bor kissé megzavarta fejét,
De a szép menyecske még jobban a szivét.
S hol a vén csaplár, hogy ezért föl nem pattan?
Kinn a kazal végén álmodik nyugodtan...
Kazal végén akkor, most már lenn a sírban,
És a szép fiatal menyecske is ott van,
És a hamis deák s mind, kik itt boroztak.
Ők valamennyien már rég porladoznak.
A csárda is vénült, vénült és roskadott,
Leüté fejéről a szél a kalapot,
A födelet.. ekkép áll hajadon fővel,
Mintha urával beszélne, az idővel,
S kérné alázattal, hogy kissé kimélje;
Hanem sikeretlen esdeklő beszédje.
Dűledez, dűledez; félig ismerni csak:
Melyik volt az ajtó, melyik volt az ablak.
Még áll s emelkedik az éghez kéménye,
Mint a haldoklónak utósó reménye.
Pincéje beomlott, a kút is mellette,
Honnan az ostorfát valaki elvitte;
Csak az ágas és a gém van meg épségben,
Egy mogorva sas űl a gém tetejében.
Legmagasabb hely a pusztán e gém vége,
Azért ült föl a sas ennek tetejébe.
Fönn űl és merően maga elé bámul,
Mintha gondolkodnék a mulandóságrul.
Fölötte lángol a nap, az égnek ifja,
Lángol, mert kebelét a szerelem vívja;
Szeretője, aki epedve néz rája,
Délibáb, a puszták szép tündérleánya.','Te vagy, oh szép alföld végtelen rónája,
Lelkem legkedvesebb mulatótanyája.
Az a görbe felföld hegy- és völgyeivel
Könyv, melynek számtalan lapját forgatni kell,','Szalkszentmárton, 1845. október 8-16. között',1845,'1845',array['Természet','Haza','Elmúlás']::text[],'{}'::text[],false,384,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-151','petofi','Változás','Nem úgy van, amint volt. A földön
Minden mindegyre változik.
Multam s jelenkorom két testvér,
S egymást tán meg sem ismerik.

A tenyeremben hordtam egykor
Szivem, barátsággal tele;
Nem volt szükség, hogy kérjék tőlem:
Magam kináltam mást vele.

Mostan ha kérik szívemet sem
Adom, nem adom senkinek.
Azt hazudom, ha jőnek hozzám:
"Nincsen szivem, eredjetek!"

Egykor ha szerelemre gyúltam:
Plátói szerelem vala.
Oly szentül hittem, hogy minden lyány
A mennyországnak angyala.

Azt hittem!... most tudom, hogy inkább
Ördög, mint angyal a leány;
S nem sírok, ha nem kellek egynek,
Akad helyette akarhány.

A hazaszeretet napom volt,
Mely melegíté lelkemet;
S mi mostan? holdvilág, mely sárga
Hideg sugárt arcomra vet.

Egykor ha a világ megbántott,
Kivánkozám a sírba le;
Most, épen mert bánt, élni vágyok,
Dacolni van kedvem vele.

Agyag voltam, hig, engedékeny,
Egy ujjal is átszúrható;
Márvány vagyok... ki rám lő: rólam
Rá visszapattan a golyó.

Fehér bor, szőke lyány, fényes nap
Hatottak egykor lelkemig;
Vörös bor, barna lyány, sötét éj,
Kedvem most bennetek telik!','Nem úgy van, amint volt. A földön
Minden mindegyre változik.
Multam s jelenkorom két testvér,
S egymást tán meg sem ismerik.','Szalkszentmárton, 1845. október 8-16. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,385,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-152','petofi','Hegyen űlök...','Hegyen űlök, búsan nézek le róla,
Mint a boglya tetejéről a gólya.
Lenn a völgyben lassu patak tévedez,
Az én fáradt életemnek képe ez.

Elfárasztott engemet a szenvedés.
Be sok búm volt, örömem meg be kevés!
Bánatomból egy nagy árvíz lehetne,
Örömem kis sziget lenne csak benne.

Fenn a hegyen, lenn a völgyben zúg a szél,
Közelget az időjárás ősz felé;
Ősszel szép csak a természet énnekem,
A haldokló természetet szeretem.

Tarka madár nem fütyörész az ágon,
Sárgapiros levél csörög a fákon,
Innen-onnan lehull a fák levele...
Bárcsak én is lehullanék ővele!

Holtom után vajjon mi lesz belőlem?
Vadfa lenni szeretnék az erdőben;
Ott lenne az én számomra jó tanya,
Egész világ engem ott nem bántana.

Szeretném, ha vadfa lennék erdőben,
Még inkább: ha tűzvész lenne belőlem;
Elégetném ezt az egész világot,
Mely engemet mindörökké csak bántott.','Hegyen űlök, búsan nézek le róla,
Mint a boglya tetejéről a gólya.
Lenn a völgyben lassu patak tévedez,
Az én fáradt életemnek képe ez.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,386,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-153','petofi','Megpendítem...','Megpendítem hónapok multával
Még egyszer szerelmi lantomat;
Még ez egyszer, egyszer és utószor,
Mert ezentúl hangot ő nem ad.

Nem pazarlom én többé leányra
Dalaimat, érzeményimet.
Érzéketlen bábak a leányok,
Szívet és dalt nem érdemlenek.

Nem beszél vak indulat belőlem;
Csendes elmém, higgadt szózata.
Megszűnt már a vész, mely nem viszonzott
Szerelmem kínjából támada.

Tiszta szemmel nézek a jövőbe,
Nem lebeg rajt szenvedély köde.
Mely előlem annyi szép virányt, de
Annyi puszta tájt is elföde.

Tiszta szemmel nézek a jövőbe,
Jaj de mit lát, mit lát ott szemem?
Azt, hogy nincs már semmi szépet látnom...
Nincs barátság, nincs ott szerelem!

Egyedűl, e roppant nagy világtól
Elhagyatva, szeretetlenűl,
Máriusként, aki számüzötten
Egy országnak omladékin űl!

Nem lehet, hogy én még nem szeressek,
És hogy engem ne szeressenek!
Bármily hideg a világ: szívem még
Nem fagyott meg, szívem még meleg.

Lesz leány még, kell leánynak lenni,
Aki éreztesse majd velem,
Hogy áldás az átkos élet, melyben
Van egy percnyi boldog szerelem!','Megpendítem hónapok multával
Még egyszer szerelmi lantomat;
Még ez egyszer, egyszer és utószor,
Mert ezentúl hangot ő nem ad.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,387,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184506-154','petofi','Lehel','Melyik szerelmes nem választ magának
A számtalan közűl egy csillagot?
És melyik költő nem választ magának
A számtalan közűl egy bajnokot?...
Ezt Toldy Miklós, azt Kont lelkesíti;
Ki a vitéz, ki engem föltüzel?
Ki e vitéz?... a kürtharsogtatással
Országokat reszkettető Lehel!

Ez volt a hős, ez volt a kürt!... e hősnek
Halála egy nagy égzengés vala;
Kilencszáz év mult, és ez égzengésre
Most kél a viszhang: lantomnak dala.
Ti jászok és ti kúnok, hallgassátok,
Mert, ugy hiszem, legjobban érdekel
Titeket, ő, a kürtharsogtatással
Országokat reszkettető Lehel.

Mi a legjobb köszörükő? a bosszu;
Ez fente meg a magyar kardokat.
Mi a leggyorsabb fergeteg? a bosszu;
Ez hordja mostan a magyarokat.
Éles kardokkal, szélvészrohanással
A németek földére érnek el;
Elől száguld a kürtharsogtatással
Országokat reszkettető Lehel.

Hiába fented kardodat, magyarság!
Felsőbb hatalom esküdt ellened.
Harcod koporsó, óriás koporsó,
Amelybe dicsőséged temeted.
Nagy lakomája volt ez a halálnak,
S kit el nem költe: mint rab vesztegel.
Ezek között a kürtharsogtatással
Országokat reszkettető Lehel.

"Akasztófára!" dörg a német császár,
"Akasztófára e zsiványokat!
Haha, hittétek-e ti száraz fák, hogy
Teremni fogtok még virágokat?
Lám, kivirúltok újolag. - Mivelhogy
A vezér elsőséget érdemel:
Előre hát, te kürtharsogtatással
Országokat reszkettető Lehel!"

Kilépe a hős: "Isten néki, császár,
Függjek koszoruként ez oszlopon. -
Német vagy, nem t''om: lesz-e emberséged?
Meghallgatod-e végkivánatom?
Szeretnék egyszer még kürtömbe fujni,
Vén bajtársamtól hadd bucsúzzak el!"
Ekkép beszélt a kürtharsogtatással
Országokat reszkettető Lehel.

Megkapta kürtjét s úgy megfujta a hős,
Hogy a császár megsiketült bele,
Megsiketűlt és eldőlt... innenonnan
Kilencszáz éve, s még föl sem kele.
Nem is kel ő fel többé. - Jászberényben
Még megvan a kürt csorba élivel,
Mit megcsorbított a császár fején a
Győzötten is még győzelmes Lehel.','Melyik szerelmes nem választ magának
A számtalan közűl egy csillagot?
És melyik költő nem választ magának
A számtalan közűl egy bajnokot?...','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Elmúlás','Természet','Haza']::text[],'{}'::text[],false,388,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-155','petofi','Örök ölelkezés','A téren kettős sírhalom van,
Fölöttök egy-egy zöld bokor;
Egymásra hajlanak, miként ha
Két szerető szív összeforr.

Igen, két szerető szív szálla
Pihenni e két domb alá,
Midőn a háborgó életnek
Kemény harcát kiharcolá.

Egymás mellé temetteték a
Hű szeretők itt magokat,
Hogy egyesűlve legyenek, mint
A földön, úgy a föld alatt.

És egyesűlve maradának.
Mely a sírhalmokon növe,
A két ölelkező bokorfa
A két szerelmes szelleme.','A téren kettős sírhalom van,
Fölöttök egy-egy zöld bokor;
Egymásra hajlanak, miként ha
Két szerető szív összeforr.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,389,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-156','petofi','Forrás és folyam','Szelíd a forrás habja, s dalai
Beillenének csengetyű szavának.
Ilyen szelídek és csengők valának
Ifjúságomnak első hangjai.

Akkor kedélyem a forrás vala,
Mosolygó tűkre a szép mennyországnak,
Nap, csillagok s hold beleláthatának.
Szivem volt a forrás vig, fris hala.

De a kis forrás most már nagy folyam,
Csengő szavát s nyugalmát elvesztette,
Vészek kergetnek vészeket fölötte,
S belé a mennynek nézni hasztalan.

Ne nézz beléje, oh menny, hasztalan!
Magad most benne ugysem láthatod meg,
Mert az csatáitól a fergetegnek
Mind fenekiglen fölforgatva van.

És mit jelent e vérfolt a vizen,
E vérfolt a haboknak közepette?...
Horgát a vad világ beléd ütötte,
Te vérzel, árva hal, szegény szivem!','Szelíd a forrás habja, s dalai
Beillenének csengetyű szavának.
Ilyen szelídek és csengők valának
Ifjúságomnak első hangjai.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,390,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-157','petofi','A jegygyürű','"Isméred e gyürűt?
Aranymives barátom!"
- ''Ismerém jól, uram.
E gyűrüt én csináltam;

Azt is tudom, kinek
Számára készíttetted.
Az szép leányka volt,
És aztán hitvesed lett.''

- "Igen, szép lyányka volt,
És aztán hitvesem lett.
De megszegé hitét
S mással kötött szerelmet.

E gyűrü rosz helyen
Volt ujján; visszavettem.
Legdrágább kincsem ez,
Jobb helyre kell hát tennem.

Ezennel önts golyót
E gyűrüből barátom!...
...Fegyverbe töltöm azt,
S szivem, beléd bocsátom."','"Isméred e gyürűt?
Aranymives barátom!"
- ''Ismerém jól, uram.
E gyűrüt én csináltam;','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,391,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-158','petofi','Jókay mórhoz','Miért szeretsz te engemet,
Kit annyian gyülölnek?
S én, aki annyit gyűlölök,
Téged miért szeretlek?
Szeretlek téged, oh barátom...
Nem, nem barátom!... megbocsáss,
Hogy e gúnynévvel illetélek;
Mert a jelenkor gyermekének
E szó "barát" csak gúnyolás.

Percenként jobban-jobban el-
Sötétül láthatárom,
De én éltemnek éjjelét
Nem rettegem, sőt várom...
Hisz annál fényesebb a csillag,
Minél sötétb az éjszaka.
Tudom, mert a szív mondja nékem:
Te lész sötét, kietlen éjem
Hamvadhatatlan csillaga.

Nem hiszek én már senkinek,
Nincs senkiben bizalmam,
Mert életemben sokszor, ah,
Oly sokszor megcsalattam.
Bizalmam várát fölgyujtották,
Ledöntötték az emberek;
Romjai között egy ép oszlop van:
Te állasz ott... csak te... magadban...
Téged le nem dönthettenek.

Szentül hiszem, ha a világ
Elfordul is szivemtül,
Ha a világnak ajakán
Rám átkok átka zendül:
A te ajkadról akkor is még
Reám csak áldás lebben el...
Ha az egész világ egy kéz lesz,
Mely eltaszít, miként dögvészest:
Kezed még akkor is ölel.

Tudom, hogy így tesz a világ,
Hogy így fog tenni vélem.
Fejemre köveket hajít,
Míg éltemet leélem.
S hóhéraim, ha halva fekszem,
Agyonveretve, egykoron:
Koporsómhoz majd odalépnek,
S melyet elébb megkövezének,
Babérral födik homlokom.

Oh e babér, amellyel a
Világ magát gunyolja,
Ez a babér, ez a babér
Velőm égetni fogja.
De nem soká tart égetése...
Te, lelkem megmaradt fele,
Hozzám te szinte eljövendesz,
És koszorúmra könnyet ejtesz,
S eloltod lángjait vele.','Miért szeretsz te engemet,
Kit annyian gyülölnek?
S én, aki annyit gyűlölök,
Téged miért szeretlek?','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,392,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-159','petofi','Remény','Mi a remény?... förtelmes kéjleány,
Ki minden embert egyaránt ölel.
Ha rápazarlod legszebb kincsedet,
Az ifjuságot: akkor elhagy, el!','Mi a remény?... förtelmes kéjleány,
Ki minden embert egyaránt ölel.
Ha rápazarlod legszebb kincsedet,
Az ifjuságot: akkor elhagy, el!','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Szerelem']::text[],'{}'::text[],false,393,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-160','petofi','A hazáról','Lement a nap. De csillagok
Nem jöttenek. Sötét az ég.
Közel s távolban semmi fény nincs,
Csak mécsvilágom s honszerelmem ég.

Szép csillag a honszeretet,
Gyönyörüségesen ragyog.
Szegény hazám, szegény hazám te,
Neked kevés van ilyen csillagod.

Mécsemnek lángja mint lobog!
Mitől lobog? mi lengeti?
Éjfélt ütött. Ti lengtek itten
Mécsem körül, ti népem ősei!

Mintha nap volna mindenik,
Oly tündöklők e szellemek,
Tündöklők, mert hisz a dicsőség
Sugármezébe öltözködtenek.

Ne nézz ősidre, oh magyar,
Ki most sötétségben vagy itt,
Ne nézz ősidre, e napokra...
Szemeid gyöngék... a napfény megvakít.

Hazám dicső nagy ősei,
Ti földetrázó viharok!
Ti egykoron a porba omlott
Európa homlokán tomboltatok.

Oh nagy volt hajdan a magyar,
Nagy volt hatalma, birtoka;
Magyar tenger vizében húnyt el
Éjszak, kelet s dél hullócsillaga.

Csakhogy rég volt, midőn magyar
Fejekre termett a babér;
A képzelet sebes szárnyú sas,
Elfárad mégis, mire odaér.

Oly rég elhervadt a babér
A magyaroknak homlokán,
Hazám, oly rég voltál te nagy, hogy
Nagyságod híre csak mese talán.

Már rég nem sírtam, s íme most
Pillámon egy könny rengedez.
Magyar nép, vajjon hajnalodnak
Vagy alkonyodnak harmatcseppje ez?

Magyar dicsőség, mi valál?
Hullócsillag? mely tündökölt,
Aztán lehullott a magasból
És mindörökre elnyelé a föld.

Vagy üstökös vagy, oh magyar
Dicsőség! mely jött s távozék,
Hogy századok multával ujra
Lássák fényét a népek s rettegjék?','Lement a nap. De csillagok
Nem jöttenek. Sötét az ég.
Közel s távolban semmi fény nincs,
Csak mécsvilágom s honszerelmem ég.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Haza','Természet']::text[],'{}'::text[],false,394,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-161','petofi','A sivatag koronája','Olyan, mint vén királynak
Feje, a sivatag;
Hajszálai, a fűvek,
Csak gyéren inganak.

E vén királyi főn egy
Nagy tölgy a korona.
Ha megszólamlanék, sok
Századról szólana.

Megszólamlott végtére.
Kóbor felhő jöve;
Elfáradott, s leszálla
Pihenni fölibe.

Ez kérte, mondaná el
Élettörténetét,
És a felhőnek a tölgy
Következőt beszélt:

*

"Távol világ regényes bércein
Virágozának boldog őseim.
Anyám - közel hozzá az égi bolt -
A vadonerdő legszebb fája volt.
A fergeteg beléje szeretett,
S mivel szerelme célt nem érhetett:
Anyámra - oh mi aljaslelküség! -
Szegény anyámra bosszut esküvék.
És teljesíté. Ottan függtem én
Testvéreimmel szűlőnk kebelén;
Letépe minket és szétkergetett
A bosszujában rémes fergeteg.
Idáig űzött engem haraga,
E sivatag magába fogada,
Felnőttem itten és sok századot
Láttam már, amint jött és távozott.
Ah, mily unalmas hosszu életem!
Csak szomorúság széttekintenem;
Bármerre nézek: látnom nem lehet
Szegény anyámat és testvérimet.
Koronként jőnek hozzám emberek,
Javokra vagyok, amint lehetek.
Ki nyáron jő, midőn nap égeti,
Szolgálok hűvös sátorúl neki;
Ha jőnek erre tél-idő alatt,
Adok tüzelni száraz ágakat,
S akit kétségbeejte a világ,
Jön s fölakasztja énreám magát. -
S ezzel végeztem. Eddig terjede
Hosszú éltem rövid története.
Éltemnek is bár vége volna már!
A fergeteg, mely ide-ide jár,
A fergeteg, e régi ellenem,
Nem győzhetett meg, nem bírt énvelem.
S a hőst, ki annyi századéven át
Oly bátran, olyan rendületlen állt,
E hőst mi fogja most eldönteni?
Önnön keblének hitvány férgei!
Oh isten, isten, aki alkotál,
Hát nincs számomra nemesebb halál?"

*

Im ezt beszélte a tölgy.
Fönn űlt a tölgytetőn
A felleg, s a beszédet
Hallgatta részvevőn.

Részvétből, szánalomból
Villámot vett elé,
Az árva tölgyre sujtá
S azt porrá égeté.','Olyan, mint vén királynak
Feje, a sivatag;
Hajszálai, a fűvek,
Csak gyéren inganak.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Természet','Család']::text[],'{}'::text[],false,395,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-162','petofi','Hogy van, hogy azt a sok gazembert...','Hogy van, hogy azt a sok gazembert
Egytől-egyig föl nem kötik?...
Tán csak azért, mert annyi fája
Nincs a világnak, hogy reája
Akasztathatnék mindenik.

Oh mennyi, mennyi a gazember
E földön!... én megesküszöm:
Ha mind esőcseppé változnék,
Negyven nap, negyven éjjel esnék,
Támadna egy új vízözön.','Hogy van, hogy azt a sok gazembert
Egytől-egyig föl nem kötik?...
Tán csak azért, mert annyi fája
Nincs a világnak, hogy reája','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,396,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-163','petofi','A gyüldei ifjakhoz','A honnak egy igaz zászlója van,
Ezt mi álljuk körűl,
S ti elhagyátok a hon zászlaját?
Elhagyhatátok, oh, ifjak, hitetlenűl?

(Szégen, gyalázat! hát az oroszlán
Rókák fészkébe tér?...)
Silány rongyot hogy cserélhettetek
A haza szentséges, dicső zászlójaért!

Higyétek el, hogy rókafészek az,
Hová beléptetek,
Ha rá más bizonyság nem volna is,
Elég az, hogy papok tanyáznak köztetek.

Pap és ravaszság, pap és árulás,
Pap és minden rosz... egy!
Ott a gonoszság, ott van a pokol,
A kárhozat, hová ily férfi-szoknya megy.

Okos volt, aki öltözetjöket
Barnának rendelé,
Fehér ruhát azért nem hordanak,
Mert azt sötét lelkök befeketítené.

Mint öltözetjök, lelkök oly setét,
Ők éjszakának gyermeki;
Azért látjátok őket mindenütt
A szabadság, e napfény ellen küzdeni.

Hol a szabadság, ott van a haza,
S ti elválhattatok
E két szentségtől, és olyan korán!
Mert hisz fiatalok vagytok, fiatalok.

Nem jó idők!... a féreg eddig a
Vén fákat rágta csak;
Ti ifjak vagytok, ifjú csemeték
És a férgek máris belétek hulltanak.

A férges fát mi várja? rothadás!
Ti hát rothadjatok...
Minket levágnak s tűzre tesznek tán,
De lelkünk lesz a láng, mely égbe szállni fog.','A honnak egy igaz zászlója van,
Ezt mi álljuk körűl,
S ti elhagyátok a hon zászlaját?
Elhagyhatátok, oh, ifjak, hitetlenűl?','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Haza']::text[],'{}'::text[],false,397,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-164','petofi','Álmos vagyok és mégsem alhatom...','Álmos vagyok és mégsem alhatom;
Ébren vagyok és mégis álmodom.
Gyertyám pislog komorhomályosan,
Mint a lidérc, mely temetőbe'' van;
S ki nem merem kezemet nyujtani:
Elvenni hamvát vagy eloltani.
Ágyamban fekszem mozdulatlanul.
Előttem el rém rém után vonul.
Hiába húnyom be szemeimet,
Látom még akkor is e rémeket.
És milyen rémek, milyen alakok!
Arcomról hideg izzadás csorog.
Ott mély árokban egy koldús halott,
Fölkél és rágja a koldúsbotot.
Kemény. Beléje törnek fogai,
Látom szájából a vért omlani.
Itt egy öreg cigány, a deresen,
Ütik, verik kinoskeservesen,
Vernek le róla húsdarabokat;
Fájdalmában, mint a kutya, ugat.
Hát az mi ott? torony vagy óriás?
S mit mível? kútat vagy sirgödröt ás?
Nem sír lesz az, nem. Kút; mert ott hever
Mellette a nagy százakós veder;
Most leereszti a roppant vedert...
Nem víz, de vér, mit e kútból kimert.
Itt egy ifjú, ki lenyakaztaték,
Viszi fejét, markolva üstökét,
S szólván: "nem én, de te vagy a zsivány!"
Bedobja azt a bíró ablakán.
Ott akasztófa, rajta csecsemő;
A csecsemőnek anyja odajő,
Megfogja lábát, s húzza, húzza le,
S körűltáncolja a bitót vele.
Itt egy leány, két béka ül szemén,
Nyúzott patkány van orrának helyén,
Hosszú férgekből vannak fürtei,
S őt félkigyó-félember öleli. - -
Ily szörnyeket lát lázas képzetem.
Elkergetném s el nem kergethetem.
Mindenki alszik, csak magam vagyok
Nem alvó. Csend van, csak fogam vacog.','Álmos vagyok és mégsem alhatom;
Ébren vagyok és mégis álmodom.
Gyertyám pislog komorhomályosan,
Mint a lidérc, mely temetőbe'' van;','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,398,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-165','petofi','Álmaim','Irtóztatók koronként álmaim.
Az éjjel is szörnyűket álmodám.
Alighogy eltűnt egyik álomképem,
Másik mereszte vad szemet reám.

Láttam biborban a bűn hőseit,
Tiprott erény volt lábok zsámolya.
Fehérpirosra volt e zsámoly festve:
Szeméből könny, szivéből vér folya.

Láttam kiszáradt sárga arcokat,
Sárgák valának, mint az éji hold,
Igen bizony, mert minden arc az éhség
Éjének egy-egy holdvilága volt.

Láttam mellettök fényes arcokat,
Miken a jóllét napja ragyoga;
Bokáikon arany sarkantyu... sárga,
Mint amaz éhezők arcúlata.

Láttam halotti ágyon férfiút,
Szívének táján mély seb tátogott.
Saját magzatja ölte meg. De nője
Siratja tán a bús áldozatot?

Mit? nője? nője nem siratja őt!
Mig egy szobában a férj álmodik
Halotti ágyon: más szobában a nő
Uj szeretőjével bujálkodik.

S midőn sírban volt már a férfiú,
Eljöttek éjjel az atyafiak,
Feltörték sírja ajtaját, s halotti
Ruhája kincsén megosztoztanak.

Láttam veszendő, dúlt országokat,
Hol kész halál volt a polgárerény,
Hol éj közelge... már pirult az alkony
Hóhérok honfivéres fegyverén.

Láttam ledöntött, rab országokat,
Hol nem hallatszott a rabok jaja,
Mert jajgatásukat fölülhaladta
A zsarnokhatalom gúnykacaja.

Im, ilyek éji látományaim.
De nem csodálkozom, hogy ilyenek;
Mert amiket szemlélek álmaimban,
Történnek egyre és történtenek.

Meddig tart még ez iszonyú világ?
Miért nem jősz, te rontó égitest,
Te üstökös, mely arra rendeltettél,
Hogy tengelyéből a földet kivesd!','Irtóztatók koronként álmaim.
Az éjjel is szörnyűket álmodám.
Alighogy eltűnt egyik álomképem,
Másik mereszte vad szemet reám.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Elmúlás']::text[],'{}'::text[],false,399,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-166','petofi','Pusztai találkozás','Sík a puszta, mint a pihenő tó.
Közepén megy gazdag úri hintó.
Megy a hintó, mégpedig vágtatva,
Mintha villám volna belefogva.
Van beléje fogva négy paripa.
Az út olyan, mint a pallós szoba.
De a jó út s jó lovak dacára
Most a hintó hirtelen megálla.
Elvágták-e a négy hámistrángot?
Vagy a kerék mély kátyúba vágott?
Sem az egyik, sem a másik biz a!
Hanem ott termett a puszták fia,
Ottan termett a puszták királya,
A haramja; egy nagyot kiálta,
S pisztolyt vett ki a nyeregkápábul.
Azért áll a hintó és nem mozdul.
A haramja gyönge sikoltást hall,
Azt gondolja, hogy talán madárdal,
És körűlnéz és be a hintóba,
Hát ott van a madár, aki szóla;
Szép kis madár, gyönyörű menyecske,
Talán nem is él, csak úgy van festve.
"Könyörűlj!" szól, s tovább esdekelne,
De elvette hangját ijedelme.
A haramja lelkesen néz rája,
S ilyen nyájas szókra nyílik szája:
"Ne rettegjen, tekintetes asszony!
Nem gátolom, hogy tovább utazzon.
De mielőtt innen odább menne,
Kérem szépen, nézzen a szemembe!"
És az asszony félénk bátorsággal
Farkasszemet néz a haramjával,
Ki közelebb lépett, és megint kért:
"Tegyen meg még egyet a kedvemért:
Engedje megfognom szép kacsóját...
Megengedi? megengedi tehát?
Oh köszönöm, köszönöm!... de hátha
Volna még egy esdeklésem hátra?
Egyetlen egy... azután utazzon...
Csókoljon meg, tekintetes asszony! -
Arca pirul... harag ez vagy szégyen?
Oh, akármi, csak harag ne légyen;
Ne váljunk el haragban egymástól,
Inkább lemondok e kivánságról.
A csók úgyis, ha erőtetve jő,
Olyan, mint a korán szedett szőlő.
Teens asszony, isten áldja meg hát!
Felejtse el a szegény haramját.
Aki, aki..." itt megszakadt szava,
De érezte sarkantyúját lova,
Egyet ugrott és vágtatni kezdett,
Meg sem állott, amíg este nem lett.','Sík a puszta, mint a pihenő tó.
Közepén megy gazdag úri hintó.
Megy a hintó, mégpedig vágtatva,
Mintha villám volna belefogva.','Pest, 1845. október 16. - november 25. között',1845,'1845',array['Természet']::text[],'{}'::text[],false,400,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-167','petofi','Szemere pálhoz','Sok van, miben büszkélkednem lehet,
De büszkeségem mindenekfelett,
Hogy, mint barátod, úgy állok szivednél,
Bár korra nézve nagyapám lehetnél.
Tiszteltelek, mint tisztelőd menék
Hozzád. Te szóltál, hogy ez nem elég,
Engem ne tisztelj, engemet szeress!
Mostan szeretlek és tisztellek téged;
Mind a kettőre vagy te érdemes.
Mig tiszteletre indit öregséged,
Szeretnem kell ifjúi szívedet...
Mert nyom nélkül haladt el e felett
Esztendeidnek terhe, sokasága.
Hervadhatatlan kebled e virága.
Öreg barátom fiatal sziveddel!
Fa vagy te, melynek elhullt levele,
Amelyet már a téli hó lepett el,
De rajta vígan zeng a cinege.
S bár késő este van már életedben,
Szemed még most is tisztán s messze lát:
Megismeréd a felhők madarát,
Kit fényes nappal sem láttak meg többen.
Magamról szólok. - Hah, míg annyian
Vetnek reám lenéző szemeket,
Kezedben a borostyán lombja van,
Megkoszorúzni véle fejemet.
Tedd föl fejemre, tedd e koszorút!
Ha most nem érdemelném is, talán
Megérdemelni fogom ezután.
Előttem még olyan hosszú az út,
S a boldogságról már végkép lemondék,
Ugysem találnám meg, hát életem
Keresésére nem vesztegetem;
Szivemnek csak egy óhajtása van még...
Erre törekszem, ez amit kivánok:
Büszkén nevezzen a haza fiának! -
Elérem-e e nagy célt? féluton
Nem roskadok-e össze? nem tudom.
Tán egy bevégezetlen épület
Lesz életem munkája, meglehet,
Amely ha készen volna, beleszállna
A hír, a feledés örök királya,
Mig így elkezdve féligmeddig készen
Csak rövid emlék szűk tanyája lészen.
De ha erőm vágyamnál nem kisebb,
Ha ezt a hosszu pályát megfutandom,
S egy nemzet fogja megtapsolni lantom:
Nem lesz előttem e taps kedvesebb,
Mint az volt, mellyel pályám kezdetén
Egymagad által üdvezeltetém,
És mint szivednek dobbanása volt,
Midőn szivemre először hajolt.','Sok van, miben büszkélkednem lehet,
De büszkeségem mindenekfelett,
Hogy, mint barátod, úgy állok szivednél,
Bár korra nézve nagyapám lehetnél.','Szalkszentmárton, 1845. november 25. - december 31. között',1845,'1845',array['Természet','Szerelem']::text[],'{}'::text[],false,401,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1845-184507-168','petofi','Téli éj','Vad téli éj. Sürű hópelyhek esnek.
Szélvész ragadja. S hátha nem hópelyhek?
Talán egy őrült gondolatjai?
Vagy összetépett lelkem rongyai.

Közelg az éjfél. Fennvirasztva várom.
Akkor kisértet látogat meg, három;
Szent háromság, mely egykor vezetett:
A hit, a remény és a szeretet.

Nem élnek többé. Meggyilkoltatának.
De éjfelenként sírjokból kiszállnak,
S felém lebegnek halvány képeik,
S a régi szép időt emlegetik. -

Szétszaggatá a felleget a szélvész.
Tekintetem a csillagok közé vész.
Olyan sötétpiroslók fényeik,
Mikéntha vércsepp volna mindegyik.

S ki mondja meg: nem vércsepp-e a csillag?
Hisz itt a földön oly sokat gyilkolnak.
Ábelszivek fölfeccsent vére ez,
Mit a zsivány föld csillagnak nevez. -

Veszett szélvész, te még mindegyre tombolsz,
A fellegekbe és hajamba markolsz;
Ki akarod tán tépni fürtimet?
Ah, tépd ki inkább, tépd ki szívemet!

Hogy dobog e szív! - szinte félek tőle, -
Ugy, mint a kő, mely várromokról dől le,
Vagy mint a koporsónak födele,
Ha a halottat szögezik bele.

Koporsó vagy, koporsó vagy te keblem,
Amelybe szívem élve eltemettem.
Oh szív, te élő eltemettetett!
Ki írhatná le gyötrelmeidet?

Megszűnt a vész, a hold is fönn az égen.
Már béke és fény lebeg a vidéken.
Hazamehetek hát s lefekhetem.
Mert béke és fény nem való nekem.','Vad téli éj. Sürű hópelyhek esnek.
Szélvész ragadja. S hátha nem hópelyhek?
Talán egy őrült gondolatjai?
Vagy összetépett lelkem rongyai.','Szalkszentmárton, 1845. november 25. - december 31. között',1845,'1845',array['Természet','Elmúlás']::text[],array['tel']::text[],false,402,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-01','petofi','Isten csodája','Ameddig a történet csillaga
Röpíti a multakba sugarát:
A szem saját kezünkben mindenütt
Saját szivünkre célzó gyilkot lát,
S ez öngyilkos kéz hányszor szálla ránk!...
Isten csodája, hogy még áll hazánk.

Igy hordozunk sok százados sebet,
Keblünk soha be nem gyógyúlhatott;
Mérget kellett mindenkor innia,
Ki sebeinkre önte balzsamot.
Valami rosz szellemtől származánk!
Isten csodája, hogy még áll hazánk.

S míg egymást martuk szennyes koncokért,
Mint a szeméten a silány ebek,
Azt vettük észre csak, hogy ezalatt
Az oroszlánok itt termettenek;
Jött a tatár, jött a török reánk.
Isten csodája, hogy még áll hazánk.

Ott foly Sajó... oly görbén kanyarog,
Mint ember, aki görcsben haldokol;
Ott haldokoltunk, vérünk ott szivá
Az óriási nadály, a mogol,
S holttesteinket fölfalá a láng!
Isten csodája, hogy még áll hazánk.

S ott van Mohács... ott nyomta a királyt
Sárkoporsóba páncéla s lova,
S készűlt számunkra a ledőlt király
Kardjából a rettentő zabola,
Melytől még most is ég és vérzik szánk!...
isten csodája, hogy még áll hazánk.

Mi lesz belőlünk?... ezt én kérdezem,
De mily kevesen gondolnak vele.
Oh nemzetem, magyar nép! éltedet
Mindig csak a jó sorsra bízod-e?
Ne csak istenben bízzunk, mint bizánk;
Emberségünkből álljon fönn hazánk!','Ameddig a történet csillaga
Röpíti a multakba sugarát:
A szem saját kezünkben mindenütt
Saját szivünkre célzó gyilkot lát,','Szalkszentmárton, 1846. január',1846,'1846',array['Haza']::text[],'{}'::text[],false,403,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-02','petofi','Az őrült','- - - - Mit háborgattok?
Takarodjatok innen!
Nagy munkába'' vagyok. Sietek.
Ostort fonok, lángostort, napsugarakból;
Megkorbácsolom a világot!
Jajgatnak majd és én kacagok,
Mint ők kacagtak, amikor én jajgattam.
Hahaha!
Mert ilyen az élet. Jajgatunk s kacagunk.
De a halál azt mondja: csitt!
Egyszer már én is meghalék.
Mérget töltöttek azok vizembe,
Akik megitták boromat.
S mit tettek gyilkosaim,
Hogy gaztettöket elleplezzék?
Midőn kiterítve feküdtem:
Reám borúltak s könnyezének.
Szerettem volna fölugrani,
Hogy orraikat leharapjam.
De nem harapom le! gondolám,
Legyen orrok és szagolják,
Ha rothadok, s fúladjanak meg.
Hahaha!
És hol temettek el? Afrikában.
Az volt szerencsém,
Mert egy hiéna kiása siromból.
Ez az állat volt egyetlen jóltevőm.
Ezt is megcsaltam.
Ő combom akarta megenni:
Én szívemet adtam oda,
S ez oly keserű volt, hogy megdöglött tőle.
Hahaha!
De hiába, csak így jár,
Ki emberrel tesz jót. Mi az ember?
Mondják: virágnak gyökere,
Amely fönn a mennyben virúl.
De ez nem igaz.
Virág az ember, melynek gyökere
Ott lenn van a pokolban.
Egy bölcs tanított engemet erre,
Ki nagy bolond volt, mert éhenhala.
Mért nem lopott? mért nem rabolt?
Hahaha!
De mit kacagok, mint a bolond?
Hisz sírnom kellene.
Siratni, hogy oly gonosz a világ.
Az isten is felhőszemével
Gyakran siratja, hogy megalkotá.
De mit használ az ég könyűje is?
A földre hull, a ronda földre,
Hol az emberek lábbal tiporják,
S mi lesz belőle,
Az ég könnyéből?... sár.
Hahaha!
Oh ég, oh ég, te vén kiszolgált katona,
Érdempénz melleden a nap,
S ruhád, rongyos ruhád a felhő.
Hm, így eresztik el a vén katonát,
A hosszu szolgálat jutalma
Egy érdempénz és rongyos öltözet.
Hahaha!
S tudjátok-e mit tesz az emberi nyelven,
Midőn a fűrj azt mondja: pitypalatty?
Az azt teszi, hogy kerüld az asszonyt!
Az asszony vonzza magához a férfiakat,
Mint a folyókat a tenger;
Miért? hogy elnyelhesse.
Szép állat az asszonyi állat,
Szép és veszedelmes;
Arany pohárban méregital.
Én ittalak, oh szerelem!
Egy harmatcseppnyi belőled édesebb,
Mint egy mézzé vált tenger;
De egy harmatcseppnyi belőled gyilkosabb,
Mint egy méreggé vált tenger.
Láttátok-e már a tengert,
Midőn a fergeteg szánt rajta
És vet beléje halálmagot?
Láttátok a fergeteget,
E barna parasztot,
Kezében villámösztökével?
Hahaha!
Ha megérik a gyümölcs: lehull fájáról.
Érett gyümölcs vagy, föld, lehullanod kell.
Még várok holnapig;
Ha holnap sem lesz a végitélet:
Beások a föld közepéig,
Lőport viszek le
És a világot a
Levegőbe röpítem... hahaha!','- - - - Mit háborgattok?
Takarodjatok innen!
Nagy munkába'' vagyok. Sietek.
Ostort fonok, lángostort, napsugarakból;','Szalkszentmárton, 1846. január',1846,'1846',array['Természet','Elmúlás']::text[],'{}'::text[],false,404,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-03','petofi','A szökevények','Shelley után angolból

1

A jégeső szakad,
Fehérek a habok,
A tajték táncol, és
A villámlás ragyog -
El, el!

A mennydörgés ropog,
A forgószél kereng,
Harangok zugnak és
Az erdők rengenek -
El, el!

Mint tenger, mozg a föld,
Rajt minden rombadől,
Ember, állat, madár
Elbújt a vész elől -
El, el!

2

"Egy vitorlánk van... a
Kormányos halovány;
Ki merne szállani
Most csónakunk után?"
Az ifju szólt.

A lány felelt: "Evezz,
Taszítsd a csónakot!"
S jégzápor és golyók
Borítják útjokat
A tengeren.

A kék őrtűz lobog;
Némán villámlanak
Az elsűlt fegyverek;
Elnyelte hangjokat
A fergeteg.

3

"És látsz-e? s hallasz-e?
S nem retteg-e szived?
S nem szállunk szabadon
A vad tenger felett
Én és te?"

Egy tengerészköpeny
Fölöttök a fedél;
Együtt ver kebelök,
És suttognak kevély
Örömben.

Mozgó hegyekbül áll
A vészes óceán,
Kelnek s enyésznek a
Habok egymásután
Köröskörül.

4

A várudvarban, a
Kapusnéhoz közel,
Áll, mint megvert kutya,
És szégyen marja fel,
A vőlegényt.

Rémes kisértetként
A zsarnok őszapa
Áll a toronytetőn...
Hangjához képest a
Vihar szelíd;

S hallatlan átkokban
Kívánja a halált
Lyányának, ki legjobb
És legszebb s a család
Végtagja volt.','Shelley után angolból
1
A jégeső szakad,
Fehérek a habok,','Szalkszentmárton, 1846. január',1846,'1846',array['Természet']::text[],'{}'::text[],false,405,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-04','petofi','Távozol hát ifjuságom?','Távozol hát ifjuságom?
Oh bízvást távozhatol,
Nem siratlak. Búcsúm tőled:
Keserű, hideg mosoly.

Nem valánk mi jóbarátok.
Úr voltál te, én kutyád;
Korbácsoltál, uszítottál
Egyre tüskén-bokron át.

Néha dobtál irgalomból
Száraz csontokat nekem;
S akkor büszkébb voltam, semhogy
Alamizsnád elvegyem.

Távozzál hát, ifjuságom,
S halld hozzád végszavamat:
Vidd magaddal emléked, vagy
Vidd magaddal átkomat!','Távozol hát ifjuságom?
Oh bízvást távozhatol,
Nem siratlak. Búcsúm tőled:
Keserű, hideg mosoly.','Szalkszentmárton, 1846. január',1846,'1846',array['Természet']::text[],'{}'::text[],false,406,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-05','petofi','Tündérálom','Sajkás vagyok vad, hullámos folyón.
Hullámzik a viz, reng a könnyü sajka,
Reng, mint a bölcső, melyet ráncigál
Szilaj kezekkel a haragvó dajka.
Sors, életemnek haragos dajkája,
Te vagy, ki sajkám ugy hányod-veted,
Ki rám zavartad fergeteg módjára
A csendriasztó szenvedélyeket.

Elfáradtam már, messze még a part?
Mely béfogad révébe;... vagy az örvény?
Mely nyúgodalmat szintugy ad, midőn
Mélyébe ránt, a sajkát összetörvén.
Sem part, sem örvény nincsen még előttem,
Csak hánykódás, csak örökös habok;
Hánykódom egyre a folyó nagy árján...
Ki sem köthetek, meg sem halhatok.

De mily hang ez, mily tulvilági hang,
Mely bévegyűl a habzúgás közé?
Tán szellem, égbe szálló a pokolból,
Hol büntetését már átszenvedé?...
Egy hattyu száll fölöttem magasan,
Az zengi ezt az édes éneket -
Oh lassan szállj és hosszan énekelj,
Haldokló hattyúm, szép emlékezet!...

Nem voltam többé gyermek, s nem valék
Még ifju. Ez az élet legszebb éve,
Mint legszebb perc, midőn a hajnalégről
Az éj kárpitja félig van levéve.
Sötétség volt még egyfelől szivemben,
De másfelől már pirosan kelének,
Mint a közelgő nap szemeiből
Kilőtt sugárok, a vágyak s remények.

Amire vágytam, bírni is reméltem,
S amit reméltem, azt el is nyerém;
Talán azért, mert nem sok volt... egyéb sem,
Mint pihenés egy hű barát ölén.
Hű volt barátom, mert hisz ilyenkor még
Nincsen kikelve a rejtett önérdek,
E mindent elrágó hernyója a
Baráti hűség virágos kertének.

Barátom hű volt; ürítgettem véle
A boldog órák édes poharát,
S a lelkesűlés égi mámorában
Sasként röpültem a világon át.
S amerre szálltam, minden az enyém volt!
A dúsgazdagság bársony pamlagára
Hajtám le főmet, melyet övezett
A dicsőségnek csillagkoronája.

Ily nagyszerűnek álmodám jövőmet,
S már hittem is, hogy ez való, nem álom...
De most egyszerre szívem, melyet a
Világgal tölték meg, tágulni látom:
Szivem tágúla, vagy tán a világ
Kisebbedett? azt nem tudom, de érzém,
Hogy kebelemben hézag támadott,
Hézag, keblemnek legmelegebb részén.

És napról-napra nőttön-nőtt ez ür,
S ez ür miatt nem szállhatott már lelkem,
Félt, hogy mélyébe hull... s nem kelle többé.
Mit eddig olyan lángolón öleltem,
Nem kellett kincs és nem kellett dicsőség.
Mind a kettő oly fénytelen vala!
Oly fénytelen, mint lesz az ég idővel,
Ha elkopik majd csillagfátyola.

Nem kelle semmi, még a jóbarát sem,
Magam magamnak voltam terhire,
S futottam, mint kit rémek serge üldöz,
Az életzajtól messzi-messzire.
Csöndes magányban keresék tanyát,
Sötét erdő völgyébe telepedtem...
Oh e magányban milyen alakok
Lengtek körűlem s szálltak el fölöttem!

Szivembül jöttek e tündéri lények,
Szivemnek nem rég támadt üregébül,
Tündéri lények, milyenekre félig
Emlékezém a szép gyermekregékbül.
"Megálljatok! megálljatok!" kiálték,
"Oh, csak egy álljon meg közűletek,
Csak addig, mig egy csók s egy ölelés tart!"
Nem álltanak meg, mind eltüntenek.

Kerestem őket, és meg nem lelém,
Még csak nyomukra sem akadhaték;
Nyom nélkül jártak, oly könnyűk valának,
Könnyebbek, mint a szellő, mint a lég.
S minél messzebbre távozának tőlem,
Minél homályosabban láttam őket:
Annál dicsőbbek voltak, és szivem
Annál emésztőbb sovárgásban égett.

Szivem sovárgott és én sorvadék,
Társim nevettek a sápadt fiún,
Csak jóbarátom, ő nem nevetett,
Fejét csóválta, búsan, szomorún.
Mi lelt? kérdezte; én nem felelék,
Mert hisz magam sem tudtam, hogy mi lelt.
Szomjas valék s vizet hiába ittam,
Nem enyhité viz a tikkadt kebelt.

S meguntam ezt a földi életet,
Mely elvesztette szépségét szememben.
Föl, föl! mondám, a mennybe! ahová
Fájó szivemnek tündérnépe lebben;
Föl a mennyekbe! ha a léget szívom,
Mit ők színak: tán majd e szomj nem éget...
S ha ott is futnak tőlem? ah, utánok
Keresztülbolygom a nagy mindenséget! -

Fényes tavasz volt. A mezőn szivárvány,
Égő szivárvány százezer virágbul;
De rám oly búsan néztenek... talán
Tudták, hogy elkészűlök a világbul.
A legnagyobb hegy tetejére mentem,
Onnan tekinték föl az ég felé.
Átlátszó kék volt a felhőtlen ég...
Beléláttam... tisztán láttam belé...

Ábránd-alakjaim legszebbike
Ott volt az égben. Ajka mozgott; szinte
Hallottam hívó hangjait... de jól
Láthattam, hogy felém kezével inte.
Megyek! mondám, s a bérc szélére léptem,
Ahol száz ölnyi mélység nyilt alattam.
Már-már ugrám... hátúl egy kéz ragadt meg...
Eszmélet nélkül visszahanyatlottam.

Midőn eszméltem: a dicső alak,
Kit az egekben láttam az imént,
Ott állt mellettem... oh, mit érezék?
Leirhatatlan édes érzeményt!
"Ilyen közel van hát a föld az éghez?"
Zavart elmémmel ekkép gondolkodtam,
"Im a mennyben vagyok szép angyalomnál,
S elébb egy perccel még a földön voltam."

Ezt gondolám, de szólni nem tudék,
Avvagy talán nem mertem szólani,
Félvén, hogy majd ha ajkam megnyitom,
Keblemből a menny ki fog szállani,
És megragadtam angyalom kezét,
Hogy el ne tűnjék tőlem újolag,
És derekát átövezé karom,
Átövezé, mint egy égő szalag.

S merőn szemléltem fényes arculatját.
Most is csodálom, hogy szemem világa
El nem veszett e földöntúli fénytől,
Midőn benéztem szeme csillagába.
Sötétkék csillag volt az ő szeme,
És szemöldöke fekete szivárvány,
S vállán ugy úsztak barna fürtei,
Miként az éj egy rózsatenger árján.

Meg mertem végre nyitni ajkamat,
S beszéltem üdvről, angyalokrul, égről.
Nagyon homályosan beszélheték,
Mert ő nem értett semmit e beszédből.
"Én lyány vagyok," szólt, "földi lyány, nem angyal;
Ahol vagyunk, ez a föld, nem az ég,
S te itt a mélybe estél volna, ámde
Én mentésedre még jókor jövék."

"Legyünk tehát a földön," válaszoltam,
"Földön vagy égen, az mindegy nekem,
Csak oldaladnál, kedves oldaladnál;
Hisz ahol te vagy, ott az én egem.
De űlj le mellém, s engedd, hogy karom
Szorosabban fűzhessen át, o engedd!
Úgyis sajátom vagy, tulajdonom,
Mert téged az én képzetem teremtett."

Leültünk ott a szikla tetején
S beszélgeténk. Kérdezte: ki vagyok?
"Egy bús sohajtás voltam eddig," szólék,
"Öledben ím e csókkal meghalok.
Most csókolj vissza, lyányka, hogy legyen
Föltámadásom... - ím, föltámadok,
Mert csókod ért; s ki bú-sohaj valék,
Most a gyönyörnek mosolya vagyok."

Ő megcsókolt. Nem kéreté magát,
Első szavamra ajkamon volt ajka;
E csók! ez ajk!... mért nem váltunk itt kővé?
Hadd függtem volna mindörökre rajta!
E csók, e csók! ez édesb volt a méznél
S az anyatejnél. Csak ezóta élek;
Midőn elcsattant e csók ajkamon,
Érzém, hogy ekkor szállt belém a lélek.

"Tekints körül", szólott a csók után
A lyányka, "látod, milyen változás?
Én nem tudom, honnan, s miként van ez,
De mostan ég és föld egészen más.
Kékebb az ég, sugárosabb a nap,
S e fák alatt itt hűvösebb az árnyék,
S pirosb a rózsa, illatosb a lég...
Ah, mintha csak egy más világban járnék!"

"Más a világ, más, nem olyan, minő volt,"
Feleltem én, "vagy csak mi változánk?
De bármiként van, mit törődünk véle,
Midőn e változás áldás reánk!"
Egymás ölébe így fontuk tovább
Beszélgetésünk rózsakötelét,
S amint eszméltünk szép ábrándjainkból,
Láttuk, hogy a nap már a földre lép.

Alkonyodék. Arany felhőkön szállott
A nap violaszín hegyek mögé.
A messzeségbe nyúló rónaságot,
E száraz tengert, halvány köd födé.
A szikla, melyen állottunk, piroslott
A végsugártól, miként bíbor párna
A trónon. De hisz trón volt ez; mi rajta
A boldogság ifjú királyi párja.

Elbúcsuzánk; nem szóval; szemeinkkel;
S nem szomorúan, oh nem, oly vidáman!
Az éjt úgy néztük, mint a haldokló
A sirt, amelyen túl egy szebb világ van.
Nem ígértük, hogy holnap eljövünk,
De mind a ketten eljövénk hiven,
S így éltük által az egész tavaszt,
Ajk ajakon, kéz kézben, szív sziven.

S így éltük által az egész nyarat.
Minden napunk egy virágszál vala
A bokrétából, melytül illatot nyer
Az istenek olympi asztala.
De e virágok elhervadtanak már;
Mit ér, szemlélnem száraz kelyhöket?
Röpűlj ki e szép kornak édenéből,
Haldokló hattyúm, bús emlékezet!

Eljött az ősz, ez a vad zsarnoka
A természetnek. Kérlelhetlen karja
Letépi a szegény fák levelét,
A földre sujtja, és lábbal tiporja.
Lábbal tiprá boldogságunkat is;
Reánk küldé enyészetes szelét
Elválás képiben, s ez arcainknak
Leszaggatá szép rózsalevelét.

Elváltunk, hogy ne lássuk egymást többé.
Komoly borongó volt az őszi este;
A ködön át a távolból lyánykámat
Könnyes szemem mégegyszer fölkereste,
Aztán futottam, útat nem tekintve,
Arcom, kezem tövistől vérezék...
Futottam árván, mint a hullócsillag,
Melyet magából kilökött az ég. - -

Azóta arcom és kezem begyógyult,
Arcom s kezem, mit tüske sérte meg,
S szivemből is ki vannak irtva már
Az elválástól támadott sebek;
De e sebeknél jobban fáj nekem most,
Jobban fáj az, hogy már-már feledem
Ábrándjaidnak édes üdvességét,
Oh tündérálom, első szerelem!','Sajkás vagyok vad, hullámos folyón.
Hullámzik a viz, reng a könnyü sajka,
Reng, mint a bölcső, melyet ráncigál
Szilaj kezekkel a haragvó dajka.','Szalkszentmárton, 1846. február 20.',1846,'1846',array['Természet','Szerelem','Elmúlás']::text[],array['osz']::text[],false,407,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-06','petofi','Vajda Péter halálára','Oh természet, midőn alunni mentél,
Alunni a múlt ősznek végivel:
Elbúcsuzál-e kedves gyermekedtől,
Elbúcsuzál-e leghivebb fiadtól,
Őtőle?... és ha elbucsúztatok:
Gondoltad-e, hogy végbucsútok ez? -
Alszod, természet, téli álmadat...
Alszol... vajon megálmodád-e már,
Megálmodád-e azt a bánatot,
Mely ébredésed reggelén megüt?
Föl fogsz ébredni, fölkelt a tavasz,
S a csalogány mond legszebb éneket
Föltámadásod hangos ünnepén;
Pedig volt egykor, aki érkezésed
A csalogánynál szebben üdvezelte.
Te széttekintesz, s kérdeni fogod:
Hol van legelső dalnokom? hol ő?...
Egy sírhalom lesz rá a felelet.
Oh, természet, viseld gondját e sírnak,
Melynek lakója leghivebb fiad,
Viseld gondját... ültesd áldás gyanánt
Virágaid legszebbjeit reá;
Ugysincs e honnak, nincs hálás keze,
Hogy megtegye, ha elmulasztanád.
Oh e hazában olyan sok jeles
Sírján ingatja vándor fuvalom
A feledésnek tüskebokrait! -
Vagy modd, hazám, hogy multad illeti,
Csak multadat s nem a jelent, e vád;
Mondd, hogy szivedben lesz egy kis helye
Maradni-méltó emlékezetének.
Vagy nem méltó-e rá, hogy a haza
Szivében hordja annak emlékét,
Ki a hazát szivében hordozá?...
Emlékezést, emlékezést neki!
S ha sírhalmához mentek: ejtsetek
Reá egy könnyet, mert megérdemel
Egy könnyet az, ki annyit szárított föl
Meleg lelkének hő sugárival! - -
És míg ti benne dalnokot sirattok:
Az én könyűim hadd omoljanak
A függetlenség bajnok férfiáért,
Ki e hajlongó, görnyedő időkben
Meg nem tanúla térdet hajtani,
Ki sokkal inkább hajtá le fejét a
Szabad szegénység kőszikláira,
Semmint a függés bársony pamlagára. - -
Sirassa benned, elhunyt férfiú,
A természet leghívebb gyermekét,
Sirassa benned dalnokát a hon...
Legkeserűbb az én könyűm, ki benned
A függetlenség hősét siratom!','Oh természet, midőn alunni mentél,
Alunni a múlt ősznek végivel:
Elbúcsuzál-e kedves gyermekedtől,
Elbúcsuzál-e leghivebb fiadtól,','Pest, 1846. február 10. után',1846,'1846',array['Haza','Természet','Elmúlás']::text[],'{}'::text[],false,408,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-07','petofi','Elvándorol a madár...','Elvándorol a madár,
Ha őszre jár
Az idő.
(Tavasszal azonban ismét visszajő.)
Száll... száll... száll... viszi szárnya;
Azon veszed észre magad, hogy már a
Távolság kék levegőit issza.
Olyan sebesen száll,
Hogy eltünő álomnak véled. -
A madárnál
Mi száll tova még sebesebben?... az élet!
De, mint a madár, ez nem tér többé vissza.','Elvándorol a madár,
Ha őszre jár
Az idő.
(Tavasszal azonban ismét visszajő.)','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,409,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-08','petofi','Nem sírok én...','Nem sírok én és nem panaszkodom;
Nem mondom én el másnak: mi bajom?
De nézzetek szinetlen arcaimra,
Ott föl van írva;
És nézzetek szemembe, mely kiégett,
S belőle kiolvashatjátok,
Hogy rajtam átok fekszik, átok,
Hogy fáj nekem, hogy nagyon fáj az élet!','Nem sírok én és nem panaszkodom;
Nem mondom én el másnak: mi bajom?
De nézzetek szinetlen arcaimra,
Ott föl van írva;','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,410,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-09','petofi','Szeretném itthagyni...','Szeretném itthagyni a fényes világot,
Amelyen oly sok sötét foltot látok.
Szeretnék rengetegbe menni,
Ahol nem lenne senki, senki!
Ott hallgatnám a lombok suttogását,
Ott hallgatnám a patakok zugását
És a madárnak énekét,
S nézném a felhők vándorseregét,
Nézném a nap jöttét s lementét...
Mig végre magam is lemennék.','Szeretném itthagyni a fényes világot,
Amelyen oly sok sötét foltot látok.
Szeretnék rengetegbe menni,
Ahol nem lenne senki, senki!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,411,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-10','petofi','Annyit sem ér az élet...','Annyit sem ér az élet,
Mint egy eltört fazék, mit a konyhából
Kidobtak, s melynek oldaláról
Vén koldús nyalja a rászáradt ételt!','Annyit sem ér az élet,
Mint egy eltört fazék, mit a konyhából
Kidobtak, s melynek oldaláról
Vén koldús nyalja a rászáradt ételt!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,412,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-11','petofi','Mögöttem a múlt...','Mögöttem a múlt szép kék erdősége,
Előttem a jövő szép zöld vetése;
Az mindig messze, és mégsem hagy el,
Ezt el nem érem, bár mindig közel.
Ekkép vándorlok az országuton,
Mely puszta, vadon,
Vándorlok csüggedetten
Az örökkétartó jelenben.','Mögöttem a múlt szép kék erdősége,
Előttem a jövő szép zöld vetése;
Az mindig messze, és mégsem hagy el,
Ezt el nem érem, bár mindig közel.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,413,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-12','petofi','Voltak barátim...','Voltak barátim, jó embereim...
Oh mért meg nem halának!
Sírhalmaikra mostan könnyeim
Folynának,
S virágokat termesztene
Fölöttök könnyeim özöne. -
Meg fognak halni majd,
De egyik régi barát
Sem nyer tőlem könyűket, csak sohajt,
Csalódás kínos sohaját;
S ha ez leng rájok:
Sírhalmukon elszáradnak a virágok.','Voltak barátim, jó embereim...
Oh mért meg nem halának!
Sírhalmaikra mostan könnyeim
Folynának,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,414,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-13','petofi','Szállnak reményink...','Szállnak reményink, e szép madarak...
Midőn legjobban szállanak,
S szíják a mennyei tiszta léget,
Hol már sas sem tanyáz;
Jön a való, e zord vadász,
S lelövöldözi őket.','Szállnak reményink, e szép madarak...
Midőn legjobban szállanak,
S szíják a mennyei tiszta léget,
Hol már sas sem tanyáz;','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,415,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-14','petofi','Elváltam a lyánykától','Elváltam a lyánykától,
Ki kedvesem vala;
Ugy fájt leszakadnom ajakáról,
Mely csókola. -
Rég volt ez; azóta már
Sok esztendő lejárt.
Az elválás keserüségét
Többé nem érezem,
De a csók édességét
Még most is érezem.','Elváltam a lyánykától,
Ki kedvesem vala;
Ugy fájt leszakadnom ajakáról,
Mely csókola. -','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,416,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-15','petofi','Emlékezet...','Emlékezet!
Te összetört hajónk egy deszkaszála,
Mit a hullám s a szél viszálya
A tengerpartra vet... - -','Emlékezet!
Te összetört hajónk egy deszkaszála,
Mit a hullám s a szél viszálya
A tengerpartra vet... - -','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,417,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-16','petofi','Amott a távol kék ködében...','Amott a távol kék ködében
Emelkedik egy falu tornya sötéten;
Van egy fehér ház e faluban,
Hol egy fekete szemü lyányka van.
E lyányka, e lyányka,
E fekete szem,
Ez bánatom és örömem
Százszínű szivárványa.','Amott a távol kék ködében
Emelkedik egy falu tornya sötéten;
Van egy fehér ház e faluban,
Hol egy fekete szemü lyányka van.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,418,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-17','petofi','Viseld egyformán...','"Viseld egyformán jó- s balsorsodat!"
Igy szól, kit a bolond világ bölcsnek nevez.
Az én jelszóm nem ez;
Én örömimet és fájdalmimat
Érezni akarom... kettősen érezem.
Lelkem nem a folyó leszen,
Amely egykedvüleg
Ragadja magával a rózsalevelet,
Melyet tavasszal szép lyány vet bele,
S a száraz fűveket,
Miket
Árjára sodort az ősz szele.','"Viseld egyformán jó- s balsorsodat!"
Igy szól, kit a bolond világ bölcsnek nevez.
Az én jelszóm nem ez;
Én örömimet és fájdalmimat','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,419,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-18','petofi','Mi szebb, mint...','Mi szebb, mint a szép gyermeklyány orcája?
Ki azt álmodja, hogy ifját öleli,
Az ifjút, akivel ébren nem meri
Sejtetni sem, hogy őt imádja!','Mi szebb, mint a szép gyermeklyány orcája?
Ki azt álmodja, hogy ifját öleli,
Az ifjút, akivel ébren nem meri
Sejtetni sem, hogy őt imádja!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,420,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-19','petofi','Mely''k a legvígabb temető?','Mely''k a legvígabb temető?
A bú temetője!... "S ez hol lelhető?"
Azt kérditek, úgyebár? -
A bú temetője a boros-asztal,
Közepén a kereszttel, a nagy palackkal,
E mellett sírhalom minden pohár. -
Járjunk e víg temetőbe
Ily szomorú időbe''!','Mely''k a legvígabb temető?
A bú temetője!... "S ez hol lelhető?"
Azt kérditek, úgyebár? -
A bú temetője a boros-asztal,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,421,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-20','petofi','Hajamnak egy fürtjét levágom...','Hajamnak egy fürtjét levágom,
Melynek most minden szála szög;
S ha majd elmúlik ifjuságom,
Ha majd megőszülök:
A falra függesztem tükör helyett
E barna fürtöt: így csalom meg szememet,
Hitetve, hogy még fiatal vagyok...
De vajon nem árul-e el
A szív ütése, mely
Majd mindig halkabban dobog?','Hajamnak egy fürtjét levágom,
Melynek most minden szála szög;
S ha majd elmúlik ifjuságom,
Ha majd megőszülök:','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,422,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184601-21','petofi','Mintha a nagy, nehéz...','Mintha a nagy, nehéz világot tartanám,
Leányka, hogy az ne szakadjon rám,
Ugy reszketek,
Ha megfogom könnyű, kis kezedet.','Mintha a nagy, nehéz világot tartanám,
Leányka, hogy az ne szakadjon rám,
Ugy reszketek,
Ha megfogom könnyű, kis kezedet.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,423,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-22','petofi','Itt állok a rónaközépen...','Itt állok a rónaközépen,
Mint a szobor, merően.
A pusztát síri csend födé el,
Mint elfödik a halottat szemfödéllel.
Nagymessze tőlem egy ember kaszál;
Mostan megáll,
S köszörűli a kaszát...
Pengése hozzám nem hallatszik át,
Csak azt látom: mint mozog a kéz.
És most idenéz,
Engem bámul, de én szemem sem mozditom...
Mit gondolhat, hogy én miről gondolkodom?','Itt állok a rónaközépen,
Mint a szobor, merően.
A pusztát síri csend födé el,
Mint elfödik a halottat szemfödéllel.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,424,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-23','petofi','Oh lyány! Szemed...','Oh lyány! szemed
Milyen sötét,
S mégis ragyog;
Kivált midőn
Reám tekintesz,
Ugy tündököl,
Mint zordon éjben
Villám tüzénél
A hóhérpallos!','Oh lyány! szemed
Milyen sötét,
S mégis ragyog;
Kivált midőn','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,425,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-24','petofi','Ha jőne oly nagy fergeteg...','Ha jőne oly nagy fergeteg,
Mely meghasítná az eget,
És e hasitékon át
A földgolyót behajítaná!','Ha jőne oly nagy fergeteg,
Mely meghasítná az eget,
És e hasitékon át
A földgolyót behajítaná!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,426,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-25','petofi','Egy bölcs hajdan...','Egy bölcs hajdan szamáron útazott. -
Azóta az idő megváltozott,
Nagyon megváltozott már,
Most a szamarak
Lovaglanak,
A bölcs pedig gyalog jár.','Egy bölcs hajdan szamáron útazott. -
Azóta az idő megváltozott,
Nagyon megváltozott már,
Most a szamarak','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,427,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-26','petofi','Mi a dicsőség?...','Mi a dicsőség?... tündöklő szivárvány,
A napnak könnyekben megtört sugára.','Mi a dicsőség?... tündöklő szivárvány,
A napnak könnyekben megtört sugára.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,428,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-27','petofi','Sok embert ismerek...','Sok embert ismerek,
Ki önmagát legjobban szereti;
De másnak ismét vannak kedvesi,
Kiket magánál forróbban szeret,
S ezeket sokszor mégis megbántja.
Aztán megbánja,
Hogy könnyeket facsart szeméből,
Kinek egy vidám pillantatáért,
Kinek egy mosolyáért
A legszebb részt od''adná életéből.
Ilyenkor tudja csak: mi a gyötrelem?
Mik a keservek?
És kéri szivét: repedj meg, oh szivem!
És ez - büntetésül - nem reped meg.','Sok embert ismerek,
Ki önmagát legjobban szereti;
De másnak ismét vannak kedvesi,
Kiket magánál forróbban szeret,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,429,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-28','petofi','A bánat? Egy nagy óceán','A bánat? egy nagy óceán.
S az öröm?
Az óceán kis gyöngye. Talán,
Mire fölhozom, össze is töröm.','A bánat? egy nagy óceán.
S az öröm?
Az óceán kis gyöngye. Talán,
Mire fölhozom, össze is töröm.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,430,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-29','petofi','Dacos leány!','Dacos leány!
Hagyd megcsókolni magad,
Hagyd átölelnem derekad.
Nap megy nap után,
S ha napjaid elhaladnak,
Maradsz magadnak.
Száraz derekad
Majd senki meg nem öleli,
Csak a koporsónak deszkája,
S halvány ajakad
Más nem csókolja, csak a sír férgei...
Gondolj reája. -
Mit érzesz,
Nem rendül meg szived?
Nem érezed,
Hogy ez hideg csók, hideg ölelés lesz!','Dacos leány!
Hagyd megcsókolni magad,
Hagyd átölelnem derekad.
Nap megy nap után,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,431,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-30','petofi','Gyertyám homályosan lobog...','Gyertyám homályosan lobog...
Magam vagyok...
Sétálok föl s alá szobámban...
Szájamban füstölő pipám van...
Multam jelenési lengenek körűlem...
Sétálok, sétálok, s szemlélem
A füst árnyékát a falon,
És a barátságról gondolkodom.','Gyertyám homályosan lobog...
Magam vagyok...
Sétálok föl s alá szobámban...
Szájamban füstölő pipám van...','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,432,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-31','petofi','Mondják, hogy mindenikünk...','Mondják, hogy mindenikünk bir egy csillaggal,
S az, akié lehull az égrül, meghal.
És így fogy az ember, így fogy a csillag;
Mindegyre omolnak...
A csillag az égrül a földre,
Az ember a földrül a sírgödörbe.
Hah, majd ha miljom s miljom év lemégyen,
S a földön és az égen
Csak egy ember s egy csillag bujdosik!...
S ha végre ez is leesik!... - -','Mondják, hogy mindenikünk bir egy csillaggal,
S az, akié lehull az égrül, meghal.
És így fogy az ember, így fogy a csillag;
Mindegyre omolnak...','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,433,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-32','petofi','Az ember ugyan hova lesz?...','Az ember ugyan hova lesz?...
Sokrates,
Ki a mérget megitta,
S hóhéra, ki a mérget neki adta,
Egy helyre mentek mind a ketten?
Oh lehetetlen!
És hátha... hátha...
Mért nem láthatni a másvilágba!','Az ember ugyan hova lesz?...
Sokrates,
Ki a mérget megitta,
S hóhéra, ki a mérget neki adta,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,434,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-33','petofi','Elmém ezen sokat gondolkodik...','Elmém ezen sokat gondolkodik:
Ha valaha
A világrendszer fölbomlana,
S mint most az eső és hó esik,
Esnének akkor csillagok,
S folynának a csillagpatakok!','Elmém ezen sokat gondolkodik:
Ha valaha
A világrendszer fölbomlana,
S mint most az eső és hó esik,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,435,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-34','petofi','Mit ettél, föld...','Mit ettél, föld, hogy egyre szomjazol?
Hogy annyi könnyet s annyi vért iszol?','Mit ettél, föld, hogy egyre szomjazol?
Hogy annyi könnyet s annyi vért iszol?','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,436,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-35','petofi','Mosolygjatok rám...','Mosolygjatok rám, oh mosolygjatok,
Ti szép leánykák szemei!
S én el fogom felejteni,
Hogy már olyan sokszor megcsaltatok. -
Véljük, hogy a lyányok szíve az ég,
Mert mélyei, mint ez, úgy ragyognak.
A lyányi szív csalárd folyó csak,
Amelybe sugáraikat veték
Az égi csillagok...
Ki ott mennyet keres, elnyelik a habok.','Mosolygjatok rám, oh mosolygjatok,
Ti szép leánykák szemei!
S én el fogom felejteni,
Hogy már olyan sokszor megcsaltatok. -','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem','Természet']::text[],'{}'::text[],false,437,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-36','petofi','Ha a sírban megszáradt...','Ha a sírban megszáradt szíveket
Mind egy halomra hordanák
S meggyújtanák,
Ki mondja meg:
Hány színű lenne majd e láng?','Ha a sírban megszáradt szíveket
Mind egy halomra hordanák
S meggyújtanák,
Ki mondja meg:','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,438,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-37','petofi','Hová lesz a kacaj...','Hová lesz a kacaj,
Hová lesz a sohaj,
Ha hangja elenyész?
S hová lesz az ész,
Midőn már nem gondolkodik?
S a szeretet,
S a gyűlölet,
Ha a szívből kiköltözik?','Hová lesz a kacaj,
Hová lesz a sohaj,
Ha hangja elenyész?
S hová lesz az ész,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,439,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-38','petofi','Te ifjúság...','Te ifjúság, te forgószél!
Ki szép virágfüzért
Sodorsz magaddal... e virágokat
Futtodban homlokunkra keríted...
Egy perc alatt
Ismét leröpíted,
S gyorsan tovább futasz.
Mi búsan álmélkodva állunk,
S kérdezzük: igaz-e, hogy nálunk
Valál? talán nem is igaz!','Te ifjúság, te forgószél!
Ki szép virágfüzért
Sodorsz magaddal... e virágokat
Futtodban homlokunkra keríted...','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,440,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-39','petofi','Barátim vagytok...','Barátim vagytok, azt mondjátok.
Talán nem mondtok hazugságot,
Ez meglehet,
De azért nem adom nektek hitemet,
Nem adhatom: most jó dolgom van,
Jertek hozzám, ha majd napom lejár,
Mert a barátság nappal láthatatlan,
Éjjel ragyog csak, mint a fénybogár.','Barátim vagytok, azt mondjátok.
Talán nem mondtok hazugságot,
Ez meglehet,
De azért nem adom nektek hitemet,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,441,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-40','petofi','Földét a földmives...','Földét a földmives felszántja,
Aztán beboronálja.
Képünket az idő felszántja,
De be nem boronálja.','Földét a földmives felszántja,
Aztán beboronálja.
Képünket az idő felszántja,
De be nem boronálja.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,442,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-41','petofi','Nemcsak mi vénülünk...','Nemcsak mi vénülünk, mi emberek...
Mi volna, ami nem vénülne meg?
Nézzétek a napot, ha jön a december:
Nem valóságos öregember?
Későn ébred, s alig
Hogy fölkapaszkodhatik
Az égre, oly erőtelen;
Mogorván néz a világra s hidegen,
S olyan korán ledől megint ágyára.
Majd végesvégül
Azt is megérjük, hogy megőszül,
És ekkor... ekkor fehér lesz sugára.','Nemcsak mi vénülünk, mi emberek...
Mi volna, ami nem vénülne meg?
Nézzétek a napot, ha jön a december:
Nem valóságos öregember?','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,443,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-42','petofi','Futó folyam hullámai...','Futó folyam hullámai
Az ember miljom vágya;
Perc hozza őket, perc ragadja el.
A sors azért nem szokta teljesíteni,
Azért nem hallgat rája;
Jól tudja: mikorra egy kegyét leejti,
Az ember már régen mást esdekel,
S hogy kérte amazt, el is felejti.','Futó folyam hullámai
Az ember miljom vágya;
Perc hozza őket, perc ragadja el.
A sors azért nem szokta teljesíteni,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,444,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-43','petofi','Hány csepp van az óceánban...','Hány csepp van az óceánban?
Hány csillag az égen?
Az emberiség fejin hány hajszál van?
S hány gonoszság szivében?','Hány csepp van az óceánban?
Hány csillag az égen?
Az emberiség fejin hány hajszál van?
S hány gonoszság szivében?','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,445,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-44','petofi','Nem sűlyed az emberiség...','Nem sűlyed az emberiség!
Ilyen gonosz vala rég,
Ilyen gonosz már kezdet óta...
Hisz különben nem kellett vóna
Százféle mesét,
Eget, isteneket,
Pokolt és ördögöket
Gondolni ki, hogy zaboláztassék.','Nem sűlyed az emberiség!
Ilyen gonosz vala rég,
Ilyen gonosz már kezdet óta...
Hisz különben nem kellett vóna','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,446,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-45','petofi','Kik a föld alacsony porából...','Kik a föld alacsony porából,
Mit minden féreg gázol,
A naphoz emelkedtek,
Ti szárnyas, óriás lelkek!
Hogy van, hogy titeket a törpe világ
Mindig kicsínyeknek kiált?...
Természetes! hiszen a tölgy a bérceken
Kisebbnek tetszik, mint a fűzfa idelenn.','Kik a föld alacsony porából,
Mit minden féreg gázol,
A naphoz emelkedtek,
Ti szárnyas, óriás lelkek!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,447,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-46','petofi','Az én szivem...','Az én szivem egy földalatti lak,
Sötét, sötét!
Az öröm egy-egy fényes sugarat
Csak néha vét
Mélyébe e földalatti háznak.
Ez a fény is csak azért pillant bele,
Hogy lássa a szörnyeket, mik ott tanyáznak,
Mikkel televan, tele!','Az én szivem egy földalatti lak,
Sötét, sötét!
Az öröm egy-egy fényes sugarat
Csak néha vét','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,448,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-47','petofi','Odanézzetek!','Odanézzetek!
Csatára iramlik a fergeteg;
Paripája a szél, a nyargaló,
Kezében a felleg a lobogó,
Amelynek villám a nyele.
Vágtat vele, vágtat vele
Csatára, csatára...
Mint harsog trombitája,
A mennydörgés!

- - - - - - - -

Oh fergeteg,
Ki a tornyokat
Eldöntögeted,
Kinek kezében kiszakad
A tölgy a bérc kebelébül,
Hol századok óta vénül,
Hatalmas fergeteg! ki nem szakíthatod
Az emberi szivbül a bánatot - -','Odanézzetek!
Csatára iramlik a fergeteg;
Paripája a szél, a nyargaló,
Kezében a felleg a lobogó,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Haza']::text[],'{}'::text[],false,449,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-48','petofi','Már sokszor énekeltem...','Már sokszor énekeltem rólatok,
Még többször is éneklek, szép csillagok.
Én úgy szeretlek titeket!
Egy szebb világgal hiteget
Sugárotok;
S ti egyre mosolygotok,
S oly jól esik nekem,
Oda tekintenem,
Hol egy kis vidámság van
E szomorú világban.','Már sokszor énekeltem rólatok,
Még többször is éneklek, szép csillagok.
Én úgy szeretlek titeket!
Egy szebb világgal hiteget','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,450,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-49','petofi','Mivé lesz a föld?...','Mivé lesz a föld?... megfagy-e, elég-e?
És ugy hiszem, hogy meg fog fagyni végre,
Megfagyasztják a jéghideg szivek,
Amelyek benne s bele fekszenek.','Mivé lesz a föld?... megfagy-e, elég-e?
És ugy hiszem, hogy meg fog fagyni végre,
Megfagyasztják a jéghideg szivek,
Amelyek benne s bele fekszenek.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],array['tel']::text[],false,451,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-50','petofi','Fönséges éj!','Fönséges éj!
Az égen tündökölve ballag
A nagy hold s a kis esti csillag.
Fönséges éj!
A harmat csillog a gyep bársonyán,
Bokor sátrában zeng a csalogány.
Fönséges éj!
Az ifjú mostan megy szeretője után...
S most megy gyilkolni a zsivány.
Fönséges éj!','Fönséges éj!
Az égen tündökölve ballag
A nagy hold s a kis esti csillag.
Fönséges éj!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,452,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-51','petofi','Ki fogja vajon megfejteni...','Ki fogja vajon megfejteni
E rejtélyt:
Az emberiségnek könnyei
Lemoshatnák-e az emberiségnek szennyét?','Ki fogja vajon megfejteni
E rejtélyt:
Az emberiségnek könnyei
Lemoshatnák-e az emberiségnek szennyét?','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,453,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-52','petofi','Szép kedvesem...','Szép kedvesem, ha majd az oltár mellett
Dobog felém szerelmes kebled!...
S ha majd körűlünk apró gyermekek
Mosolyganak, enyelgenek!...
S ha majd fölénk a szemfedő borúl,
S kivisznek, s rajtunk a sír domborúl!...
S ha majd hozzánk az unokák kijőnek
Szép alkonyán a sárga, csendes ősznek,
S merengve nézik ákáclombjainkat,
Miket fejfánknál a lég halkan ingat...','Szép kedvesem, ha majd az oltár mellett
Dobog felém szerelmes kebled!...
S ha majd körűlünk apró gyermekek
Mosolyganak, enyelgenek!...','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,454,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-53','petofi','Szeretője-e vajon...','Szeretője-e vajon a testnek a lélek?
S mint szeretőkhöz illik, együtt enyésznek?
Vagy a lélek a testnek csak barátja?
S ugy tesz, mint rendesen a barát:
Elhordja magát,
Midőn amazt pusztulni látja?','Szeretője-e vajon a testnek a lélek?
S mint szeretőkhöz illik, együtt enyésznek?
Vagy a lélek a testnek csak barátja?
S ugy tesz, mint rendesen a barát:','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,455,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-54','petofi','Oh szerelem...','Oh szerelem, te óriási láng!
Ki a világot gyujtod ránk,
Aztán ellobansz... tán egy perc alatt,
S örök sötétség és hideg hamvad marad.','Oh szerelem, te óriási láng!
Ki a világot gyujtod ránk,
Aztán ellobansz... tán egy perc alatt,
S örök sötétség és hideg hamvad marad.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,456,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-55','petofi','Miért hogy láthatatlanok...','Miért hogy láthatatlanok
Az ördögök s az angyalok?
Ismerni szeretném őket
Avégett,
Hogy tudja, amit nem tudok:
Mi van ebben és mi van abban?
S az ember melyikhez hasonlít jobban?','Miért hogy láthatatlanok
Az ördögök s az angyalok?
Ismerni szeretném őket
Avégett,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,457,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-56','petofi','Mulandóság...','Mulandóság a királyok királya.
Ez a világ az ő nagy palotája.
Sétál föl és le benne,
S nincs hely, hová ne menne,
S hová lelép, amire hág,
Minden pusztúl... körűle fekszenek
Szétszórva: eltört koronák,
Hervadt virágok, megrepedt szivek.','Mulandóság a királyok királya.
Ez a világ az ő nagy palotája.
Sétál föl és le benne,
S nincs hely, hová ne menne,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,458,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-57','petofi','A férj hazajő betegen...','A férj hazajő betegen.
Hű nője orvosért
Megy hirtelen.
Miként siet, az istenért!
Az orvostól mindent remél,
Azért rohan érte, mint a szél,
Oly gyorsan azért keresi föl...
Jól tudja: az orvos gyakran öl.','A férj hazajő betegen.
Hű nője orvosért
Megy hirtelen.
Miként siet, az istenért!','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Haza']::text[],'{}'::text[],false,459,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-58','petofi','Barátaim megölelének...','Barátaim megölelének...
Szivökhöz nyomták szívemet;
Bennem mi boldog volt a lélek!...
Később tudám meg: mért öleltenek? -
Azt tapogatták, míg öleltek:
Hol van legfájóbb része e kebelnek?
Hogy gyilkukat majd odadöfjék...
És odadöfték!','Barátaim megölelének...
Szivökhöz nyomták szívemet;
Bennem mi boldog volt a lélek!...
Később tudám meg: mért öleltenek? -','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,460,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-59','petofi','Mint lót-fut a boldogság után...','Mint lót-fut a boldogság után
Az ember, a dőre,
Az egyik hátra, a másik előre,
Mikéntha már ott volna nyomán.
Hiába igyekeznetek!
Előttetek, mögöttetek
Nincs a boldogság... ott alattatok van
A sírhalomban.','Mint lót-fut a boldogság után
Az ember, a dőre,
Az egyik hátra, a másik előre,
Mikéntha már ott volna nyomán.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,461,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-60','petofi','Hideg ellen a tél...','Hideg ellen a tél a folyókat jéggel,
A földet hóval leplezé el.
Csupán némely embernek
Kell öltözetlenűl bujdosnia...
Tehát a természetnek
Az ember a legmostohább fia?','Hideg ellen a tél a folyókat jéggel,
A földet hóval leplezé el.
Csupán némely embernek
Kell öltözetlenűl bujdosnia...','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],array['tel']::text[],false,462,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-61','petofi','Vajon mi ér?','Vajon mi ér? vajon mi történik velem?
Sejtek, s e sejtelem, ez olyan rettentő!
Ugy rángatózik, úgy ugrándozik szivem,
Miként a porban a levágott emberfő.','Vajon mi ér? vajon mi történik velem?
Sejtek, s e sejtelem, ez olyan rettentő!
Ugy rángatózik, úgy ugrándozik szivem,
Miként a porban a levágott emberfő.','Szalkszentmárton, 1846. március 10. előt',1846,'1846','{}'::text[],'{}'::text[],false,463,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-62','petofi','Az özvegy...','Az özvegy gyászba öltözék;
Kedves férjét eltemeték.
Ő gyászruhát ölt a meghalt után! -
Jó asszony, ez egyet föl se vedd,
Vagy végy föl többet... hisz ez egy ruhán
Keresztülcsillog titkos örömed.','Az özvegy gyászba öltözék;
Kedves férjét eltemeték.
Ő gyászruhát ölt a meghalt után! -
Jó asszony, ez egyet föl se vedd,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,464,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-63','petofi','Igazság! Alszol?','Igazság! alszol? vagy meg is halál?
E férfi méltó volt rá, hogy nyakáról
Aranylánc függjön; s íme a helyett
Ő függ, ő függ... a hóhér kötelén.
S ennek nyakában aranylánc van, pedig
Hóhérkötélen kéne függnie. -
Igazság! alszol? vagy meg is halál?','Igazság! alszol? vagy meg is halál?
E férfi méltó volt rá, hogy nyakáról
Aranylánc függjön; s íme a helyett
Ő függ, ő függ... a hóhér kötelén.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Haza']::text[],'{}'::text[],false,465,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-64','petofi','Az álom...','Az álom
A természetnek legszebb adománya.
Megnyílik ekkor vágyink tartománya.
Mit nem lelünk meg ébren a világon.
Álmában a szegény
Nem fázik és nem éhezik,
Bibor ruhába öltözik,
S jár szép szobák lágy szőnyegén.
Álmában a király
Nem büntet, nem kegyelmez, nem birál...
Nyugalmat élvez.
Álmában az ifju elmegy kedveséhez,
Kiért epeszti tiltott szerelem,
S ott olvad égő kebelén. -
Álmamban én
Rabnemzetek bilincsét tördelem!','Az álom
A természetnek legszebb adománya.
Megnyílik ekkor vágyink tartománya.
Mit nem lelünk meg ébren a világon.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Szerelem']::text[],'{}'::text[],false,466,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-65','petofi','E gazdag úr...','E gazdag úr miként
Gőgösködik, mint nézi le a szegényt!
Ne gőgösködjél, jóbarát,
Azért, hogy most oly jó dolgod van;
Majd e szegény magasabbról néz le rád,
Ha ő a mennyben lesz s te a pokolban.','E gazdag úr miként
Gőgösködik, mint nézi le a szegényt!
Ne gőgösködjél, jóbarát,
Azért, hogy most oly jó dolgod van;','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,467,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-66','petofi','Kereszt','Kereszt jutalma a fáradságoknak,
Mindenfelé keresztet osztogatnak.
Aranykeresztet tűznek a fejedelmek
Jobbágyaik mellére; a földmivesnek
Oszt a természet búzakereszteket...
Fakereszt illet, megváltók, titeket!','Kereszt jutalma a fáradságoknak,
Mindenfelé keresztet osztogatnak.
Aranykeresztet tűznek a fejedelmek
Jobbágyaik mellére; a földmivesnek','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,468,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-67','petofi','Voltak fejedelmek...','Voltak fejedelmek,
Akiknek emlékoszlopot emeltek,
Magast és fényeset,
Mely hirdeté nagyságukat,
Mely hirdeté jóságukat.
És hol van az oszlop?... elesett!
El kellett esnie,
Mert hazugsággal volt tele.
Az idő igaz,
S eldönti, ami nem az.
Ott áll a sír most emléktelenűl,
Az eltörött helyett mást nem tevének...
De nem! hisz örök átka nemzetének
Sötét oszlopként rajta nehezűl.','Voltak fejedelmek,
Akiknek emlékoszlopot emeltek,
Magast és fényeset,
Mely hirdeté nagyságukat,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Haza']::text[],'{}'::text[],false,469,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-68','petofi','Midőn a földön...','Midőn a földön még csak pár ember vala,
Már meghalt egyik a másiknak általa.
Ábelt megölte Kain.
Ha a világ végén majd újolag
Két ember lesz a föld határain,
Ők is bizonnyal így egymásra rontanak,
S az, aki megmarad ott,
Nőül fog venni egy vadállatot.
Talán e vadállatnak méhibül
A réginél szelídebb emberfaj kerül.','Midőn a földön még csak pár ember vala,
Már meghalt egyik a másiknak általa.
Ábelt megölte Kain.
Ha a világ végén majd újolag','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Elmúlás']::text[],'{}'::text[],false,470,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-69','petofi','Kivágom én...','Kivágom én keblemből szívemet,
Ott úgysem okoz mást, csak gyötrelmeket,
Kivágom és a földbe ültetem...
Talán kikél babérfa képiben,
S koszorúja lesz a bajnokoknak,
Kik a szabadságért harcolnak!','Kivágom én keblemből szívemet,
Ott úgysem okoz mást, csak gyötrelmeket,
Kivágom és a földbe ültetem...
Talán kikél babérfa képiben,','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Haza']::text[],'{}'::text[],false,471,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-70','petofi','Fövényszem... Harmatcsepp...','Fövényszem... harmatcsepp... a szikla,. melyet
Ezer villám meg nem rengethet...
Az örökké rengő tenger...
A tiszta napfény és a szennyes ember
És minden, minden e világon
Csak álom, tünedékeny álom.
Ez álma mind a természetnek,
Kit miljom év előtt szender lepett meg,
S ki álmodik
Talán még miljom s miljom évekig.
De fölébred végre,
Egyszerre fölriad,
Fölkeltik egyre rémesb álmai,
És ekkor a borzalom miatt
A semmiség feneketlen tengerébe
Fog ugrani.','Fövényszem... harmatcsepp... a szikla,. melyet
Ezer villám meg nem rengethet...
Az örökké rengő tenger...
A tiszta napfény és a szennyes ember','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,472,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-71','petofi','Fejemben éj van...','Fejemben éj van, éjek éjjele,
S ez éj kisértetekkel van tele;
Agyamban egymást szűlik a gondolatok,
S egymást tépik szét, mint vadállatok.
Lázzal verő szivemnek vére forr,
Mint boszorkány üstjében a bűvös viz.
Gyúlt képzeletem mint meteor
Fut át a világon és magával visz,
Laktársam a kétségbeesés,
Szomszédom a megőrülés.','Fejemben éj van, éjek éjjele,
S ez éj kisértetekkel van tele;
Agyamban egymást szűlik a gondolatok,
S egymást tépik szét, mint vadállatok.','Szalkszentmárton, 1846. március 10. előtt',1846,'1846','{}'::text[],'{}'::text[],false,473,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-72','petofi','Átok és áldás','Legyen átok a földön,
Hol ama fa termett,
Amelyből énnekem
Bölcső készítteték;
Legyen átkozott a kéz,
Mely e fát ülteté,
És átkozott az eső s a napsugár,
Mely e fát felnövelte!... -
De áldás légyen a földön,
Hol ama fa termett,
Melyből nekem majd
Koporsó készűl;
Áldott legyen a kéz,
Mely e fát ülteté,
Áldott az eső s a napsugár,
Mely e fát felnövelte!','Legyen átok a földön,
Hol ama fa termett,
Amelyből énnekem
Bölcső készítteték;','Szalkszentmárton, 1846. március 10. előtt',1846,'1846',array['Természet']::text[],'{}'::text[],false,474,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-73','petofi','Mért vagyok én még a világon...','Mért vagyok én még a világon, ha már
Átéltem minden szenvedéseket?
Végeztem pályám... mert hiszen az ember,
Hogy szenvedjen, csak azért született.
Mért vagyok én még a világon, hisz már
Láttam mindent, mi látható van itt;
Látám a jónak örökös bukását
S a rosznak örök diadalmait.

Hallottam már az éhezők nyögését
S dorbézolási kurjantásokat,
Hallottam már a csalogányt dalolni
És csörömpölni a rabláncokat.
Tudom, hogy így volt ezredév előtt s hogy
Ezred multán is ekkép lenni fog...
Mindent tudok, mindent hallottam, láttam,
Hát mért élek még? mért meg nem halok?

Vagy tán valólag a világ nem ilyen?
Ily szomorúnak én látom csupán?
Én látom így csak, keresztülnézvén a
Kétségbesésnek sötét fátyolán?
Mindegy... elég, hogy én kétségbeestem,
Elég, hogy én elkárhozott vagyok,
Hogy engem éles, égő körmeikkel
Tépnek, szaggatnak a rosz angyalok!

Szakadj meg, szívem! hagyj el engem, élet!
Fogadj öledbe, mély öledbe, föld!
Borúlj reám, sír! és te, fergeteg, jőj,
Hogy rólam a sírhalmot elsöpörd!
Söpörd el s szórd ki összeporlott csontom,
S szórd el csontommal hírem-nevemet...
Ne tudja senki se, hogy egykor ilyen
Megátkozott teremtmény létezett!','Mért vagyok én még a világon, ha már
Átéltem minden szenvedéseket?
Végeztem pályám... mert hiszen az ember,
Hogy szenvedjen, csak azért született.','Pest, 1846. március 10. - április 10.',1846,'1846',array['Haza']::text[],'{}'::text[],false,475,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-74','petofi','Minden virágnak...','Minden virágnak, minden kis fűszálnak
Jut a napból, ha több nem, egy sugár.
Oh szerelem, te szívek napja, szívem
Egy sugárt tőled csak hiába vár?
Nincsen leány, ki engemet szeretne,
Nincsen leány, ki mondaná nekem:
Hideg világ van, lelkedet meghűté,
Jer, melegedj föl forró keblemen!

Nincsen leány, ki mondaná: fáradt vagy,
Bocsásd vállamra bágyadt fejedet!
Nincsen leány, ki véremet lemosná
E homlokról, mely megköveztetett!...
Magam vagyok, mint a szőlő karója,
Melyről leszáradt a zöld venyige;
Madár nem száll rám, csak fölöttem repdes
Sötét eszméim hollóserege.

Igy foly le majd az ifjuság, az élet,
Igy foly le tőlem árván, egyedűl,
Azt veszem észre csak, hogy elfagy vérem
A halál hideg ölelésitül.
S ha meghalok, ha megfagyok: szememre
Megkönnyezetlen szemfedő borúl,
S ültetni nem fog senki egy virágot
A sírra, amely rajtam domborúl.

Ott hamvadok majd egy kopott fejfánál,
Kopott fejfánál, puszta domb alatt;
Nő ott a kóró, mert meg nem tapossa,
Nem jő megnézni senki síromat.
Meglátogatni csak te fogsz, hogy elzúgd
Testvéri búdat, éji fergeteg,
Testvéri búdat, mert hiszen testvére
Voltál te lelkem érzeményinek!','Minden virágnak, minden kis fűszálnak
Jut a napból, ha több nem, egy sugár.
Oh szerelem, te szívek napja, szívem
Egy sugárt tőled csak hiába vár?','Pest, 1846. március 10. - április 10.',1846,'1846',array['Természet','Szerelem','Család']::text[],'{}'::text[],false,476,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1846-184602-75','petofi','A szerelmes tenger','Ült a lyányka boldogan tünődve
Sziklaparton a tenger fölött,
És akit várt, akiről tünődék,
Kedvesének koszorút kötött.

Átellenben kelt az esti csillag,
De a tenger nem gondolt vele;
A9 leányra nézett kék szemével,
S így sohajta hullámkebele:

"Oh mi szép vagy, oh miként szeretlek!
Jőj le, ha van benned irgalom,
Jőj s fürödjél bennem... üdvezűlök,
Hogyha kebled megcsókolhatom.

Jőj le hozzám, szépségek leánya,
Jőj le, és szeress, légy hitvesem;
Földiszítlek, mint menyasszonyát még
Nem diszíté egy királyfi sem.

Fürteidre fölhozom dúsgazdag
Mélységemnek minden gyöngyeit;
S elveszíti ragyogásaiktól
Szeme fényét, aki rád tekint.

Nem, nem, oh rád ne tekintsen senki!
Messze viszlek innen téged el
Napkeletre egy szigetbe, amely
Telve a föld gyönyöreivel.

Ottan minden patak egy szivárvány,
S híg gyémánt a tiszta levegő,
S a mezőnek minden órán új s a
Régieknél szebb virága nő.

Ottan szebb az éj, mint itten a nap,
S szebb a tél, mint itt a kikelet,
S madarak a hópelyhek... mig esnek,
Zengedeznek tündéréneket.

Jőj keblemre, szépségek leánya,
Jőj le, és szeress, légy hitvesem;
Napkeletre szigetembe viszlek,
Ott élünk örök-szerelmesen.

Itt a sajka, ülj beléje, lyányka,
Ringatom majd oly szelídeden,
Hogy elalszol; és mire fölébredsz.
Ott leendesz a szép szigeten."

Esdekelve így beszélt a tenger;
A leány nem érté meg szavát,
Nem fejté meg a rengő haboknak
Suttogó, egyhangú moraját.

És akközben kész lett koszorúja,
S akit várt, az ifju megjöve,
És látá az érkezőt a tenger,
S hah miként fölháborult szive!

Hátha még a többit látta volna...
Eltünének sűrü fák mögé,
S őket a sötétzöld lombozat s az
Éj sötét kárpitja elfödé.

Másnap reggel vitorlás hajón a
Boldog ifju a tengerre szállt;
És a tenger jókedvvel, nyugodtan
Vitte őt a messzeségen át.

"Menj, menj, ifju", gondolá magában,
"Sok szerencsét vándorlásodon;
De halálod lesz az óra, mely e
Lyányhoz téged ismét visszavon.

Kedvezek most, sebesen röpítlek,
Mert a lyánytól messze távozol;
De ha vissza, a leány felé jősz,
Minden vészemmel találkozol."

A leányka ott állt nemsokára,
Ahol tennap koszorút kötött;
Koszorúja összetépve fekvék
Széteresztett fürtei között.

Ottan állt, a tenger s ég közötti
Végtelenben járt tekintete,
Mint elfáradott galamb, amelyet
A sas helyről-helyre kergete.

"Itt volt. Elment, elment mindörökre,
Megcsalt; megcsalt! Engem itt hagyott.
Itt hagyott, oh, engemet... kettőnket:
Engemet és a gyalázatot!"

Igy panaszlá a leány keservét,
És a tenger meghallotta azt,
És egyszerre nagy birodalmában
Minden alvó habot fölriaszt;

És után küldé a hajónak,
Mely a csábitó ifjút vivé,
S a hullámok a hajót s az ifjut
Egy csapással zúzták semmivé.

S szólt a tenger: "Te szegény teremtés,
Mit teszesz most, mondd, hogy mit teszesz?
Megcsalt téged az, akit szerettél,
Én szeretlek s engem nem szeretsz!

És mit ér az élet már tenéked?
Karjaimba vesd le magadat,
Hadd legyek koporsód... eltemetlek,
Tégedet és gyalázatodat."

Amit egykor nem értett a lyányka,
Most megérté a tenger szavát;
Leugrott a szikláról, s a tenger
Eltemette őt s gyalázatát.','Ült a lyányka boldogan tünődve
Sziklaparton a tenger fölött,
És akit várt, akiről tünődék,
Kedvesének koszorút kötött.','Szalkszentmárton, 1846. április 10-24.',1846,'1846',array['Szerelem','Természet','Elmúlás']::text[],'{}'::text[],false,477,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006')
